// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ZZZActivationAssets} from "./ZZZActivationAssets.sol";

/// @notice Fixed, noncustodial deployment helper. Splits Registry initcode;
/// it cannot configure a child, replace one, execute calls or receive funds.
contract ZZZActivationAssetsFactory {
    address public immutable access;
    mapping(address => address) public assetsOf;
    error AlreadyCreated();
    constructor() { access=msg.sender; }
    function create() external returns(address child) {
        if (assetsOf[msg.sender]!=address(0)) revert AlreadyCreated();
        child=address(new ZZZActivationAssets(access,msg.sender));
        assetsOf[msg.sender]=child;
    }
}

src/ZZZActivationEntry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {ZZZModule} from "./base/ZZZModule.sol";
import {ZZZActivationAssets} from "./ZZZActivationAssets.sol";
import {IZZZNFT, IZZZPools, IZZZOracle} from "./interfaces/IZZZ.sol";
import {Ids, PoolConfig} from "./libraries/ZZZTypes.sol";
import {ExactToken} from "./libraries/ExactToken.sol";
import {ExactAsset} from "./libraries/ExactAsset.sol";
import {ZZZContributionPricing} from "./ZZZContributionPricing.sol";
import {IZZZProtocolPolicy} from "./interfaces/IZZZProtocolPolicy.sol";

interface IActivationVault {
    function activate(uint256, bytes32, uint256, uint256, uint128, uint256) external payable;
    function increase(uint256, uint256, uint256, uint128, uint256) external payable;
}
/// @notice Atomic owner-funded ETH/ZZZ contribution into the permanent LP Vault.
/// The Registry creates this immutable child. No arbitrary executor, recipient,
/// user-supplied USD value, NFT custody, permit or token rescue path exists.
contract ZZZActivationEntry is ZZZModule, ReentrancyGuard {
    /// @notice Direct pair-input ABI. Historical routed requests are incompatible.
    uint256 public constant ENTRY_ROUTING_VERSION = 3;
    /// @notice Signed contribution policy: no legacy unbounded entry fallback.
    uint256 public constant REVIEW_POLICY_VERSION = 2;
    address public immutable registry;
    ZZZActivationAssets public immutable activationAssets;

    struct Request {
        uint256 nftId;
        bytes32 poolId;
        address sourceAsset; // Zero is native ETH, distinct from every ERC20.
        uint256 amountIn;
        uint128 minimumLiquidity;
        uint256 deadline;
        bool increase;
    }
    struct Context {
        address owner;
        uint256 nftId;
        bytes32 callHash;
        bytes32 poolId;
        uint256 amount0;
        uint256 amount1;
        uint256 grossUSD;
    }
    Context private context;
    event SourceContributed(address indexed owner, uint256 indexed nftId, bytes32 indexed poolId,
        address sourceAsset, uint256 sourceAmount, uint256 grossUSD, address output, uint256 outputAmount, bool increase);

    constructor(address controller, address poolRegistry, address assets) ZZZModule(controller) {
        if (poolRegistry == address(0) || msg.sender != poolRegistry || assets.code.length == 0 ||
            ZZZActivationAssets(assets).registry() != poolRegistry ||
            address(ZZZActivationAssets(assets).access()) != controller) revert InvalidConfiguration();
        registry = poolRegistry;
        activationAssets = ZZZActivationAssets(assets);
    }
    function _owner(uint256 id) private view returns (address) {
        return IZZZNFT(access.module(Ids.NFT)).ownerOf(id);
    }
    function _vault() private view returns (address vault) {
        vault = access.module(Ids.VAULT);
        if (!access.isSealed() || access.module(Ids.POOLS) != registry || vault.code.length == 0) revert InvalidConfiguration();
    }

    /// @notice Only the canonical Vault may authorize this exact active call.
    /// ERC721 token/operator approval is never contribution authority.
    function validateOwner(uint256 id, bytes32 vaultCallHash) external view {
        Context memory c = context;
        if (msg.sender != _vault() || c.owner == address(0) || c.nftId != id ||
            c.callHash != vaultCallHash || _owner(id) != c.owner) revert Unauthorized();
    }
    /// @notice Only Registry valuation may replace pair-input value with the
    /// original, proven source value. An active mismatch MUST NOT fall back.
    function sourceValue(bytes32 poolId, uint256 amount0, uint256 amount1) external view returns (uint256) {
        if (msg.sender != registry) revert Unauthorized();
        Context memory c = context;
        if (c.owner == address(0)) return 0;
        if (c.poolId != poolId || c.amount0 != amount0 || c.amount1 != amount1 ||
            _owner(c.nftId) != c.owner) revert InvalidState();
        return c.grossUSD;
    }

    function _pricing() private view returns(ZZZContributionPricing) {
        return ZZZContributionPricing(IZZZOracle(access.module(Ids.ORACLE)).contributionPricing());
    }
    /// @notice The fixed pricing companion may adopt only this exact live Vault context.
    function pricingContext(uint256 id,bytes32 pool,uint256 packed,uint256 gross) external view returns(bool) {
        if (msg.sender != address(_pricing())) revert Unauthorized();
        Context memory c = context;
        return c.owner != address(0) && c.nftId == id && c.poolId == pool && c.grossUSD == gross &&
            c.amount0 <= type(uint128).max && c.amount1 <= type(uint128).max &&
            packed == (c.amount0 | (c.amount1 << 128)) && _owner(id) == c.owner;
    }

    /// @notice The signed maximum covers Vault balancing and placement loss; gas is separate.
    /// A tighter execution-time policy is allowed, but never a wider one than reviewed.
    function executeReviewed(Request calldata request, uint16 maximumLossBps,bytes32 expectedContributionPolicy)
        external payable live operating principalOperating nonReentrant {
        _deadline(request.deadline);
        IZZZProtocolPolicy policySource=IZZZProtocolPolicy(access.protocolPolicy());
        if(expectedContributionPolicy==bytes32(0) || policySource.entryFingerprint()!=expectedContributionPolicy)
            revert InvalidState();
        IZZZProtocolPolicy.EntryPolicy memory entryTerms=policySource.entryPolicy();
        address vault = _vault();
        if (request.amountIn == 0 || request.minimumLiquidity == 0 || _owner(request.nftId) != msg.sender) revert Unauthorized();
        PoolConfig memory pool = IZZZPools(registry).accounting(request.poolId);
        if (!pool.depositsEnabled || !pool.operationsEnabled ||
            pool.key.currency0 == pool.key.currency1) revert InvalidConfiguration();
        address source = request.sourceAsset;
        if (!activationAssets.isContributionAsset(source)) revert InvalidConfiguration();
        if (source != pool.key.currency0 && source != pool.key.currency1) revert InvalidConfiguration();
        if (msg.value != (source == address(0) ? request.amountIn : 0)) revert InvalidAmount();
        uint256 nativeBaseline = address(this).balance - msg.value;
        uint256 sourceBaseline = ExactAsset.balance(source,address(this)) - (source == address(0) ? msg.value : 0);
        // Freeze source + LP-pair prices BEFORE token pulls or approvals can
        // call external code. Both bounds come from two sources.
        uint256 grossUSD = activationAssets.value(source, request.amountIn);
        if (grossUSD == 0 || grossUSD < (request.increase?entryTerms.minGrowthUSD:entryTerms.minActivationUSD))
            revert InvalidAmount();
        if (_pricing().beginEntryReviewed(request.nftId,request.poolId,source,request.amountIn,maximumLossBps,
            expectedContributionPolicy) != grossUSD) revert InvalidState();
        if (source != address(0)) ExactToken.pull(source, msg.sender, request.amountIn);
        if (_owner(request.nftId) != msg.sender) revert Unauthorized();
        uint256 amount0 = source == pool.key.currency0 ? request.amountIn : 0;
        uint256 amount1 = source == pool.key.currency1 ? request.amountIn : 0;
        bytes memory payload = request.increase
            ? abi.encodeCall(IActivationVault.increase, (request.nftId, amount0, amount1, request.minimumLiquidity, request.deadline))
            : abi.encodeCall(IActivationVault.activate, (request.nftId, request.poolId, amount0, amount1, request.minimumLiquidity, request.deadline));
        // Token approval can call arbitrary token code. Context must remain
        // inactive until the immediate Vault call, whose own guard then protects
        // contribution valuation against unrelated callback-driven joins.
        ExactAsset.approve(source,vault, request.amountIn);
        if (_owner(request.nftId) != msg.sender) revert Unauthorized();
        context = Context(msg.sender, request.nftId, keccak256(payload), request.poolId, amount0, amount1, grossUSD);
        (bool success, bytes memory result) = vault.call{value: source == address(0) ? request.amountIn : 0}(payload);
        if (!success) assembly ("memory-safe") { revert(add(result, 32), mload(result)) }
        delete context;
        ExactAsset.approve(source,vault, 0);
        if (_owner(request.nftId) != msg.sender || ExactAsset.balance(source,address(this)) != sourceBaseline || address(this).balance != nativeBaseline) revert InvalidState();
        _pricing().endEntry();
        if(policySource.entryFingerprint()!=expectedContributionPolicy)revert InvalidState();
        emit SourceContributed(msg.sender, request.nftId, request.poolId, request.sourceAsset,
            request.amountIn, grossUSD, source, request.amountIn, request.increase);
    }
}

src/ZZZBuyback.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {ZZZModule} from "./base/ZZZModule.sol";
import {Ids, PoolConfig} from "./libraries/ZZZTypes.sol";
import {IZZZFees, IZZZLiquidity, IZZZPools, IZZZOracle, IBurnable} from "./interfaces/IZZZ.sol";
import {ExactAsset} from "./libraries/ExactAsset.sol";

contract ZZZBuyback is ZZZModule, ReentrancyGuard {
    /// @notice Fixed deployment ZZZ identity; issuer migration requires exit/redeployment.
    address public immutable zzz;
    uint256 public maxTradeUSD;
    /// @notice Immediate operating limit within the reviewed governance ceiling.
    /// Zero stops new buybacks without consulting an oracle or releasing reserves.
    uint256 public operatingTradeUSD;
    event BoughtAndBurned(address indexed input, uint256 inputAmount, uint256 zzzBurned);
    event OperatingTradeLimitChanged(uint256 previous, uint256 current);
    event MaximumTradeLimitChanged(uint256 previous,uint256 current,bytes32 reviewHash);
    constructor(address controller, address zzzToken, uint256 maximumTradeUSD) ZZZModule(controller) {
        if (zzzToken.code.length == 0 || maximumTradeUSD == 0 || maximumTradeUSD > type(uint128).max) revert InvalidConfiguration();
        zzz = zzzToken;
        maxTradeUSD = maximumTradeUSD;
        operatingTradeUSD = maximumTradeUSD;
    }
    receive() external payable {
        if (msg.sender != access.module(Ids.FEES)) revert Unauthorized();
    }
    /// @notice Future-only sizing; cannot change ZZZ, reserves, recipients or allocation.
    function setMaximumTradeUSD(uint256 limit,bytes32 reviewHash) external onlyGovernance operating nonReentrant {
        if(limit == 0 || limit > type(uint128).max || limit < operatingTradeUSD || reviewHash == bytes32(0))
            revert InvalidConfiguration();
        emit MaximumTradeLimitChanged(maxTradeUSD,limit,reviewHash);
        maxTradeUSD = limit;
    }
    /// @notice Changes execution policy only; cannot withdraw funds, change the
    /// revenue split or exceed the hard ceiling. Available during an ordinary
    /// pause, but not preparation or a canonical handoff lifecycle lock.
    function setOperatingTradeUSD(uint256 limit) external onlyGovernance operating nonReentrant {
        if (limit > maxTradeUSD) revert InvalidConfiguration();
        uint256 previous = operatingTradeUSD;
        operatingTradeUSD = limit;
        emit OperatingTradeLimitChanged(previous, limit);
    }
    function execute(address token, uint256 amount, bytes32 poolId, uint256 deadline) external onlyKeeper live operating nonReentrant {
        _deadline(deadline);
        if (amount == 0 || operatingTradeUSD == 0) revert InvalidAmount();
        IZZZOracle oracle = IZZZOracle(access.module(Ids.ORACLE));
        // The maximum spend must hold at either admitted source price. Ordinary
        // Oracle.value is the lower mark for minimum contributions/display; it
        // can understate a trade budget. Round the upper input value upward.
        (, uint256 upper,) = oracle.priceBounds(token);
        if (Math.mulDiv(amount, upper, 10 ** oracle.tokenDecimals(token), Math.Rounding.Ceil) > operatingTradeUSD)
            revert InvalidAmount();
        uint256 beforeZZZ = IERC20(zzz).balanceOf(address(this));
        uint256 beforeInput = ExactAsset.balance(token,address(this));
        IZZZFees(access.module(Ids.FEES)).releaseBuyback(token, amount);
        if (ExactAsset.balance(token,address(this)) != beforeInput + amount) revert InvalidState();
        uint256 acquired = amount;
        if (token != zzz) {
            PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
            bool zeroForOne = c.key.currency0 == token && c.key.currency1 == zzz;
            if (!zeroForOne && !(c.key.currency1 == token && c.key.currency0 == zzz)) revert InvalidConfiguration();
            uint256 minimum = Math.mulDiv(oracle.quote(token, zzz, amount), 10000 - c.maxSlippageBps, 10000);
            address manager = access.module(Ids.LIQUIDITY);
            ExactAsset.approve(token,manager, amount);
            acquired = IZZZLiquidity(manager).swap{value: token == address(0) ? amount : 0}(poolId, zeroForOne, amount, minimum, deadline);
            ExactAsset.approve(token,manager, 0);
            if (ExactAsset.balance(token,address(this)) != beforeInput) revert InvalidState();
        }
        if (IERC20(zzz).balanceOf(address(this)) != beforeZZZ + acquired) revert InvalidState();
        uint256 supplyBefore = IBurnable(zzz).totalSupply();
        IBurnable(zzz).burn(acquired);
        if (IBurnable(zzz).totalSupply() + acquired != supplyBefore ||
            IERC20(zzz).balanceOf(address(this)) != beforeZZZ) revert InvalidState();
        emit BoughtAndBurned(token, amount, acquired);
        if (!access.keeperAuthorized(msg.sender) || access.paused()) revert Unauthorized();
    }
}

src/ZZZCanonicalHandoff.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IZZZAccess, IZZZVault} from "./interfaces/IZZZ.sol";
import {IZZZCanonicalModule} from "./interfaces/IZZZCanonical.sol";
import {Ids} from "./libraries/ZZZTypes.sol";
import {IZZZProtocolPolicy} from "./interfaces/IZZZProtocolPolicy.sol";

interface ICanonicalController is IZZZAccess {
    function bootstrap() external view returns (address);
    function preparationHash() external view returns (bytes32);
    function preparationReadyDestination() external view returns (bool);
    function preparationNotice() external view returns (uint256, address, bytes32, bytes32);
    function canonicalTransition(uint8 state, bool settling, bool clearPreparation) external;
}

interface ICanonicalHelpers {
    function canonicalModule() external view returns (address);
    function royaltyRewards() external view returns (address);
    function canonicalRetire() external;
}

interface ICancelledRoyaltyHop {
    function validateCancelledRoyaltyHop() external view returns(address);
}

interface ICancelledRoyaltyLedger {
    function royaltiesOpen() external view returns(bool);
    function isAsset(address) external view returns(bool);
    function activationCount() external view returns(uint256);
    function totalWeight() external view returns(uint256);
    function sync(address) external returns(uint256);
    function canonicalRecoverCancelled(address,address) external returns(uint256);
}
interface ICanonicalExactLPProfile {
    function ACCOUNTING_VERSION() external view returns(uint256);
    function LP_ALLOCATION_VERSION() external view returns(uint256);
}

/// @notice Fixed, bounded handoff coordinator. This first transport is direct
/// same-chain custody with atomic retirement/activation. It cannot attest remote
/// consensus or move assets through an unqualified cross-chain provider.
/// Governance cannot supply accounting rows or use a generic withdrawal target.
contract ZZZCanonicalHandoff is ReentrancyGuard {
    uint256 public constant SLOTS = 6;
    uint256 public constant MAX_ROWS = 8;
    bytes32 public constant SCHEMA = keccak256("ZZZ_CANONICAL_SAME_CHAIN_EXACT_LP_V9");
    // Numeric values are wire-compatible; coordinator phases and Access states
    // are separate state machines. Constants add no public getter or storage.
    uint8 private constant PHASE_IDLE = 0;
    uint8 private constant PHASE_EXPORTING = 1;
    uint8 private constant PHASE_IMPORTED_AWAITING_BACKING = 2;
    uint8 private constant PHASE_RETIRED = 3;
    uint8 private constant PHASE_IMPORTING = 4;
    uint8 private constant PHASE_ACTIVE_REPLACEMENT = 5;
    uint8 private constant PHASE_ABORTING = 6;
    uint8 private constant PHASE_CANCELLED_IMPORT = 7;
    uint8 private constant PHASE_SETTLING = 8;
    uint8 private constant STATE_OPERATING = 0;
    uint8 private constant STATE_FROZEN = 1;
    uint8 private constant STATE_IMPORTING = 2;
    uint8 private constant STATE_RETIRED = 3;
    uint8 private constant STATE_CANCELLED = 4;
    uint8 private constant DOMAIN_NFT = 0;
    uint8 private constant DOMAIN_VAULT = 1;
    uint8 private constant DOMAIN_MEMBERSHIP = 2;
    uint8 private constant DOMAIN_LP_REWARDS = 3;
    uint8 private constant DOMAIN_ROYALTIES = 4;
    uint8 private constant DOMAIN_FEES = 5;
    ICanonicalController public immutable access;
    // 0 idle, 1 frozen/exporting, 2 imported, 3 retired, 4 importing,
    // 5 active replacement, 6 aborting, 7 cancelled replacement, 8 captured/settling.
    uint8 public phase;
    uint8 public settlementCursor;
    address public incomingSource;
    address public destinationController;
    bytes32 public handoffId;
    bytes32 public stateRoot;
    bool public importComplete;
    uint256[6] public recordCount;
    uint256[6] public assetCount;
    uint256[6] public exportCursor;
    uint256[6] public importCursor;
    bytes32[6] public exportRoot;
    bytes32[6] public importRoot;
    mapping(uint8 => mapping(uint256 => bool)) public funded;
    mapping(uint8 => mapping(uint256 => bool)) public incomingFunded;
    mapping(uint8 => mapping(uint256 => bool)) public returned;
    bytes32 private destinationDeployment;
    address private cancelledRoyaltyRoute;
    error Unauthorized();
    error InvalidState();
    error InvalidRecord();
    error InvalidBacking();
    error UnsupportedTransport();
    event ImportPrepared(address indexed sourceController);
    event Frozen(bytes32 indexed handoff, address indexed destination);
    event DomainSettled(bytes32 indexed handoff, uint8 indexed slot);
    event RecordExported(bytes32 indexed handoff, uint8 indexed slot, uint256 indexed row, bytes record);
    event SnapshotCommitted(bytes32 indexed handoff, bytes32 stateRoot);
    event RecordImported(bytes32 indexed handoff, uint8 indexed slot, uint256 indexed row);
    event BackingTransferred(
        bytes32 indexed handoff, uint8 indexed slot, uint256 indexed index, address asset, uint256 amount
    );
    event Retired(bytes32 indexed handoff, address indexed successor, bytes32 stateRoot);
    event Activated(bytes32 indexed handoff, address indexed source, bytes32 stateRoot);
    event AbortStarted(bytes32 indexed handoff);
    event BackingReturned(bytes32 indexed handoff, uint8 indexed slot, uint256 indexed index);
    event Aborted(bytes32 indexed handoff);
    event CancelledRoyaltyReturnAdvanced(address indexed previousController,address indexed nextController);
    event CancelledRoyaltiesRecovered(address indexed asset,address indexed controller,address indexed receiver,
        uint256 amount,uint256 activeCount,uint256 activeWeight,bytes32 reviewHash);

    constructor(address controller) {
        access = ICanonicalController(controller);
    }
    modifier governance() {
        if (msg.sender != access.governance() || !access.isSealed()) revert Unauthorized();
        _;
    }

    function moduleAt(uint8 slot) public view returns (address) {
        if (slot == DOMAIN_NFT) return access.module(Ids.NFT_CANONICAL);
        if (slot == DOMAIN_VAULT || slot == DOMAIN_LP_REWARDS) return ICanonicalHelpers(
            access.module(slot == DOMAIN_VAULT ? Ids.VAULT : Ids.REWARDS)).canonicalModule();
        if (slot == DOMAIN_MEMBERSHIP) return access.module(Ids.MEMBERSHIP);
        if (slot == DOMAIN_ROYALTIES) return ICanonicalHelpers(access.module(Ids.NFT)).royaltyRewards();
        if (slot == DOMAIN_FEES) return access.module(Ids.FEES_CANONICAL);
        revert InvalidState();
    }

    function _module(uint8 slot) private view returns (IZZZCanonicalModule) {
        return IZZZCanonicalModule(moduleAt(slot));
    }

    function _peer(address controller) private view returns (ZZZCanonicalHandoff) {
        return ZZZCanonicalHandoff(IZZZAccess(controller).canonicalHandoff());
    }
    function _exactLPProfile(address controller) private view {
        IZZZAccess target = IZZZAccess(controller);
        if (ICanonicalExactLPProfile(target.module(Ids.VAULT)).ACCOUNTING_VERSION() != 7 ||
            ICanonicalExactLPProfile(target.module(Ids.REWARDS)).LP_ALLOCATION_VERSION() != 1) revert InvalidState();
    }

    /// @notice Review commitment to the exact destination controller, code,
    /// bound modules and immutable helpers. Review still has to establish that
    /// the selected implementation is safe; a code hash is not a security proof.
    function deploymentCommitment() public view returns (bytes32 result) {
        if (!access.isSealed()) revert InvalidState();
        _exactLPProfile(address(access));
        result = keccak256(
            abi.encode(
                SCHEMA,
                block.chainid,
                address(access),
                address(this),
                address(access).codehash,
                address(this).codehash,
                incomingSource
            )
        );
        bytes32[16] memory ids = [
            Ids.VAULT,
            Ids.NFT,
            Ids.LIQUIDITY,
            Ids.REWARDS,
            Ids.MEMBERSHIP,
            Ids.FEES,
            Ids.STRATEGY,
            Ids.COMPOUNDER,
            Ids.BUYBACK,
            Ids.MIGRATION,
            Ids.ORACLE,
            Ids.POOLS,
            Ids.CANONICAL,
            Ids.NFT_CANONICAL,
            Ids.VAULT_CANONICAL,
            Ids.FEES_CANONICAL
        ];
        for (uint256 i; i < ids.length; ++i) {
            address target = access.module(ids[i]);
            if (target.code.length == 0) revert InvalidState();
            result = keccak256(abi.encode(result, ids[i], target, target.codehash));
        }
        for (uint8 slot; slot < SLOTS; ++slot) {
            address target = moduleAt(slot);
            result = keccak256(abi.encode(result, slot, target, target.codehash));
        }
        address policy = access.protocolPolicy();
        result = keccak256(abi.encode(result,policy,policy.codehash,
            IZZZProtocolPolicy(policy).PROTOCOL_POLICY_VERSION(),IZZZProtocolPolicy(policy).configurationHash()));
    }

    /// @notice Only an unused, unsealed deployment can become an inert importer.
    /// Its ordinary economic entrypoints remain unavailable until activation.
    function prepareImport(address sourceController) external nonReentrant {
        if (
            access.isSealed() || msg.sender != access.bootstrap() || phase != PHASE_IDLE
                || sourceController == address(access) || sourceController.code.length == 0
                || !IZZZAccess(sourceController).isSealed()
        ) revert Unauthorized();
        if (IZZZVault(access.module(Ids.VAULT)).canonicalChainId() != block.chainid) revert UnsupportedTransport();
        if (_peer(sourceController).SCHEMA() != SCHEMA) revert UnsupportedTransport();
        _exactLPProfile(sourceController);
        _exactLPProfile(address(access));
        incomingSource = sourceController;
        phase = PHASE_IMPORTING;
        access.canonicalTransition(STATE_IMPORTING, false, false);
        emit ImportPrepared(sourceController);
    }

    function freeze() external governance nonReentrant {
        if (
            access.lpExitStarted() || (phase != PHASE_IDLE && phase != PHASE_ACTIVE_REPLACEMENT) || !access.preparationActive()
                || access.canonicalState() != STATE_OPERATING || !access.preparationReadyDestination()
        ) {
            revert InvalidState();
        }
        (uint256 chain, address destination, bytes32 deployment,) = access.preparationNotice();
        if (chain != block.chainid) revert UnsupportedTransport();
        ZZZCanonicalHandoff peer = _peer(destination);
        if (
            !IZZZAccess(destination).isSealed() || peer.SCHEMA() != SCHEMA || peer.phase() != PHASE_IMPORTING
                || peer.incomingSource() != address(access) || peer.deploymentCommitment() != deployment
        ) {
            revert InvalidState();
        }
        if (IZZZVault(IZZZAccess(destination).module(Ids.VAULT)).canonicalChainId() != block.chainid) {
            revert UnsupportedTransport();
        }
        // Every bucket must be parked and have no active custody handoff.
        // Capture enforces that boundary; no retired v3 channel is admitted.
        destinationController = destination;
        destinationDeployment = deployment;
        handoffId = keccak256(
            abi.encode(
                SCHEMA,
                block.chainid,
                address(access),
                address(this),
                destination,
                address(peer),
                access.preparationHash(),
                deployment
            )
        );
        phase = PHASE_SETTLING;
        settlementCursor = 0;
        stateRoot = bytes32(0);
        // Establish the guard BEFORE any external balance observation. Capture
        // every module first, then process only those immutable cutoffs.
        access.canonicalTransition(STATE_FROZEN, false, false);
        for (uint8 slot; slot < SLOTS; ++slot) {
            _module(slot).canonicalCapture();
        }
        for (uint8 slot; slot < SLOTS; ++slot) {
            recordCount[slot] = _module(slot).canonicalCount();
            assetCount[slot] = _module(slot).canonicalAssetCount();
            if (recordCount[slot] == 0 || assetCount[slot] > 256) {
                revert InvalidState();
            }
            exportCursor[slot] = 0;
            exportRoot[slot] = bytes32(0);
            for (uint256 index; index < assetCount[slot]; ++index) {
                funded[slot][index] = false;
                returned[slot][index] = false;
            }
        }
        peer.bindFrozen(handoffId);
        emit Frozen(handoffId, destination);
    }

    /// @notice Process each captured domain exactly once in fixed order. No
    /// export, funding or activation is possible until all six have settled.
    /// Cutoffs were captured atomically at freeze; later receipts stay outside
    /// this snapshot even if the operator stops between settlement calls.
    function settle(uint8 slot) external nonReentrant {
        if (phase != PHASE_SETTLING || slot != settlementCursor || slot >= SLOTS) revert InvalidState();
        access.canonicalTransition(STATE_FROZEN, true, false);
        _module(slot).canonicalSettle();
        access.canonicalTransition(STATE_FROZEN, false, false);
        settlementCursor = slot + 1;
        if (settlementCursor == SLOTS) phase = PHASE_EXPORTING;
        emit DomainSettled(handoffId, slot);
    }

    function bindFrozen(bytes32 id) external {
        if (phase != PHASE_IMPORTING || msg.sender != address(_peer(incomingSource)) || handoffId != bytes32(0)) {
            revert Unauthorized();
        }
        handoffId = id;
        ZZZCanonicalHandoff source = ZZZCanonicalHandoff(msg.sender);
        if (source.handoffId() != id || source.destinationController() != address(access)) revert InvalidState();
        for (uint8 slot; slot < SLOTS; ++slot) {
            recordCount[slot] = source.recordCount(slot);
            assetCount[slot] = source.assetCount(slot);
        }
    }

    function _next(bytes32 previous, uint8 slot, uint256 row, bytes memory record) private view returns (bytes32) {
        return keccak256(abi.encode(handoffId, slot, row, previous, keccak256(record)));
    }

    function exportRows(uint8 slot, uint256 count) external nonReentrant {
        if (
            phase != PHASE_EXPORTING || slot >= SLOTS || count == 0 || count > MAX_ROWS
                || exportCursor[slot] + count > recordCount[slot]
        ) revert InvalidState();
        uint256 end = exportCursor[slot] + count;
        for (uint256 row = exportCursor[slot]; row < end; ++row) {
            bytes memory record = _module(slot).canonicalExport(row);
            exportRoot[slot] = _next(exportRoot[slot], slot, row, record);
            emit RecordExported(handoffId, slot, row, record);
        }
        exportCursor[slot] = end;
        bool complete = true;
        for (uint8 i; i < SLOTS; ++i) {
            if (exportCursor[i] != recordCount[i]) complete = false;
        }
        if (complete) {
            stateRoot = keccak256(abi.encode(handoffId, recordCount, assetCount, exportRoot));
            emit SnapshotCommitted(handoffId, stateRoot);
        }
    }

    function importRows(uint8 slot, bytes[] calldata records) external nonReentrant {
        if (
            phase != PHASE_IMPORTING || slot >= SLOTS || records.length == 0 || records.length > MAX_ROWS
                || importCursor[slot] + records.length > recordCount[slot]
        ) revert InvalidState();
        ZZZCanonicalHandoff source = _peer(incomingSource);
        if (source.phase() != PHASE_EXPORTING || source.stateRoot() == bytes32(0) || source.handoffId() != handoffId) {
            revert InvalidState();
        }
        IZZZCanonicalModule sourceModule = IZZZCanonicalModule(source.moduleAt(slot));
        for (uint256 i; i < records.length; ++i) {
            uint256 row = importCursor[slot]++;
            if (keccak256(records[i]) != keccak256(sourceModule.canonicalExport(row))) revert InvalidRecord();
            _module(slot).canonicalImport(row, records[i]);
            importRoot[slot] = _next(importRoot[slot], slot, row, records[i]);
            emit RecordImported(handoffId, slot, row);
        }
    }

    function completeImport() external nonReentrant {
        if (phase != PHASE_IMPORTING) revert InvalidState();
        ZZZCanonicalHandoff source = _peer(incomingSource);
        for (uint8 slot; slot < SLOTS; ++slot) {
            if (
                importCursor[slot] != recordCount[slot] || importRoot[slot] != source.exportRoot(slot)
                    || _module(slot).canonicalCount() != recordCount[slot]
                    || _module(slot).canonicalAssetCount() != assetCount[slot]
            ) revert InvalidRecord();
        }
        stateRoot = keccak256(abi.encode(handoffId, recordCount, assetCount, importRoot));
        if (source.phase() != PHASE_EXPORTING || stateRoot == bytes32(0) || stateRoot != source.stateRoot()) {
            revert InvalidRecord();
        }
        importComplete = true;
        phase = PHASE_IMPORTED_AWAITING_BACKING;
    }

    function _balance(address asset, address owner) private view returns (uint256) {
        return asset == address(0) ? owner.balance : IERC20(asset).balanceOf(owner);
    }

    function fund(uint8 slot, uint256 index) external nonReentrant {
        if (phase != PHASE_EXPORTING || slot >= SLOTS || index >= assetCount[slot] || funded[slot][index]) {
            revert InvalidState();
        }
        ZZZCanonicalHandoff peer = _peer(destinationController);
        if (peer.phase() != PHASE_IMPORTED_AWAITING_BACKING || peer.stateRoot() != stateRoot || stateRoot == bytes32(0))
        revert InvalidState();
        (address asset, uint256 amount) = _module(slot).canonicalBacking(index);
        IZZZCanonicalModule destination = IZZZCanonicalModule(peer.moduleAt(slot));
        (address otherAsset, uint256 otherAmount) = destination.canonicalBacking(index);
        if (otherAsset != asset || otherAmount != amount) revert InvalidBacking();
        funded[slot][index] = true;
        uint256 beforeBalance = _balance(asset, address(destination));
        _module(slot).canonicalRelease(index, address(destination));
        if (_balance(asset, address(destination)) != beforeBalance + amount) revert InvalidBacking();
        peer.acceptFunding(slot, index);
        emit BackingTransferred(handoffId, slot, index, asset, amount);
    }

    function acceptFunding(uint8 slot, uint256 index) external nonReentrant {
        ZZZCanonicalHandoff source = _peer(incomingSource);
        if (
            msg.sender != address(source) || phase != PHASE_IMPORTED_AWAITING_BACKING || slot >= SLOTS
                || index >= assetCount[slot] || incomingFunded[slot][index] || !source.funded(slot, index)
        ) revert Unauthorized();
        incomingFunded[slot][index] = true;
        _module(slot).canonicalAccept(index, source.moduleAt(slot));
    }

    function _allFunded() private view {
        for (uint8 slot; slot < SLOTS; ++slot) {
            for (uint256 index; index < assetCount[slot]; ++index) {
                if (!funded[slot][index]) revert InvalidBacking();
            }
        }
    }

    function commit() external governance nonReentrant {
        if (phase != PHASE_EXPORTING || stateRoot == bytes32(0)) revert InvalidState();
        ZZZCanonicalHandoff peer = _peer(destinationController);
        if (
            peer.phase() != PHASE_IMPORTED_AWAITING_BACKING || peer.stateRoot() != stateRoot
                || peer.deploymentCommitment() != destinationDeployment
        ) revert InvalidState();
        _allFunded();
        // Both transitions are atomic on this chain. A failed readiness or
        // backing check rolls retirement back; no competing successor is added.
        phase = PHASE_RETIRED;
        access.canonicalTransition(STATE_RETIRED, false, false);
        ICanonicalHelpers(access.module(Ids.NFT)).canonicalRetire();
        peer.activate();
        emit Retired(handoffId, destinationController, stateRoot);
    }

    function activate() external nonReentrant {
        ZZZCanonicalHandoff source = _peer(incomingSource);
        if (
            msg.sender != address(source) || phase != PHASE_IMPORTED_AWAITING_BACKING || source.phase() != PHASE_RETIRED
                || source.destinationController() != address(access) || source.stateRoot() != stateRoot
        ) {
            revert Unauthorized();
        }
        for (uint8 slot; slot < SLOTS; ++slot) {
            for (uint256 index; index < assetCount[slot]; ++index) {
                if (!incomingFunded[slot][index]) revert InvalidBacking();
            }
            _module(slot).canonicalValidate();
        }
        for (uint8 slot; slot < SLOTS; ++slot) {
            _module(slot).canonicalActivate();
        }
        phase = PHASE_ACTIVE_REPLACEMENT;
        access.canonicalTransition(STATE_OPERATING, false, true);
        emit Activated(handoffId, incomingSource, stateRoot);
    }

    function abort() external governance nonReentrant {
        if (phase != PHASE_EXPORTING && phase != PHASE_SETTLING) revert InvalidState();
        phase = PHASE_ABORTING;
        _peer(destinationController).cancelImport();
        emit AbortStarted(handoffId);
    }

    function cancelImport() external nonReentrant {
        ZZZCanonicalHandoff source = _peer(incomingSource);
        if (
            msg.sender != address(source) || source.phase() != PHASE_ABORTING
                || (phase != PHASE_IMPORTING && phase != PHASE_IMPORTED_AWAITING_BACKING)
        ) {
            revert Unauthorized();
        }
        phase = PHASE_CANCELLED_IMPORT;
        access.canonicalTransition(STATE_CANCELLED, false, false);
    }

    function returnFunds(uint8 slot, uint256 index) external nonReentrant {
        if (
            phase != PHASE_ABORTING || slot >= SLOTS || index >= assetCount[slot] || !funded[slot][index]
                || returned[slot][index]
        ) revert InvalidState();
        ZZZCanonicalHandoff peer = _peer(destinationController);
        if (peer.phase() != PHASE_CANCELLED_IMPORT) revert InvalidState();
        (address asset, uint256 amount) = _module(slot).canonicalBacking(index);
        returned[slot][index] = true;
        uint256 beforeBalance = _balance(asset, moduleAt(slot));
        peer.returnFunding(slot, index);
        if (_balance(asset, moduleAt(slot)) != beforeBalance + amount) revert InvalidBacking();
        _module(slot).canonicalRestore(index, peer.moduleAt(slot));
        emit BackingReturned(handoffId, slot, index);
    }

    function returnFunding(uint8 slot, uint256 index) external nonReentrant {
        ZZZCanonicalHandoff source = _peer(incomingSource);
        if (
            msg.sender != address(source) || phase != PHASE_CANCELLED_IMPORT || source.phase() != PHASE_ABORTING
                || !incomingFunded[slot][index] || !source.returned(slot, index)
        ) revert Unauthorized();
        incomingFunded[slot][index] = false;
        _module(slot).canonicalRelease(index, source.moduleAt(slot));
    }

    function finishAbort() external governance nonReentrant {
        if (phase != PHASE_ABORTING || _peer(destinationController).phase() != PHASE_CANCELLED_IMPORT) {
            revert InvalidState();
        }
        for (uint8 slot; slot < SLOTS; ++slot) {
            for (uint256 index; index < assetCount[slot]; ++index) {
                if (funded[slot][index] && !returned[slot][index]) revert InvalidBacking();
            }
            _module(slot).canonicalValidate();
        }
        phase = incomingSource == address(0) ? PHASE_IDLE : PHASE_ACTIVE_REPLACEMENT;
        access.canonicalTransition(STATE_OPERATING, false, true);
        emit Aborted(handoffId);
    }

    /// @notice Only an authenticated descendant of the original restored
    /// source can receive cancelled royalties. This cursor never accepts input.
    function cancelledRoyaltyReturnController() public view returns(address) {
        return cancelledRoyaltyRoute == address(0) ? incomingSource : cancelledRoyaltyRoute;
    }

    function _cancelledRestored() private view {
        if(phase != PHASE_CANCELLED_IMPORT || access.canonicalState() != STATE_CANCELLED) revert InvalidState();
        uint8 sourceState = IZZZAccess(incomingSource).canonicalState();
        if(sourceState != STATE_OPERATING && sourceState != STATE_RETIRED) revert InvalidState();
    }

    function _recoveryPeer(address controller) private view returns(ZZZCanonicalHandoff peer) {
        peer = _peer(controller);
        if(peer.SCHEMA() != SCHEMA || address(peer.access()) != controller) revert InvalidState();
    }

    /// @notice Advance ONE immutable retired-source hop. Repeated calls follow
    /// arbitrarily long reviewed histories without unbounded execution.
    function advanceCancelledRoyaltyReturn() external nonReentrant {
        _cancelledRestored();
        address previous = cancelledRoyaltyReturnController();
        address next = ICancelledRoyaltyHop(moduleAt(DOMAIN_VAULT)).validateCancelledRoyaltyHop();
        cancelledRoyaltyRoute = next;
        emit CancelledRoyaltyReturnAdvanced(previous,next);
    }

    function _cancelledTarget(address asset) private view returns(address controller,address receiver) {
        _cancelledRestored();
        controller = cancelledRoyaltyReturnController();
        IZZZAccess target = IZZZAccess(controller);
        _recoveryPeer(controller);
        if(!target.isSealed() || target.canonicalState() != STATE_OPERATING || target.paused() ||
            target.preparationActive() || !target.canConfigure(msg.sender))
            revert Unauthorized();
        receiver = ICanonicalHelpers(target.module(Ids.NFT)).royaltyRewards();
        if(receiver == address(0) || receiver == moduleAt(DOMAIN_ROYALTIES) ||
            !ICancelledRoyaltyLedger(receiver).royaltiesOpen() || !ICancelledRoyaltyLedger(receiver).isAsset(asset))
            revert InvalidState();
    }

    /// @notice Current TARGET governance reviews return of one cancelled
    /// currency to current active weights. No operator-chosen recipient/swap.
    function recoverCancelledRoyalties(address asset,bytes32 reviewHash) external nonReentrant returns(uint256 amount) {
        if(reviewHash == bytes32(0)) revert InvalidRecord();
        (address target,address receiver) = _cancelledTarget(asset);
        ICancelledRoyaltyLedger ledger = ICancelledRoyaltyLedger(receiver);
        ledger.sync(asset);
        uint256 count = ledger.activationCount(); uint256 weight = ledger.totalWeight();
        if(weight == 0) revert InvalidState();
        amount = ICancelledRoyaltyLedger(moduleAt(DOMAIN_ROYALTIES)).canonicalRecoverCancelled(asset,receiver);
        ledger.sync(asset);
        (address afterTarget,address afterReceiver) = _cancelledTarget(asset);
        if(afterTarget != target || afterReceiver != receiver || ledger.activationCount() != count ||
            ledger.totalWeight() != weight) revert InvalidState();
        emit CancelledRoyaltiesRecovered(asset,target,receiver,amount,count,weight,reviewHash);
    }
}

src/ZZZClaimRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IZZZAccess, IZZZNFT} from "./interfaces/IZZZ.sol";
import {Ids} from "./libraries/ZZZTypes.sol";

interface IZZZClaimLedger {
    function claimFor(uint256 id, address asset, address owner) external returns (uint256);
}

/// @notice Atomic, owner-authenticated batching of funded LP and royalty claims.
/// Ledgers pay the current owner directly. This helper never holds funds or
/// approvals, and accepts neither an arbitrary target nor a payout recipient.
contract ZZZClaimRouter is ReentrancyGuard {
    uint256 public constant MAX_CLAIMS = 32;
    IZZZAccess public immutable access;
    address public immutable nft;
    address public immutable royalties;

    struct Claim {
        uint256 nftId;
        address asset;
        bool royalty;
    }

    error InvalidConfiguration();
    error InvalidBatch();
    error DuplicateClaim();
    error Unauthorized();
    event BatchClaimed(address indexed owner, uint256 operations);

    /// @dev Created only by its NFT, while that NFT is under construction.
    /// The LP ledger is resolved through the canonical sealed access registry.
    constructor(address controller, address nftController, address royaltyLedger) {
        if (controller.code.length == 0 || msg.sender != nftController || royaltyLedger.code.length == 0) {
            revert InvalidConfiguration();
        }
        access = IZZZAccess(controller);
        nft = nftController;
        royalties = royaltyLedger;
    }

    /// @notice At most 32 selected (NFT, asset, ledger) operations per transaction.
    /// Results retain input order and raw asset units; unlike dollar values,
    /// amounts for different assets must never be summed. Any failure rolls back
    /// the complete batch. Chunk larger portfolios, and omit failing assets.
    function claimBatch(Claim[] calldata claims) external nonReentrant returns (uint256[] memory amounts) {
        uint256 length = claims.length;
        if (length == 0 || length > MAX_CLAIMS) revert InvalidBatch();
        if (!access.isSealed() || access.module(Ids.NFT) != nft) revert InvalidConfiguration();
        // Reject malformed/unauthorized batches before any payout callback.
        for (uint256 i; i < length; ++i) {
            Claim calldata entry = claims[i];
            if (IZZZNFT(nft).ownerOf(entry.nftId) != msg.sender) revert Unauthorized();
            for (uint256 j; j < i; ++j) {
                Claim calldata earlier = claims[j];
                if (entry.nftId == earlier.nftId && entry.asset == earlier.asset && entry.royalty == earlier.royalty) {
                    revert DuplicateClaim();
                }
            }
        }
        amounts = new uint256[](length);
        for (uint256 i; i < length; ++i) {
            Claim calldata entry = claims[i];
            // A preceding native/token callback may have transferred this NFT.
            // Each ledger independently repeats the same current-owner check.
            if (IZZZNFT(nft).ownerOf(entry.nftId) != msg.sender) revert Unauthorized();
            address target = entry.royalty ? royalties : access.module(Ids.REWARDS);
            if (target.code.length == 0) revert InvalidConfiguration();
            amounts[i] = IZZZClaimLedger(target).claimFor(entry.nftId, entry.asset, msg.sender);
        }
        emit BatchClaimed(msg.sender, length);
    }
}

