src/ZZZLiquidityManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {ZZZModule} from "./base/ZZZModule.sol";
import {Ids, PoolKey, PoolConfig} from "./libraries/ZZZTypes.sol";
import {ExactToken} from "./libraries/ExactToken.sol";
import {ZZZLPPositionExecutor} from "./ZZZLPPositionExecutor.sol";
import {ZZZLPBalancer} from "./ZZZLPBalancer.sol";
import {EmergencyRebalance, IZZZEmergencyBudget, IZZZEmergencyVault, IZZZEmergencyController} from "./interfaces/IZZZEmergency.sol";
import {IZZZPools, IZZZStrategy, IPositionManagerMinimal, IStateViewMinimal,
    IPermit2Minimal, IPoolManagerMinimal} from "./interfaces/IZZZ.sol";

interface INativePoolAssets {
    function isNativePool(bytes32 poolId) external view returns (bool);
}
interface IEmergencyOutput { function minimumOutputForExit(bytes32,bool,uint256) external view returns(uint256); }
interface IPortfolioVault { function migrationBudget() external view returns(address); }
interface IGuardedConsolidation { function consolidationActive() external view returns(bool); }
interface IPortfolioBudget {
    function maintenanceBucket() external view returns(uint256);
    function maintenancePrices() external view returns(uint256,uint256,uint256,uint256);
}
interface IManagerPortfolioPolicy {
    function enabled(bytes32) external view returns(bool);
    function minimumMainBps(bytes32) external view returns(uint16);
    function residualRange(bytes32,uint160,int24,int24,bool) external view returns(int24,int24);
    function recordApplied(uint256,bytes32) external;
}

/// @notice Typed v4 operations only. No arbitrary call/action/recipient entrypoint.
/// Vault owns every LP NFT. Per-NFT approvals authorize this immutable module.
contract ZZZLiquidityManager is ZZZModule, ReentrancyGuard {
    using SafeERC20 for IERC20;
    uint256 public constant LP_ROUTING_VERSION = 2;
    uint256 public constant PORTFOLIO_VERSION = 2;
    uint256 public constant RESIDUAL_EXIT_VERSION = 1;
    uint256 public constant EXECUTION_QUALITY_VERSION = 1;
    uint256 public constant EMERGENCY_REBALANCE_VERSION = 2;
    ZZZLPBalancer public immutable balancingRouter;
    ZZZLPPositionExecutor private immutable positionExecutor;
    IPositionManagerMinimal private immutable posm;
    IStateViewMinimal public immutable stateView;
    IPoolManagerMinimal public immutable poolManager;
    IPermit2Minimal public immutable permit2;
    bytes32 private pendingSwapHash;
    address private emergencyBudget;
    // A native credit is accepted only during an expected core call.
    // Forced ETH is preserved and never counted as contribution or revenue.
    address private nativeSender;
    uint256 private nativeReceived;
    constructor(address controller,address positionManager_,address stateView_,address poolManager_,address permit2_,address balancer_)
        ZZZModule(controller) {
        if (positionManager_.code.length == 0 || stateView_.code.length == 0 || poolManager_.code.length == 0 ||
            permit2_.code.length == 0) revert InvalidConfiguration();
        posm = IPositionManagerMinimal(positionManager_);
        stateView = IStateViewMinimal(stateView_);
        poolManager = IPoolManagerMinimal(poolManager_);
        permit2 = IPermit2Minimal(permit2_);
        if (posm.poolManager() != poolManager_ || posm.permit2() != permit2_ ||
            stateView.poolManager() != poolManager_) revert InvalidConfiguration();
        if(balancer_.code.length==0)revert InvalidConfiguration();
        balancingRouter=ZZZLPBalancer(balancer_);
        if(address(balancingRouter.access())!=controller || address(balancingRouter.poolManager())!=poolManager_ ||
            address(balancingRouter.stateView())!=stateView_ || balancingRouter.LP_ROUTING_VERSION()!=2)revert InvalidConfiguration();
        positionExecutor=new ZZZLPPositionExecutor(controller,positionManager_,stateView_,poolManager_,permit2_,balancer_);
    }
    receive() external payable {
        if (msg.sender != nativeSender || nativeSender == address(0)) revert Unauthorized();
        nativeReceived += msg.value;
    }
    function positionManager() external view returns (address) { return address(posm); }
    /// @notice Pins balancing policy across Vault approval/reset callbacks too.
    function balanceContext(bytes32 targetPool) external view returns (bytes32) {
        return _balanceContext(targetPool);
    }
    function _balanceContext(bytes32 targetPool) private view returns (bytes32) {
        address emergency = _emergencyBudget();
        if(emergency != address(0)) return IZZZEmergencyBudget(emergency).emergencyFingerprint();
        return keccak256(abi.encode(address(balancingRouter),balancingRouter.executionRevision(),
            balancingRouter.policyFingerprint(targetPool,bytes32(0))));
    }
    function _emergencyBudget() private view returns(address budget) {
        return msg.sender == access.module(Ids.VAULT) || msg.sender == address(positionExecutor) ? emergencyBudget : address(0);
    }
    /// @dev Scoped to the Vault's atomic manual-emergency wrapper. Ordinary
    /// operations perform no extra Budget RPC/capability probe.
    function beginEmergency() external onlyModule(Ids.VAULT) nonReentrant {
        if(emergencyBudget != address(0)) revert InvalidState();
        address budget = IZZZEmergencyVault(msg.sender).migrationBudget();
        IZZZEmergencyBudget(budget).validateEmergency(IZZZEmergencyBudget(budget).emergencyBucket());
        emergencyBudget = budget;
    }
    function endEmergency() external onlyModule(Ids.VAULT) nonReentrant {
        address budget = emergencyBudget;
        // Set only by this same immutable Vault's beginEmergency, in one atomic
        // nonreentrant Vault operation. Its Budget binding cannot be replaced.
        if(budget == address(0)) revert InvalidState();
        IZZZEmergencyBudget(budget).validateEmergency(IZZZEmergencyBudget(budget).emergencyBucket());
        emergencyBudget = address(0);
    }
    function _retains(uint8 bit) private view returns(bool) {
        address budget = _emergencyBudget();
        return budget == address(0) || (IZZZEmergencyBudget(budget).emergencyChecks() & bit) != 0;
    }
    function _policySpot(bytes32 poolId) private view returns(uint160) {
        address budget = _emergencyBudget();
        if(budget != address(0)) return (IZZZEmergencyBudget(budget).emergencyChecks() & 2) != 0 ?
            IZZZStrategy(access.module(Ids.STRATEGY)).validateExitPrice(poolId) : spot(poolId);
        return IZZZStrategy(access.module(Ids.STRATEGY)).validatePrice(poolId);
    }
    function spot(bytes32 poolId) public view returns (uint160 priceX96) {
        (priceX96,,,) = stateView.getSlot0(poolId);
    }
    function _config(bytes32 poolId, bool requireOperations) private view returns (PoolConfig memory c) {
        c = IZZZPools(access.module(Ids.POOLS)).get(poolId);
        // Fresh production admission is native ETH/fixed ZZZ only. Historical
        // ERC20-pair deployments retain their own immutable implementation.
        if ((requireOperations && _retains(8) && !c.operationsEnabled) || keccak256(abi.encode(c.key)) != poolId ||
            c.key.currency0 != address(0) || c.key.currency1 == address(0) || c.key.fee > 100000 ||
            c.key.hooks != address(0) || !INativePoolAssets(access.module(Ids.POOLS)).isNativePool(poolId)) revert InvalidState();
    }
    function _balance(address token, address owner) private view returns (uint256) {
        return token == address(0) ? owner.balance : IERC20(token).balanceOf(owner);
    }
    function _sendNative(address recipient, uint256 amount) private {
        if (amount == 0) return;
        uint256 beforeNative = address(this).balance;
        (bool ok,) = recipient.call{value: amount}("");
        if (!ok || address(this).balance + amount != beforeNative) revert InvalidState();
    }
    function _finishNativeCredit(uint256 beforeNative, address recipient) private {
        nativeSender = address(0);
        uint256 amount = nativeReceived;
        nativeReceived = 0;
        if (address(this).balance != beforeNative + amount) revert InvalidState();
        _sendNative(recipient, amount);
    }
    function _checkPosition(bytes32 poolId, uint256 id) private view returns (int24 lower, int24 upper) {
        if (posm.ownerOf(id) != access.module(Ids.VAULT)) revert InvalidState();
        (PoolKey memory key, uint256 info) = posm.getPoolAndPositionInfo(id);
        if (keccak256(abi.encode(key)) != poolId) revert InvalidState();
        lower = int24(uint24(info >> 8));
        upper = int24(uint24(info >> 32));
    }
    function _portfolioPolicy() private view returns(IManagerPortfolioPolicy) {
        return IManagerPortfolioPolicy(IZZZStrategy(access.module(Ids.STRATEGY)).portfolioPolicy());
    }
    function _ordinaryReplacement() private view returns(bool) {
        return _emergencyBudget()==address(0) &&
            IPortfolioBudget(IPortfolioVault(access.module(Ids.VAULT)).migrationBudget()).maintenanceBucket()!=0;
    }
    function _hybridReplacement(bytes32 poolId) private view returns(bool) {
        return _ordinaryReplacement() && _portfolioPolicy().enabled(poolId);
    }
    /// @notice Stable IDs, full keys and bounds. Main increases must not reset
    /// ordinary confirmation; actual current liquidity is checked separately.
    /// @dev Deploy only the excess asset. The scarce remainder stays attributed
    /// as rounding idle; no third leg or mutation of an existing residual.
    /// @dev Only collect/close supply fixed typed actions. Keep recipient reads
    /// after their original callbacks; native and ERC20 prefunds stay untouched.
    function positionOperator()external view returns(address){return address(positionExecutor);}
    function secondaryId(uint256 main)external view returns(uint256){return positionExecutor.secondaryId(main);}
    function activeSecondaryCount()external view returns(uint256){return positionExecutor.activeSecondaryCount();}
    function portfolioFingerprint(uint256 main)external view returns(bytes32){return positionExecutor.portfolioFingerprint(main);}
    function executionPortfolioFingerprint(uint256 main)external view returns(bytes32) {
        uint256 aux=positionExecutor.secondaryId(main);
        return keccak256(abi.encode(positionExecutor.portfolioFingerprint(main),
            main==0?uint128(0):posm.getPositionLiquidity(main),aux==0?uint128(0):posm.getPositionLiquidity(aux)));
    }
    function portfolioAmounts(uint256 main)external view returns(uint256,uint256){return positionExecutor.portfolioAmounts(main);}
    function amounts(uint256 id)external view returns(uint256,uint256){return positionExecutor.amounts(id);}
    function ticks(uint256 id)external view returns(int24,int24){return positionExecutor.ticks(id);}
    modifier onlyPositionExecutor(){if(msg.sender!=address(positionExecutor))revert Unauthorized();_;}
    function executionConfig(bytes32 pool,bool ops)external view onlyPositionExecutor returns(PoolConfig memory){return _config(pool,ops);}
    function executionSpot(bytes32 pool)external view onlyPositionExecutor returns(uint160){return _policySpot(pool);}
    /// @notice Normal replacement must restore active LP in single or hybrid
    /// mode. Initial entry, growth, compound and explicit emergency are separate.
    function executionOrdinaryReplacement()external view onlyPositionExecutor returns(bool){return _ordinaryReplacement();}
    function executionHybridReplacement(bytes32 pool)external view onlyPositionExecutor returns(bool){return _hybridReplacement(pool);}
    function mint(bytes32 pool,int24 lower,int24 upper,uint256 a0,uint256 a1,uint128 minL,uint256 deadline)
        external payable onlyModule(Ids.VAULT) nonReentrant returns(uint256 id,uint256 spent0,uint256 spent1) {
        (id,spent0,spent1)=positionExecutor.mint{value:msg.value}(pool,lower,upper,a0,a1,minL,deadline);
        _portfolioPolicy().recordApplied(id,pool);
    }
    function increase(bytes32 pool,uint256 id,uint256 a0,uint256 a1,uint128 minL,uint256 deadline)
        external payable onlyModule(Ids.VAULT) nonReentrant returns(uint256,uint256) {
        return positionExecutor.increase{value:msg.value}(pool,id,a0,a1,minL,deadline);
    }
    function collect(bytes32 pool,uint256 id,uint256 deadline)external onlyModule(Ids.VAULT) nonReentrant{positionExecutor.collect(pool,id,deadline);}
    function close(bytes32 pool,uint256 id,uint256 deadline)external onlyModule(Ids.VAULT) nonReentrant{positionExecutor.close(pool,id,deadline);}
    /// @notice Close only the registered residual to Vault. This typed recovery
    /// path never swaps, changes the main or authorizes an external recipient.
    function closeSecondary(bytes32 pool,uint256 main,uint256 deadline)
        external onlyModule(Ids.VAULT) nonReentrant {
        if(!access.isSealed() || !access.paused())revert InvalidState();
        positionExecutor.closeSecondary(pool,main,deadline);
        if(!access.paused())revert InvalidState();
    }
    function swap(bytes32 poolId, bool zeroForOne, uint256 amountIn, uint256 minimumOut, uint256 deadline)
        external payable nonReentrant returns (uint256 amountOut) {
        if (!access.isSealed() || (msg.sender != access.module(Ids.VAULT) && msg.sender != access.module(Ids.BUYBACK))) revert Unauthorized();
        _deadline(deadline);
        if (amountIn == 0 || amountIn > type(uint128).max) revert InvalidAmount();
        PoolConfig memory c = _config(poolId,true);
        address input = zeroForOne ? c.key.currency0 : c.key.currency1;
        if (msg.value != (input == address(0) ? amountIn : 0)) revert InvalidAmount();
        bytes32 context = _balanceContext(poolId);
        if (input != address(0)) ExactToken.pull(input, msg.sender, amountIn);
        uint256 beforeNative = address(this).balance - msg.value;
        amountOut = _swapExact(poolId,c,zeroForOne,amountIn,minimumOut,msg.sender);
        if (address(this).balance != beforeNative || _balanceContext(poolId) != context) revert InvalidState();
    }
    function _swapExact(bytes32 poolId, PoolConfig memory c, bool zeroForOne, uint256 amountIn, uint256 minimumOut,
        address recipient) private returns (uint256 amountOut) {
        _policySpot(poolId);
        address output = zeroForOne ? c.key.currency1 : c.key.currency0;
        if (minimumOut == 0) revert Slippage();
        if(_retains(4)) minimumOut = Math.max(minimumOut,
            _emergencyBudget() == address(0) ? IZZZStrategy(access.module(Ids.STRATEGY)).minimumOutput(poolId,zeroForOne,amountIn) :
            IEmergencyOutput(access.module(Ids.STRATEGY)).minimumOutputForExit(poolId,zeroForOne,amountIn));
        uint256 beforeOutput = _balance(output,recipient);
        bytes memory payload = abi.encode(c.key, zeroForOne, amountIn, minimumOut, recipient);
        pendingSwapHash = keccak256(payload);
        amountOut = abi.decode(poolManager.unlock(payload), (uint256));
        if (pendingSwapHash != bytes32(0) || amountOut < minimumOut ||
            _balance(output,recipient) != beforeOutput+amountOut) revert InvalidState();
        _policySpot(poolId);
    }
    /// @notice Balance only the supplied budget, executing one selected swap.
    /// The LP destination/ticks stay fixed; catalog routes never receive custody.
    function balance(bytes32 targetPool,uint256 existingLpId,uint256 amount0,uint256 amount1,uint256 deadline)
        external payable onlyModule(Ids.VAULT) nonReentrant returns (uint256 balanced0,uint256 balanced1) {
        _deadline(deadline);
        if (amount0 > type(uint128).max || amount1 > type(uint128).max || msg.value != amount0) revert InvalidAmount();
        PoolConfig memory target = _config(targetPool,true);
        // _config already requires native currency0, including in emergencies.
        bytes32 context = _balanceContext(targetPool);
        uint256 nativePrefund = address(this).balance-msg.value;
        uint256 tokenPrefund = IERC20(target.key.currency1).balanceOf(address(this));
        bool emergency = _emergencyBudget() != address(0);
        EmergencyRebalance memory request;
        if(emergency) request = IZZZEmergencyController(access.module(Ids.MIGRATION)).emergencyRequest();
        int24 lower; int24 upper; uint128 priorLiquidity;
        if (existingLpId != 0) {
            (lower,upper) = _checkPosition(targetPool,existingLpId);
            priorLiquidity = posm.getPositionLiquidity(existingLpId);
        } else if(emergency) {
            lower = request.lower; upper = request.upper;
        } else (lower,upper,) = IZZZStrategy(access.module(Ids.STRATEGY)).target(targetPool);
        // Pull before quoting: even a token callback cannot intervene between
        // the simulated route and the actual swap. Refund only this budget.
        ExactToken.pull(target.key.currency1,msg.sender,amount1);
        if (_balanceContext(targetPool) != context) revert InvalidState();
        ZZZLPBalancer.Plan memory p;
        if(emergency) {
            p.poolId = request.swapPool; p.zeroForOne = request.zeroForOne;
            p.amountIn = request.amountIn; p.minimumOut = request.minimumOut;
        } else if(existingLpId==0 && _ordinaryReplacement()) {
            // The router adds sizing headroom only when a trade is needed.
            // Actual final allocation retains the captured governed floor.
            uint256[4] memory marks;
            (marks[0],marks[1],marks[2],marks[3])=
                IPortfolioBudget(IPortfolioVault(access.module(Ids.VAULT)).migrationBudget()).maintenancePrices();
            p=balancingRouter.planReplacement(targetPool,lower,upper,amount0,amount1,
                _portfolioPolicy().enabled(targetPool)?_portfolioPolicy().minimumMainBps(targetPool):10000,marks);
        } else if(existingLpId!=0 && access.paused() &&
            IGuardedConsolidation(access.module(Ids.MIGRATION)).consolidationActive()) {
            // Guarded same-main reinvestment promises active placement too.
            // Filter the quoted destination tick before choosing a route; only
            // the fixed Migration's paused context receives this restriction.
            // Single-main scoring uses current Prices, not replacement marks.
            uint256[4] memory marks;
            p=balancingRouter.planReplacement(targetPool,lower,upper,amount0,amount1,10000,marks);
        } else p = balancingRouter.plan(targetPool,lower,upper,amount0,amount1);
        balanced0 = amount0; balanced1 = amount1;
        uint256 refund0 = amount0; uint256 refund1 = amount1;
        if (p.amountIn != 0) {
            PoolConfig memory venue = _config(p.poolId,true);
            if (venue.key.currency1 != target.key.currency1 ||
                p.amountIn > (p.zeroForOne ? amount0 : amount1)) revert InvalidState();
            uint256 output = _swapExact(p.poolId,venue,p.zeroForOne,p.amountIn,p.minimumOut,msg.sender);
            if (!emergency && (output != p.amountOut || spot(p.poolId) != p.sqrtAfter)) revert Slippage();
            if (p.zeroForOne) { balanced0 -= p.amountIn; balanced1 += output; refund0 -= p.amountIn; }
            else { balanced1 -= p.amountIn; balanced0 += output; refund1 -= p.amountIn; }
        }
        _sendNative(msg.sender,refund0);
        ExactToken.push(target.key.currency1,msg.sender,refund1);
        if (existingLpId != 0) {
            (int24 finalLower,int24 finalUpper) = _checkPosition(targetPool,existingLpId);
            if (lower != finalLower || upper != finalUpper || posm.getPositionLiquidity(existingLpId) != priorLiquidity) revert InvalidState();
        }
        if (address(this).balance != nativePrefund || IERC20(target.key.currency1).balanceOf(address(this)) != tokenPrefund ||
            _balanceContext(targetPool) != context) revert InvalidState();
        if(!emergency && (balancingRouter.executionRevision() != p.revision ||
            balancingRouter.policyFingerprint(targetPool,p.poolId) != p.fingerprint ||
            _policySpot(targetPool) != p.targetSqrtAfter)) revert InvalidState();
        if(emergency) _policySpot(targetPool);
    }
    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != address(poolManager) || pendingSwapHash == bytes32(0) ||
            pendingSwapHash != keccak256(data)) revert Unauthorized();
        pendingSwapHash = bytes32(0);
        (PoolKey memory key, bool zeroForOne, uint256 amountIn, uint256 minOut, address recipient) =
            abi.decode(data, (PoolKey, bool, uint256, uint256, address));
        int256 delta = poolManager.swap(key, IPoolManagerMinimal.SwapParams(zeroForOne, -int256(amountIn),
            zeroForOne ? TickMath.MIN_SQRT_PRICE + 1 : TickMath.MAX_SQRT_PRICE - 1), bytes(""));
        int128 delta0 = int128(delta >> 128);
        int128 delta1 = int128(uint128(uint256(delta)));
        int128 inputDelta = zeroForOne ? delta0 : delta1;
        int128 outputDelta = zeroForOne ? delta1 : delta0;
        if (inputDelta >= 0 || outputDelta <= 0 || uint256(-int256(inputDelta)) != amountIn ||
            uint256(int256(outputDelta)) < minOut) revert Slippage();
        address input = zeroForOne ? key.currency0 : key.currency1;
        address output = zeroForOne ? key.currency1 : key.currency0;
        poolManager.sync(input);
        if (input == address(0)) {
            if (poolManager.settle{value: amountIn}() != amountIn) revert InvalidState();
        } else {
            ExactToken.push(input, address(poolManager), amountIn);
            if (poolManager.settle() != amountIn) revert InvalidState();
        }
        uint256 amountOut = uint256(int256(outputDelta));
        if (output == address(0)) {
            uint256 beforeNative = address(this).balance;
            nativeSender = address(poolManager);
            nativeReceived = 0;
            poolManager.take(output, address(this), amountOut);
            if (nativeReceived != amountOut) revert InvalidState();
            _finishNativeCredit(beforeNative, recipient);
        } else poolManager.take(output, recipient, amountOut);
        return abi.encode(amountOut);
    }
}

src/ZZZMembership.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {ZZZModule} from "./base/ZZZModule.sol";
import {IZZZRewards, IZZZNFT, IZZZVault, IZZZFees, IZZZPools} from "./interfaces/IZZZ.sol";
import {Ids, Position, PositionStatus, PoolConfig} from "./libraries/ZZZTypes.sol";
import {IPairVault, IPairAssets} from "./ZZZMigrationBudget.sol";
interface IZZZMembershipOrdinals {
    function mintedCount() external view returns (uint256);
    function tokenAtOrdinal(uint256) external view returns (uint256);
}

/// @notice Each activated canonical NFT has one equal collective-reward share.
/// Eligibility belongs to the NFT, persists through transfers and LP migration,
/// and never increases when its attached LP receives an additional contribution.
contract ZZZMembership is ZZZModule {
    mapping(uint256 => bool) public eligible;
    uint256 public totalEligible;
    event MembershipActivated(uint256 indexed nftId);
    error CanonicalState();
    constructor(address controller) ZZZModule(controller) {}
    // Membership exports eligibility records, not assets. Keep its lifecycle
    // checks without inheriting custody storage or asset-transfer entrypoints.
    modifier canonicalOnly() {
        if (msg.sender != access.canonicalHandoff()) revert CanonicalState();
        _;
    }
    modifier economic() { _economic(); _; _economic(); }
    function _state() private view returns (uint8) { return access.canonicalState(); }
    function _economic() private view { if (_state() != 0) revert CanonicalState(); }
    function _canonicalNext(uint256 row) private {
        if (_state() != 2 || canonicalCursor != row) revert CanonicalState();
        ++canonicalCursor;
    }
    /// @notice Settle funded fee dust in every canonical bucket before an entry.
    /// The Vault caps all historical local buckets, including imported custody.
    /// Unharvested venue fees retain receipt-time policy.
    function settleDust() external onlyModule(Ids.VAULT) economic {
        IZZZVault vault = IZZZVault(access.module(Ids.VAULT));
        IZZZFees fees = IZZZFees(access.module(Ids.FEES));
        IZZZPools pools = IZZZPools(access.module(Ids.POOLS));
        uint256 count = vault.bucketCount();
        if (count > vault.MAX_BUCKETS()) revert InvalidState();
        for (uint256 i; i < count; ++i) {
            uint256 bucket = vault.bucketAt(i);
            Position memory position = vault.group(bucket);
            if (position.status != PositionStatus.Active && position.status != PositionStatus.Outbound &&
                position.status != PositionStatus.Parked) continue;
            // Dust uses immutable admitted currency identities, not a live venue
            // observation. A broken historical venue must not block healthy new
            // entry when its funded dust can still settle exactly. Current-pool
            // execution independently validates accounting and real LP backing.
            PoolConfig memory config = pools.get(position.poolId);
            fees.flushDust(bucket, config.key.currency0);
            fees.flushDust(bucket, config.key.currency1);
            if (IPairVault(address(vault)).migrationBudget().compositionEpoch(bucket) != 0) {
                IPairAssets assets = IPairAssets(access.module(Ids.REWARDS));
                if (assets.assetCount() > 33) revert InvalidState();
                for (uint256 j; j < assets.assetCount(); ++j) {
                    address token = assets.assets(j);
                    if (token != config.key.currency0 && token != config.key.currency1) fees.flushDust(bucket,token);
                }
            }
        }
    }
    function activate(uint256 id) external onlyModule(Ids.VAULT) economic {
        if (eligible[id] || IZZZNFT(access.module(Ids.NFT)).ownerOf(id) == address(0)) revert InvalidState();
        eligible[id] = true;
        ++totalEligible;
        // Rewards settles old stored weights before admitting this new share.
        IZZZRewards(access.module(Ids.REWARDS)).syncMembership(id);
        emit MembershipActivated(id);
    }
    uint256 private canonicalNFTs;
    uint256 private canonicalEligible;
    uint256 private canonicalCursor;
    function canonicalCapture() external canonicalOnly {
        if (_state() != 1) revert CanonicalState();
        canonicalNFTs = IZZZMembershipOrdinals(access.module(Ids.NFT)).mintedCount();
        canonicalEligible = totalEligible;
    }
    function canonicalSettle() external canonicalOnly {}
    function canonicalCount() public view returns (uint256) { return canonicalNFTs + 1; }
    function canonicalExport(uint256 row) external view returns (bytes memory) {
        if ((_state() != 1 && _state() != 3) || row > canonicalNFTs) revert CanonicalState();
        if (row == 0) return abi.encode(canonicalNFTs, totalEligible);
        uint256 id = IZZZMembershipOrdinals(access.module(Ids.NFT)).tokenAtOrdinal(row);
        return abi.encode(id, eligible[id]);
    }
    function canonicalImport(uint256 row, bytes calldata record) external canonicalOnly {
        _canonicalNext(row);
        if (row == 0) {
            if (totalEligible != 0) revert CanonicalState();
            (canonicalNFTs, canonicalEligible) = abi.decode(record, (uint256,uint256));
            if (canonicalNFTs > 1000 || canonicalEligible > canonicalNFTs) revert CanonicalState();
            return;
        }
        (uint256 id, bool active) = abi.decode(record, (uint256,bool));
        if (row > canonicalNFTs || id != IZZZMembershipOrdinals(access.module(Ids.NFT)).tokenAtOrdinal(row)) revert CanonicalState();
        eligible[id] = active;
        if (active) ++totalEligible;
    }
    function canonicalValidate() external view {
        if (_state() == 2 && (canonicalCursor != canonicalCount() || totalEligible != canonicalEligible)) revert CanonicalState();
    }
    function canonicalAssetCount() external view returns (uint256) { return 0; }
    function canonicalActivate() external canonicalOnly {
        if (_state() != 2) revert CanonicalState();
    }
}

src/ZZZMigration.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {ZZZCustodyValidation} from "./ZZZCustodyValidation.sol";
import {ZZZModule} from "./base/ZZZModule.sol";
import {IZZZProtocolPolicy} from "./interfaces/IZZZProtocolPolicy.sol";
import {ExactAsset} from "./libraries/ExactAsset.sol";
import {Ids, Position, PositionStatus, PoolConfig} from "./libraries/ZZZTypes.sol";
import {IZZZVault, IZZZPools, IZZZNFT, IZZZLiquidity} from "./interfaces/IZZZ.sol";
import {EmergencyRebalance, IZZZEmergencyVault} from "./interfaces/IZZZEmergency.sol";
import {ZZZMigrationBudget} from "./ZZZMigrationBudget.sol";
interface IResidualCompletion { function completeConsolidation() external; }
interface IResidualStrategy { function portfolioPolicy() external view returns(address); }

interface IHolderExitVault is IZZZVault {
    function beginLPExit() external;
    function exitBucketToHolders(uint256,uint256,uint256,uint256) external returns(uint256,uint256);
    function closeResidual(uint256,uint256) external;
}
interface IHolderExitNFT is IZZZNFT {
    function mintedCount() external view returns(uint256);
    function tokenAtOrdinal(uint256) external view returns(uint256);
    function refreshMetadata(uint256) external;
}

/// @notice Live same-pair movement/parking, or irreversible collective principal
/// return to NFT owners. No external custody address, conversion exit or sweep.
/// Reward ledgers and future royalty rights remain independent of principal.
contract ZZZMigration is ZZZModule, ReentrancyGuard {
    uint8 public constant CUSTODY_VERSION = 5;
    uint256 public constant EMERGENCY_REBALANCE_VERSION = 2;
    uint256 public constant RESIDUAL_EXIT_VERSION = 1;
    uint256 public constant RESIDUAL_REINVEST_VERSION = 1;
    uint256 public constant MAX_BATCH = 32;
    enum ExitPhase { Operating, Closing, Allocating, Ready }
    struct ParkingRequest {
        uint256 bucketId; bytes32 poolId; uint256 lpTokenId; uint256 totalShares; uint256 depositUSD;
        uint64 custodyEpoch; uint64 nonce; address token0; address token1;
        uint128 minimum0; uint128 minimum1; uint256 deadline; bytes32 reviewHash; bytes32 portfolioHash;
    }
    struct BucketSettlement {
        uint256 totalShares;
        uint256 ethAmount;
        uint256 zzzAmount;
        uint256 allocatedShares;
        uint256 allocatedETH;
        uint256 allocatedZZZ;
        bool closed;
    }
    struct Principal {
        uint256 ethAmount;
        uint256 zzzAmount;
        bool allocated;
        bool paid;
    }
    address public currentZZZ;
    bytes32 public zzzCodeHash;
    ExitPhase public exitPhase;
    bytes32 public exitReviewHash;
    uint256 public exitMintedCount;
    uint256 public allocationCursor;
    uint256 public remainingBuckets;
    uint256 public remainingETH;
    uint256 public remainingZZZ;
    uint256[] private settlementBuckets;
    mapping(uint256 => BucketSettlement) public bucketSettlement;
    mapping(uint256 => Principal) public principalOf;
    mapping(uint256 => uint64) public custodyEpoch;
    mapping(uint256 => uint64) public parkingNonce;
    ZZZCustodyValidation public immutable validation;
    EmergencyRebalance private emergency;
    bool public consolidationActive;
    event ZZZConfigured(address indexed token,bytes32 codeHash,bytes32 reviewHash);
    event CollectiveExitStarted(bytes32 indexed reviewHash,uint256 mintedCount,uint256 bucketCount);
    event BucketClosed(uint256 indexed bucketId,uint256 totalShares,uint256 ethAmount,uint256 zzzAmount);
    event PrincipalAllocated(uint256 indexed nftId,uint256 indexed bucketId,uint256 ethAmount,uint256 zzzAmount);
    event PrincipalDistributionReady(uint256 totalETH,uint256 totalZZZ);
    event PrincipalPaid(uint256 indexed nftId,address indexed owner,address indexed recipient,uint256 ethAmount,uint256 zzzAmount);
    event PrincipalDeferred(uint256 indexed nftId);
    event ParkingExecuted(bytes32 indexed requestHash,uint256 indexed bucketId,uint64 nonce,uint256 principal0,uint256 principal1);
    event ParkingInvalidated(uint256 indexed bucketId,uint64 nextNonce);
    event ResidualClosed(bytes32 indexed requestHash,uint256 indexed bucketId,uint256 indexed secondaryId,
        uint64 nonce,uint256 principal0,uint256 principal1);
    event EmergencyRebalanced(uint256 indexed bucket,uint8 retainedChecks,bytes32 indexed requestHash,bytes32 indexed reviewHash);
    event ResidualConsolidated(uint256 indexed bucket,bool forced,bytes32 indexed requestHash,bytes32 indexed reviewHash);

    constructor(address controller) ZZZModule(controller) {
        validation = new ZZZCustodyValidation(controller);
    }
    receive() external payable {
        if(msg.sender != access.module(Ids.VAULT)) revert Unauthorized();
    }
    function _vault() private view returns(IHolderExitVault) {
        return IHolderExitVault(access.module(Ids.VAULT));
    }
    function _nft() private view returns(IHolderExitNFT) {
        return IHolderExitNFT(access.module(Ids.NFT));
    }
    /// @notice Manual governance-only emergency, while paused. Never a keeper
    /// fallback. Disabled economic checks accept the explicitly reviewed risk;
    /// native ETH/fixed ZZZ, exact accounting and all lifecycle locks remain.
    function emergencyRebalance(EmergencyRebalance calldata request)
        external onlyGovernance operating principalOperating nonReentrant {
        _deadline(request.deadline);
        validation.validateEmergency(request);
        _executeManual(request,true);
        emit EmergencyRebalanced(request.bucket,request.checks,
            keccak256(abi.encode(block.chainid,address(this),address(_vault()),request)),request.reviewHash);
    }
    /// @notice Close the residual and reinvest attributed idle into the SAME
    /// main. Guarded execution routes automatically; forced execution uses the
    /// reviewed explicit swap/mask. Neither releases the Fees compound reserve.
    function consolidateResidual(EmergencyRebalance calldata request,bool forced)
        external onlyGovernance operating principalOperating nonReentrant {
        _deadline(request.deadline);
        ZZZCustodyValidation.Consolidation memory beforeState=validation.captureConsolidation(request,forced);
        consolidationActive=true;
        _executeManual(request,forced);
        validation.verifyConsolidation(request,forced,beforeState);
        IResidualCompletion(IResidualStrategy(access.module(Ids.STRATEGY)).portfolioPolicy())
            .completeConsolidation();
        ++parkingNonce[request.bucket]; ++custodyEpoch[request.bucket];
        consolidationActive=false;
        delete emergency;
        emit ResidualConsolidated(request.bucket,forced,
            keccak256(abi.encode(block.chainid,address(this),address(_vault()),request,forced)),request.reviewHash);
    }
    function _executeManual(EmergencyRebalance calldata request,bool forced) private {
        IZZZEmergencyVault vault=IZZZEmergencyVault(address(_vault()));
        ZZZMigrationBudget budget = ZZZMigrationBudget(vault.migrationBudget());
        emergency = request;
        bytes32 context;
        if(forced) { budget.beginEmergency(request.bucket,request.checks); context=budget.emergencyFingerprint(); }
        vault.emergencyRebalance(request.bucket,request.minimumLiquidity,request.deadline);
        if(forced) {
            if(budget.emergencyFingerprint()!=context) revert InvalidState();
            budget.endEmergency();
        }
        if(!consolidationActive) delete emergency;
    }
    function emergencyFingerprint() external view returns(bytes32 result) {
        ZZZMigrationBudget budget = ZZZMigrationBudget(IZZZEmergencyVault(address(_vault())).migrationBudget());
        if(msg.sender != address(budget)) revert Unauthorized();
        EmergencyRebalance memory request = emergency;
        budget.validateEmergency(request.bucket);
        return consolidationActive ? validation.consolidationEmergencyFingerprint(request) : validation.emergencyFingerprint(request);
    }
    function emergencyRequest() external view returns(EmergencyRebalance memory) { return emergency; }
    function emergencyTarget() external view returns(int24,int24) { return(emergency.lower,emergency.upper); }
    /// @notice Review-time physical/accounting identity. Price changes alone do
    /// not replace the LP, but a top-up, park, move or share change invalidates it.
    function emergencyCustodyHash(uint256 bucket) public view returns(bytes32) {
        return validation.emergencyCustodyHash(bucket);
    }
    function consolidationCustodyHash(uint256 bucket) external view returns(bytes32) {
        return validation.consolidationCustodyHash(bucket);
    }
    /// @notice Compatibility read for ordinary same-chain canonical snapshots.
    /// No external-custody plans exist in this implementation.
    function activePlan(uint256) external pure returns(bytes32) { return bytes32(0); }
    function outstandingCount() external pure returns(uint256) { return 0; }
    function settlementBucketCount() external view returns(uint256) { return settlementBuckets.length; }
    function settlementBucketAt(uint256 index) external view returns(uint256) { return settlementBuckets[index]; }

    /// @notice Bootstrap-only binding of the same fixed ZZZ used by contributions
    /// and buybacks. This is not an external recipient or a replaceable token.
    function configureZZZ(address token,bytes32 codeHash,bytes32 reviewHash) external onlyGovernance nonReentrant {
        validation.validateZZZ(token,codeHash,reviewHash);
        currentZZZ = token;
        zzzCodeHash = codeHash;
        emit ZZZConfigured(token,codeHash,reviewHash);
    }

    /// @notice Governance commits an irreversible LP shutdown while paused.
    /// Validate EVERY funded bucket before locking; no oracle or swap is needed.
    /// No mint, activation, growth, rebalance, resume or canonical replacement may
    /// subsequently reopen LP. NFT transfers and reward/royalty claims continue.
    function beginCollectiveExit(bytes32 reviewHash) external onlyGovernance operating nonReentrant {
        if(!access.isSealed() || !access.paused() || access.lpExitStarted() || exitPhase != ExitPhase.Operating ||
            reviewHash == bytes32(0) || currentZZZ == address(0)) revert InvalidState();
        IHolderExitVault vault = _vault();
        uint256 count = vault.bucketCount();
        if(count > vault.MAX_BUCKETS()) revert InvalidState();
        for(uint256 i; i<count; ++i) {
            uint256 bucket = vault.bucketAt(i);
            Position memory p = vault.group(bucket);
            uint256 shares = vault.bucketTotalShares(bucket);
            if(shares == 0) {
                if(p.lpTokenId != 0 || p.idle0 != 0 || p.idle1 != 0 || p.status != PositionStatus.None) revert InvalidState();
                continue;
            }
            if((p.status != PositionStatus.Active && p.status != PositionStatus.Parked) ||
                (p.status == PositionStatus.Active && p.lpTokenId == 0) ||
                (p.status == PositionStatus.Parked && p.lpTokenId != 0)) revert InvalidState();
            PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
            if(c.key.currency0 != address(0) || c.key.currency1 != currentZZZ) revert InvalidConfiguration();
            bucketSettlement[bucket].totalShares = shares;
            settlementBuckets.push(bucket);
        }
        remainingBuckets = settlementBuckets.length;
        exitMintedCount = _nft().mintedCount();
        if(remainingBuckets == 0 || exitMintedCount == 0 || exitMintedCount > 1000) revert InvalidState();
        exitReviewHash = reviewHash;
        exitPhase = ExitPhase.Closing;
        // The nonreentrant Vault barrier rejects a start during any in-flight
        // contribution, LP execution or principal callback before setting Access.
        vault.beginLPExit();
        if(!access.lpExitStarted()) revert InvalidState();
        emit CollectiveExitStarted(reviewHash,exitMintedCount,remainingBuckets);
    }

    /// @notice Close one snapshotted bucket without swaps. Raw minima cover all
    /// returned principal: LP proceeds + attributed idle + pending compounding.
    /// Only exact operation deltas enter settlement; prefunds are never assigned.
    function closeBucket(uint256 bucket,uint256 minimumETH,uint256 minimumZZZ,uint256 deadline)
        external onlyGovernance operating nonReentrant {
        _deadline(deadline);
        BucketSettlement storage s = bucketSettlement[bucket];
        if(exitPhase != ExitPhase.Closing || !access.lpExitStarted() || !access.paused() ||
            s.totalShares == 0 || s.closed || _vault().bucketTotalShares(bucket) != s.totalShares) revert InvalidState();
        uint256 beforeETH = address(this).balance;
        uint256 beforeZZZ = ExactAsset.balance(currentZZZ,address(this));
        (uint256 ethAmount,uint256 zzzAmount) = _vault().exitBucketToHolders(bucket,minimumETH,minimumZZZ,deadline);
        if(address(this).balance != beforeETH+ethAmount ||
            ExactAsset.balance(currentZZZ,address(this)) != beforeZZZ+zzzAmount ||
            _vault().group(bucket).status != PositionStatus.Exited ||
            _vault().bucketTotalShares(bucket) != s.totalShares) revert InvalidState();
        s.ethAmount = ethAmount; s.zzzAmount = zzzAmount; s.closed = true;
        remainingETH += ethAmount; remainingZZZ += zzzAmount;
        ++custodyEpoch[bucket];
        if(--remainingBuckets == 0) {
            if (IZZZLiquidity(access.module(Ids.LIQUIDITY)).activeSecondaryCount() != 0) revert InvalidState();
            exitPhase = ExitPhase.Allocating;
            allocationCursor = 1;
        }
        emit BucketClosed(bucket,s.totalShares,ethAmount,zzzAmount);
    }

    /// @notice Governance-only bounded deterministic apportionment. Cumulative
    /// floors in immutable mint order allocate every raw unit without a sweep.
    /// Transfers do not change shares; unclaimed principal follows the NFT.
    function allocatePrincipal(uint256 maximum) external onlyGovernance operating nonReentrant {
        if(exitPhase != ExitPhase.Allocating || maximum == 0 || maximum > MAX_BATCH) revert InvalidState();
        IHolderExitNFT nft = _nft(); IHolderExitVault vault = _vault();
        uint256 end = Math.min(allocationCursor+maximum,exitMintedCount+1);
        for(uint256 ordinal=allocationCursor; ordinal<end; ++ordinal) {
            uint256 id = nft.tokenAtOrdinal(ordinal);
            if(id == 0 || principalOf[id].allocated) revert InvalidState();
            uint256 shares = vault.sharesOf(id); uint256 bucket = vault.nftBucket(id);
            Principal storage p = principalOf[id]; p.allocated = true;
            if(shares == 0) {
                if(bucket != 0) revert InvalidState();
                continue;
            }
            BucketSettlement storage s = bucketSettlement[bucket];
            if(!s.closed || s.totalShares == 0) revert InvalidState();
            uint256 cumulative = s.allocatedShares+shares;
            if(cumulative > s.totalShares) revert InvalidState();
            uint256 ethTotal = Math.mulDiv(s.ethAmount,cumulative,s.totalShares);
            uint256 zzzTotal = Math.mulDiv(s.zzzAmount,cumulative,s.totalShares);
            p.ethAmount = ethTotal-s.allocatedETH; p.zzzAmount = zzzTotal-s.allocatedZZZ;
            s.allocatedShares = cumulative; s.allocatedETH = ethTotal; s.allocatedZZZ = zzzTotal;
            emit PrincipalAllocated(id,bucket,p.ethAmount,p.zzzAmount);
            // Bounded ERC-4906 event only: no receiver callback or price read.
            nft.refreshMetadata(id);
        }
        allocationCursor = end;
        if(end == exitMintedCount+1) {
            for(uint256 i; i<settlementBuckets.length; ++i) {
                BucketSettlement memory s = bucketSettlement[settlementBuckets[i]];
                if(s.allocatedShares != s.totalShares || s.allocatedETH != s.ethAmount || s.allocatedZZZ != s.zzzAmount)
                    revert InvalidState();
            }
            _backed(); exitPhase = ExitPhase.Ready;
            emit PrincipalDistributionReady(remainingETH,remainingZZZ);
        }
    }
    function claimablePrincipal(uint256 id) external view returns(uint256 ethAmount,uint256 zzzAmount) {
        Principal memory p = principalOf[id];
        if(exitPhase != ExitPhase.Ready || !p.allocated) revert NotReady();
        return p.paid ? (uint256(0),uint256(0)) : (p.ethAmount,p.zzzAmount);
    }
    /// @notice Governance pays the CURRENT NFT owner. Each bounded inner call is
    /// isolated: a rejecting or gas-consuming owner cannot block other owners.
    /// A deferred NFT remains fully backed and can retry or use owner fallback.
    function distributePrincipal(uint256[] calldata ids) external onlyGovernance operating nonReentrant returns(uint256 paid) {
        if(exitPhase != ExitPhase.Ready || ids.length == 0 || ids.length > MAX_BATCH) revert InvalidState();
        uint256 payoutGas = IZZZProtocolPolicy(access.protocolPolicy()).payoutGas();
        for(uint256 i; i<ids.length; ++i) {
            if(gasleft() < payoutGas+60000) break;
            Principal memory p = principalOf[ids[i]];
            if(!p.allocated || p.paid || (p.ethAmount == 0 && p.zzzAmount == 0)) continue;
            try this.payCurrentOwner{gas:payoutGas}(ids[i]) { ++paid; }
            catch { emit PrincipalDeferred(ids[i]); }
        }
    }
    /// @dev Self-only isolation boundary, never a caller-selected beneficiary.
    function payCurrentOwner(uint256 id) external {
        if(msg.sender != address(this)) revert Unauthorized();
        address owner = _nft().ownerOf(id);
        _pay(id,owner,owner);
    }
    /// @notice Optional recovery for a receiver that rejects an automatic push.
    /// Only the actual current owner (not an ERC721 approval) chooses recipient.
    function claimPrincipal(uint256 id,address recipient) external operating nonReentrant {
        address owner = _nft().ownerOf(id);
        if(owner != msg.sender) revert Unauthorized();
        _pay(id,recipient,owner);
    }
    function _pay(uint256 id,address recipient,address owner) private {
        Principal storage p = principalOf[id];
        if(exitPhase != ExitPhase.Ready || !p.allocated || p.paid || (p.ethAmount == 0 && p.zzzAmount == 0) ||
            recipient == address(0) || recipient == address(this))
            revert InvalidState();
        // The two private callers authenticate this owner immediately above,
        // with no intervening external call; reuse it for the original-owner log.
        _backed();
        p.paid = true;
        remainingETH -= p.ethAmount; remainingZZZ -= p.zzzAmount;
        ExactAsset.push(currentZZZ,recipient,p.zzzAmount);
        ExactAsset.push(address(0),recipient,p.ethAmount);
        _backed();
        emit PrincipalPaid(id,owner,recipient,p.ethAmount,p.zzzAmount);
    }
    function _backed() private view {
        if(address(this).balance < remainingETH || ExactAsset.balance(currentZZZ,address(this)) < remainingZZZ) revert InvalidState();
    }

    /// @notice Atomic pool-to-pool move while LP is operating. No holder payout
    /// or external recipient is involved; actual ordered currencies must match.
    function moveFunds(uint256 id,bytes32 pool,uint128 minimum,uint256 deadline)
        external onlyGovernance live principalOperating nonReentrant {
        _vault().movePool(id,pool,minimum,deadline);
    }
    function resume(uint256 id,bytes32 pool,uint128 minimum,uint256 deadline)
        external onlyGovernance live principalOperating nonReentrant {
        _vault().resume(id,pool,minimum,deadline);
    }
    function park(ParkingRequest calldata r) external onlyDrainGovernance principalOperating nonReentrant {
        _deadline(r.deadline); IHolderExitVault vault = _vault(); Position memory p = vault.group(r.bucketId);
        validation.validateParking(abi.encode(r)); ++parkingNonce[r.bucketId];
        vault.park(r.bucketId,r.deadline); Position memory afterPosition = vault.group(r.bucketId);
        uint256 a0 = afterPosition.idle0-p.idle0; uint256 a1 = afterPosition.idle1-p.idle1;
        if(afterPosition.status != PositionStatus.Parked || afterPosition.lpTokenId != 0 ||
            IZZZLiquidity(access.module(Ids.LIQUIDITY)).secondaryId(r.lpTokenId) != 0 ||
            a0 < r.minimum0 || a1 < r.minimum1) revert Slippage();
        emit ParkingExecuted(keccak256(abi.encode(block.chainid,address(this),address(vault),r)),r.bucketId,r.nonce,a0,a1);
    }
    /// @notice Manually close only the associated residual into Vault-attributed
    /// idle, without a swap, external payout or replacement of the main LP.
    /// The reviewed desired mode is unchanged; disable it separately to prevent
    /// a future whole adjustment from creating another residual.
    function closeResidual(ParkingRequest calldata r)
        external onlyGovernance operating principalOperating nonReentrant {
        _deadline(r.deadline);
        ZZZCustodyValidation.ResidualClose memory beforeState=validation.captureResidualClose(abi.encode(r));
        IHolderExitVault vault=_vault();
        ++parkingNonce[r.bucketId];
        vault.closeResidual(r.bucketId,r.deadline);
        (uint256 a0,uint256 a1)=validation.verifyResidualClose(abi.encode(r),beforeState);
        ++custodyEpoch[r.bucketId];
        emit ResidualClosed(keccak256(abi.encode(block.chainid,address(this),address(vault),r)),
            r.bucketId,beforeState.secondary,r.nonce,a0,a1);
    }
    function invalidateParking(uint256 id) external onlyDrainGovernance principalOperating {
        ++parkingNonce[id]; emit ParkingInvalidated(id,parkingNonce[id]);
    }
}

src/ZZZMigrationBudget.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {ZZZContributionPricing} from "./ZZZContributionPricing.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Ids, Position, PositionStatus, PoolConfig} from "./libraries/ZZZTypes.sol";
import {IZZZAccess, IZZZVault, IZZZPools, IZZZOracle, IZZZLiquidity, IZZZStrategy, IPositionManagerMinimal} from "./interfaces/IZZZ.sol";
interface IPairAssets { function assetCount() external view returns(uint256); function assets(uint256) external view returns(address); }
interface IPairVault { function migrationBudget() external view returns(ZZZMigrationBudget); }
interface IConfirmationControl {
    function controlFingerprint(bytes32) external view returns(bytes32);
    function observationFingerprint(uint256,bytes32) external view returns(bytes32);
    function observations(uint256) external view returns(bytes32,uint64,uint64,uint8);
    function emergencyReady(uint256) external view returns(bool);
}
import {IZZZCanonicalAccess} from "./interfaces/IZZZCanonical.sol";
interface IEmergencyManifest {
    function emergencyFingerprint() external view returns(bytes32);
    function emergencyTarget() external view returns(int24,int24);
}

interface IMigrationIdle { function totalIdle(address) external view returns(uint256); }
interface IBudgetVaultValidation {
    function validateOwner(uint256,address,bool,bool) external view returns(address);
    function validateHolderExit(uint256,address) external view returns(address,address);
    function validateContribution(uint256,uint256,uint256,uint256,uint128,bool)
        external view returns(address,address,uint16);
}
interface IBudgetPortfolioStrategy { function portfolioPolicy() external view returns(address); }
interface IBudgetPortfolioPolicy {
    function revision() external view returns(uint64);
    function enabled(bytes32) external view returns(bool);
}
interface IBudgetPositionOperator { function positionOperator() external view returns(address); }

/// @notice Bounded execution policy for contributions and principal maintenance.
/// A separately deployed fixed-controller companion. Governance can change
/// future loss limits, never custody or recipients. The sealed controller fixes
/// the sole Vault caller; there is no mutable parent setter.
contract ZZZMigrationBudget is ReentrancyGuard {
    IZZZAccess public immutable access;
    uint16 public constant MAX_LOSS_BPS = 1000;
    uint256 public constant IDLE_COMPOUNDING_VERSION = 4;
    uint256 public constant REBALANCE_CONFIRMATION_VERSION = 3;
    uint32 public constant DEFAULT_COMPOUND_INTERVAL = 1 hours;
    uint16 public contributionLossBps = 200;
    uint16 public maintenanceLossBps = 300;
    uint256 public constant EMERGENCY_REBALANCE_VERSION = 2;
    uint256 public constant RESIDUAL_REINVEST_VERSION = 1;
    bool public emergencyActive;
    uint256 public emergencyBucket;
    uint8 public emergencyChecks;
    address private emergencyGovernor;
    struct Snapshot {
        uint256 bucketId;
        uint256 value;
        uint256 price0;
        uint256 price1;
        uint256 scale0;
        uint256 scale1;
        uint256 idle0;
        uint256 idle1;
        uint16 lossBps;
        uint16 maxIdleBps;
        bytes32 maintenancePolicy;
        bytes32 confirmationControl;
        bytes32 sourcePool;
        uint64 portfolioRevision;
        bool replacement;
    }
    Snapshot private snapshot;
    bool private compoundIncluded;
    /// @notice Last successful compound or governed same-main reinvestment.
    /// Local operating state; LP replacement time remains separately in Vault.
    mapping(uint256 => uint64) public lastCompound;
    mapping(uint256 => uint64) public compositionEpoch;
    mapping(bytes32 => uint32) private compoundIntervals;
    error Unauthorized();
    error InvalidState();
    error InvalidAmount();
    error InvalidConfiguration();
    error Slippage();
    error Preparing();
    error CanonicalLocked();
    event MigrationValueChecked(uint256 indexed bucketId, uint256 beforeUSD, uint256 deployedUSD, uint256 idleUSD);
    event ContributionLossLimitChanged(uint16 previous, uint16 current);
    event MaintenanceLossLimitChanged(uint16 previous, uint16 current);
    event CompoundIntervalChanged(bytes32 indexed poolId,uint32 previous,uint32 current);

    constructor(address controller) {
        access = IZZZAccess(controller);
    }
    /// @notice Canonical parent follows only the controller's sealed module binding.
    /// Before binding, address zero cannot invoke a Vault-only entry point.
    function vault() public view returns(address) { return access.module(Ids.VAULT); }
    /// @dev Only Migration's paused governance entry may arm the atomic context.
    function beginEmergency(uint256 bucket,uint8 checks) external nonReentrant {
        if(msg.sender != access.module(Ids.MIGRATION) || emergencyActive || snapshot.value != 0) revert Unauthorized();
        emergencyBucket = bucket; emergencyChecks = checks; emergencyGovernor = access.governance(); emergencyActive = true;
        validateEmergency(bucket);
    }
    function endEmergency() external nonReentrant {
        if(msg.sender != access.module(Ids.MIGRATION) || snapshot.value != 0) revert Unauthorized();
        validateEmergency(emergencyBucket);
        delete emergencyBucket; delete emergencyChecks; delete emergencyGovernor; emergencyActive = false;
    }
    function validateEmergency(uint256 bucket) public view {
        if(!emergencyActive || emergencyBucket != bucket || access.governance() != emergencyGovernor ||
            !access.isSealed() || !access.paused() || access.preparationActive() ||
            access.canonicalState() != 0 || access.lpExitStarted()) revert InvalidState();
    }
    function emergencyFingerprint() external view returns(bytes32 result) {
        validateEmergency(emergencyBucket);
        result = IEmergencyManifest(access.module(Ids.MIGRATION)).emergencyFingerprint();
        // A retained sample requirement must survive callbacks even when the
        // value guard is deliberately disabled. Compare the stable policy/raw
        // record, not readiness against the deliberately replaced LP identity.
        if((emergencyChecks & 16) != 0) result = keccak256(abi.encode(result,
            _confirmationControl(emergencyBucket,IZZZVault(vault()).group(emergencyBucket).poolId)));
    }
    function _skip(uint8 bit) private view returns(bool) { return emergencyActive && (emergencyChecks & bit) == 0; }
    /// @notice One bounded immediate governance update. After the static access
    /// checks, only local writes/events occur: no callback can alter authority.
    function setLossLimits(uint16 contribution, uint16 maintenance) external nonReentrant {
        if (!access.canConfigure(msg.sender)) revert Unauthorized();
        if (access.preparationActive()) revert Preparing();
        if (access.canonicalState() != 0) revert CanonicalLocked();
        if (contribution > MAX_LOSS_BPS || maintenance > MAX_LOSS_BPS || snapshot.value != 0) revert InvalidConfiguration();
        emit ContributionLossLimitChanged(contributionLossBps, contribution);
        emit MaintenanceLossLimitChanged(maintenanceLossBps, maintenance);
        contributionLossBps = contribution;
        maintenanceLossBps = maintenance;
    }
    /// @notice Configure standalone compounding separately from rebalance.
    /// This changes future eligibility, never a recorded clock or NFT backing.
    function setCompoundInterval(bytes32 poolId,uint32 interval) external nonReentrant {
        if (!access.canConfigure(msg.sender)) revert Unauthorized();
        if (access.preparationActive()) revert Preparing();
        if (access.canonicalState() != 0) revert CanonicalLocked();
        if (interval < 600 || interval > 7 days || snapshot.value != 0) revert InvalidConfiguration();
        _knownPool(poolId);
        uint32 previous = _compoundInterval(poolId);
        compoundIntervals[poolId] = interval;
        emit CompoundIntervalChanged(poolId,previous,interval);
    }
    /// @notice Admitted pool policy, in seconds; one hour before its first setter.
    function compoundInterval(bytes32 poolId) external view returns(uint32) {
        _knownPool(poolId);
        return _compoundInterval(poolId);
    }
    function _compoundInterval(bytes32 poolId) private view returns(uint32 interval) {
        interval = compoundIntervals[poolId];
        if (interval == 0) interval = DEFAULT_COMPOUND_INTERVAL;
    }
    function _knownPool(bytes32 poolId) private view {
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).get(poolId);
        if (poolId == bytes32(0) || c.key.tickSpacing <= 0 || keccak256(abi.encode(c.key)) != poolId) revert InvalidConfiguration();
    }
    modifier onlyVault() {
        if (msg.sender != vault()) revert Unauthorized();
        _;
    }
    function recordComposition(uint256 id) external onlyVault {
        ++compositionEpoch[id];
    }
    function validateOwner(uint256 id,address caller,bool minted,bool activation) external view onlyVault returns (address entry) {
        return IBudgetVaultValidation(access.module(Ids.VAULT_CANONICAL)).validateOwner(id,caller,minted,activation);
    }
    function importComposition(uint256 id, uint64 epoch) external {
        if (msg.sender != access.module(Ids.VAULT_CANONICAL) ||
            IZZZCanonicalAccess(address(access)).canonicalState() != 2 || compositionEpoch[id] != 0) revert Unauthorized();
        compositionEpoch[id] = epoch;
    }
    function _balance(address asset) private view returns(uint256) {
        return asset==address(0)?vault().balance:IERC20(asset).balanceOf(vault());
    }
    function assertIdle(uint256 id) external view onlyVault {
        Position memory p = IZZZVault(vault()).group(id);
        // Vault calls this immediately after its local attribution writes.
        // Check the same bounded amounts before any token balance callbacks;
        // a failure atomically rolls back the entire operation and those writes.
        if ((p.idle0 | p.idle1) > type(uint128).max) revert InvalidAmount();
        (address a,address b) = poolTokens(p.poolId);
        if (_balance(a) < IMigrationIdle(vault()).totalIdle(a) ||
            _balance(b) < IMigrationIdle(vault()).totalIdle(b)) revert InvalidState();
    }
    function validateCanonicalWriter(address caller) external view onlyVault {
        if (caller != access.module(Ids.VAULT_CANONICAL) || IZZZCanonicalAccess(address(access)).canonicalState() != 2) revert Unauthorized();
    }
    /// @notice Compound waits after either LP creation/replacement or compound,
    /// and yields to an eligible rebalance or preapproved range selection.
    /// Rebalance never reads lastCompound:
    /// a keeper cannot compound first to postpone needed range maintenance.
    /// Applies to all standalone compound calls, including ones needing no swap.
    function compoundReady(uint256 id) public view returns (bool) {
        return _pricing().compoundReady(id);
    }
    /// @dev Called before fee settlement, token callbacks or closing the old LP.
    /// Only attributed assets enter the starting denominator.
    function checkpoint(uint256 id, uint8 phase) external onlyVault {
        // Manual same-main reinvestment is not a rebalance and has no automatic
        // compound interval. Its successful clock update rolls back on failure,
        // including when governance deliberately disables the value guard.
        if (phase == 4) lastCompound[id] = uint64(block.timestamp);
        if(emergencyActive) {
            validateEmergency(id);
            if(_skip(4)) return;
        }
        if (phase == 0) _beforeMove(id,true);
        else if (phase == 1) _includeCompound(id);
        else if (phase == 2) _afterMove(id);
        else if (phase == 3) {
            if (!compoundReady(id)) revert InvalidState();
            _beforeMove(id,false);
            lastCompound[id] = uint64(block.timestamp);
        }
        else if (phase == 4) _beforeMove(id,false);
        else revert InvalidState();
    }
    /// @notice Only a normal whole-position replacement may mint a residual.
    /// First activation, standalone compounding and manual emergency never
    /// acquire hybrid execution permission merely by calling the Manager.
    function maintenanceBucket() external view returns(uint256) {
        return !emergencyActive && snapshot.value != 0 && snapshot.replacement ? snapshot.bucketId : 0;
    }
    /// @notice Captured utilization basis for the normal partial-swap solver.
    /// This is never a substitute for current independent swap-price guards.
    function maintenancePrices() external view returns(uint256 price0,uint256 price1,uint256 scale0,uint256 scale1) {
        Snapshot storage s = snapshot;
        if (emergencyActive || s.value == 0 || !s.replacement || s.bucketId == 0) revert InvalidState();
        return (s.price0,s.price1,s.scale0,s.scale1);
    }
    function _portfolioPolicy() private view returns(IBudgetPortfolioPolicy) {
        return IBudgetPortfolioPolicy(IBudgetPortfolioStrategy(access.module(Ids.STRATEGY)).portfolioPolicy());
    }
    function _beforeMove(uint256 id,bool replacement) private {
        if (snapshot.value != 0) revert InvalidState();
        Position memory p = IZZZVault(vault()).group(id);
        Snapshot memory s;
        s.bucketId = id;
        s.sourcePool = p.poolId;
        s.lossBps = maintenanceLossBps;
        s.confirmationControl = _confirmationControl(id,p.poolId);
        if (!emergencyActive) {
            s.portfolioRevision = _portfolioPolicy().revision();
            s.replacement = replacement;
        }
        // Price validates feed/sequencer freshness. Reuse this exact vector after
        // close, swap and mint; callbacks cannot reprice away execution loss.
        ZZZContributionPricing.MaintenanceMark memory mark = _pricing().markMaintenance(id);
        s.maxIdleBps = mark.maxIdleBps; s.maintenancePolicy = mark.maintenancePolicy;
        s.price0 = mark.price0; s.price1 = mark.price1; s.scale0 = mark.scale0; s.scale1 = mark.scale1;
        s.idle0 = mark.idle0; s.idle1 = mark.idle1; s.value = mark.value;
        if (s.value == 0) revert InvalidState();
        snapshot = s;
    }
    /// @dev Between checkpoints the guarded Vault only harvests and releases
    /// compound; harvest does not modify attributed idle. Its exact idle increase
    /// is therefore the designated compound, never donated/raw token balances.
    function _includeCompound(uint256 id) private {
        Snapshot memory s = snapshot;
        if (s.value == 0 || s.bucketId != id || compoundIncluded) revert InvalidState();
        Position memory p = IZZZVault(vault()).group(id);
        snapshot.value = s.value + _value(p.idle0 - s.idle0, p.idle1 - s.idle1, s);
        compoundIncluded = true;
    }
    function _afterMove(uint256 id) private {
        Snapshot memory s = snapshot;
        if (s.value == 0 || s.bucketId != id || !compoundIncluded) revert InvalidState();
        (uint256 deployed, uint256 idle,bytes32 targetPool) = _pricing().checkMaintenance(id,s.value,
            s.price0,s.price1,s.scale0,s.scale1,s.lossBps,s.maxIdleBps,s.maintenancePolicy);
        // Round the captured retained-value floor up. Later policy changes cannot
        // weaken this operation's aggregate budget. Gas is
        // outside these custody ledgers. Keep the captured maintenance idle ceiling under
        // this same vector, including when an admitted feed changes mid-call.
        // A reviewed same-pair move deliberately changes the destination pool.
        // Preserve the ORIGINAL raw observation/control across all callbacks;
        // Manager's separate context freezes target execution controls.
        if (s.confirmationControl != _confirmationControl(id,s.sourcePool)) revert Slippage();
        if (!emergencyActive) {
            IBudgetPortfolioPolicy policy = _portfolioPolicy();
            if (policy.revision() != s.portfolioRevision) revert InvalidState();
            if (s.replacement && policy.enabled(targetPool)) {
                _pricing().assertPortfolioUtilization(id,s.price0,s.price1,s.scale0,s.scale1);
            }
        }
        delete snapshot;
        delete compoundIncluded;
        emit MigrationValueChecked(id, s.value, deployed, idle);
    }
    function _value(uint256 amount0, uint256 amount1, Snapshot memory s) private pure returns (uint256) {
        return Math.mulDiv(amount0, s.price0, s.scale0) + Math.mulDiv(amount1, s.price1, s.scale1);
    }
    /// @dev Shared current valuation keeps Vault within the standard code limit;
    /// migration checkpoints above deliberately use their cached price vector.
    function _pricing() private view returns(ZZZContributionPricing) {
        return ZZZContributionPricing(IZZZOracle(access.module(Ids.ORACLE)).contributionPricing());
    }
    function valueBucket(uint256 bucket,uint256 amount0,uint256 amount1) external view returns(uint256) {
        return _pricing().valueBucket(bucket,amount0,amount1);
    }
    function nav(uint256 id) public view returns(uint256 deployed,uint256 idle) {
        return _pricing().nav(id);
    }
    function contributionNav(uint256 id) external onlyVault returns(uint256 deployed,uint256 idle) {
        return _pricing().contributionNav(id);
    }
    function assertDeployed(uint256 id) external view {
        if(msg.sender == vault() && _skip(4)) return;
        uint16 cap = snapshot.value != 0 && snapshot.bucketId == id
            ? snapshot.maxIdleBps : _pricing().entryIdleLimit(id);
        _pricing().assertDeployed(id,cap);
    }
    function assertPut(uint256 id, uint256 a0, uint256 a1, uint256 spent0, uint256 spent1,
        uint256 before0, uint256 before1) external view onlyVault {
        Position memory p = IZZZVault(vault()).group(id);
        (address token0, address token1) = poolTokens(p.poolId);
        IZZZLiquidity liquidity = IZZZLiquidity(access.module(Ids.LIQUIDITY));
        IPositionManagerMinimal manager = IPositionManagerMinimal(liquidity.positionManager());
        uint256 secondary = liquidity.secondaryId(p.lpTokenId);
        if (spent0 > a0 || spent1 > a1 || _balance(token0) + spent0 != before0 ||
            _balance(token1) + spent1 != before1 ||
            manager.ownerOf(p.lpTokenId) != vault() ||
            (secondary != 0 && (secondary == p.lpTokenId || manager.ownerOf(secondary) != vault()))) revert InvalidState();
    }
    function validateNativeSender(address sender) external view onlyVault returns (bool liquidityCredit) {
        address manager = access.module(Ids.LIQUIDITY);
        liquidityCredit = manager != address(0) && sender == manager;
        if (!liquidityCredit && manager != address(0)) {
            address operator = IBudgetPositionOperator(manager).positionOperator();
            liquidityCredit = operator != address(0) && sender == operator;
        }
        if (!liquidityCredit && sender != access.module(Ids.FEES) &&
            sender != access.module(Ids.VAULT_CANONICAL)) revert Unauthorized();
    }
    function validateLPReceiver(address sender) external view onlyVault {
        address manager = access.module(Ids.LIQUIDITY);
        if (manager == address(0) || sender != IZZZLiquidity(manager).positionManager()) revert Unauthorized();
    }
    function mintTarget(uint256 id) external view onlyVault returns (int24,int24,uint160) {
        if(emergencyActive) {
            validateEmergency(id);
            (int24 lower,int24 upper) = IEmergencyManifest(access.module(Ids.MIGRATION)).emergencyTarget();
            return(lower,upper,
                IZZZLiquidity(access.module(Ids.LIQUIDITY)).spot(IZZZVault(vault()).group(id).poolId));
        }
        return IZZZStrategy(access.module(Ids.STRATEGY)).target(IZZZVault(vault()).group(id).poolId);
    }
    /// @notice Bind prices, target policy and admitted execution controls across
    /// the Vault's complete approval/balance/reset sequence, not only the router.
    function balanceContext(uint256 id) external view onlyVault returns(bytes32) {
        if(emergencyActive) { validateEmergency(id); return this.emergencyFingerprint(); }
        return IZZZLiquidity(access.module(Ids.LIQUIDITY)).balanceContext(IZZZVault(vault()).group(id).poolId);
    }
    function poolTokens(bytes32 poolId) public view returns (address token0, address token1) {
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
        return (c.key.currency0, c.key.currency1);
    }
    function validateReservation(bytes32 poolId,uint256 bucket) external view onlyVault {
        if (poolId == bytes32(0) || bucket == 0) revert InvalidConfiguration();
        IZZZPools(access.module(Ids.POOLS)).get(poolId);
        uint256 old = IZZZVault(vault()).poolBucket(poolId);
        if (old != 0 && old != bucket) revert InvalidState();
    }
    function validateMove(uint256 id, bytes32 nextPool, uint128 minimumLiquidity) external view onlyVault {
        PoolConfig memory oldConfig = IZZZPools(access.module(Ids.POOLS)).accounting(IZZZVault(vault()).group(id).poolId);
        PoolConfig memory nextConfig = IZZZPools(access.module(Ids.POOLS)).accounting(nextPool);
        if (minimumLiquidity == 0 || oldConfig.key.currency0 != nextConfig.key.currency0 ||
            oldConfig.key.currency1 != nextConfig.key.currency1 || !nextConfig.operationsEnabled) revert InvalidConfiguration();
    }
    function validateUnwind(uint256 id) external view onlyVault {
        if(_skip(2)) return;
        IZZZStrategy(access.module(Ids.STRATEGY)).validateExitPrice(IZZZVault(vault()).group(id).poolId);
    }
    /// @notice Read-only extraction of the Vault's existing terminal holder-exit
    /// preconditions. Caller identity remains supplied by the module-only Vault;
    /// no asset movement or new exit authority is introduced here.
    function validateHolderExit(uint256 id,address migrationCaller)
        external view onlyVault returns(address token0,address token1) {
        return IBudgetVaultValidation(access.module(Ids.VAULT_CANONICAL)).validateHolderExit(id,migrationCaller);
    }
    /// @notice No USD/spot/operations-enabled dependency is required to remove
    /// only the registered residual. The fixed main and all rights remain.
    function validateResidualClose(uint256 id) external view onlyVault {
        _pricing().validateResidualClose(id,emergencyActive || snapshot.value!=0);
    }
    function validateRebalance(uint256 id, uint128 minimumLiquidity) external view onlyVault {
        if(emergencyActive) validateEmergency(id);
        _pricing().validateRebalance(id,minimumLiquidity,emergencyActive,emergencyChecks);
        // Confirmation authenticates this exact Budget caller. Keep that
        // boundary here; the read-only pricing child must never impersonate it.
        if(emergencyActive && !_skip(16) &&
            !IConfirmationControl(IZZZStrategy(access.module(Ids.STRATEGY)).rebalanceConfirmation()).emergencyReady(id))
            revert InvalidState();
    }
    function _confirmationControl(uint256 id,bytes32 poolId) private view returns(bytes32) {
        IConfirmationControl confirmation = IConfirmationControl(
            IZZZStrategy(access.module(Ids.STRATEGY)).rebalanceConfirmation());
        // Compare raw evidence, not post-replacement readiness (the new LP
        // deliberately has a different identity). A callback reset must abort.
        return confirmation.observationFingerprint(id,poolId);
    }
    function idleValue(uint256 id) public view returns (uint256) {
        if(msg.sender == vault() && _skip(4)) return 0; // Internal sentinel, never an external zero USD valuation.
        return _pricing().idleValue(id);
    }
    function assertIdleLoss(uint256 id, uint256 beforeValue) external view onlyVault {
        if(_skip(4)) return;
        uint16 slippage = IZZZPools(access.module(Ids.POOLS)).accounting(IZZZVault(vault()).group(id).poolId).maxSlippageBps;
        if (beforeValue == 0 || idleValue(id) < Math.mulDiv(beforeValue, 10000 - slippage, 10000)) revert Slippage();
    }
    function validateContribution(uint256 id, uint256 bucket, uint256 inputUSD, uint256 inputTotal,
        uint128 minimumLiquidity, bool activation) external onlyVault returns (address token0, address token1, uint32 limits) {
        uint16 captured = contributionLossBps;
        uint16 venue;
        (token0,token1,venue) = IBudgetVaultValidation(access.module(Ids.VAULT_CANONICAL)).validateContribution(
            id,bucket,inputUSD,inputTotal,minimumLiquidity,activation);
        // Carry both limits in the existing third ABI word: low 16 bits are the
        // venue limit; high 16 bits freeze the contribution policy before callbacks.
        limits = uint32(venue) | (uint32(captured) << 16);
        _pricing().begin(id,bucket,inputTotal,inputUSD,limits);
    }
    function contributionResult(uint256 bucket,uint256 inputUSD,uint256 supply,uint256 incumbentNAV,
        uint256 incumbentDeployed,uint256 deployed,uint256 idle,uint32 limits)
        external onlyVault returns(uint256 issued,uint256 netUSD) {
        return _pricing().finish(bucket,inputUSD,supply,incumbentNAV,incumbentDeployed,deployed,idle,limits);
    }
    function historicalCompoundValue(uint256 id) public view returns(uint256) {
        return _pricing().historicalValue(id);
    }
}

