// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {Base64} from "@openzeppelin/contracts/utils/Base64.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {Ids, Position, PositionStatus, PoolConfig} from "./libraries/ZZZTypes.sol";
import {IZZZAccess, IZZZVault, IZZZPools, IZZZLiquidity, IZZZOracle, IZZZFees, IZZZStrategy} from "./interfaces/IZZZ.sol";
import {ZZZArtwork} from "./libraries/ZZZArtwork.sol";
import {IPairVault} from "./ZZZMigrationBudget.sol";
interface IHistoricalCompound { function historicalCompoundValue(uint256 id) external view returns (uint256); }

struct NFTMetadataInput {
    uint256 id;
    uint8 rarity;
    uint8 palette;
    uint8 pattern;
    uint8 stage;
    bool traitsReady;
    bool valuationAvailable;
    uint256 valueUSD;
    // Actual activated ledger weight, not the fixed rarity trait. This does not
    // establish readiness of any individual royalty payment currency.
    uint8 royaltyWeight;
    string baseURI;
}

/// @notice Read-only renderer. It never changes custody or reward eligibility.
/// Valuation fails closed while custody is external/parked or dependencies are
/// unavailable; the NFT explicitly reports an unavailable marked LP value.
contract ZZZNFTMetadata {
    IZZZAccess public immutable access;
    error ValuationUnavailable();
    error InvalidArtwork();
    constructor(address controller) { access = IZZZAccess(controller); }

    /// @notice Fixed artwork lookup only. The NFT retains its draw state/order;
    /// this immutable read-only child holds the same finite prepared tables.
    function artworkItem(uint8 rarity, uint256 item)
        external pure returns (uint8 palette, uint8 pattern, uint8 color) {
        if (rarity > 2 || item >= (rarity == 0 ? 600 : rarity == 1 ? 300 : 100)) revert InvalidArtwork();
        (palette, pattern) = ZZZArtwork.item(rarity, item);
        color = ZZZArtwork.primaryColor(palette);
    }

    function currentValue(uint256 id) external view returns (uint256 valueUSD) {
        IZZZVault vault = IZZZVault(access.module(Ids.VAULT));
        uint256 bucket = vault.nftBucket(id);
        uint256 shares = vault.sharesOf(id); uint256 supply = vault.bucketTotalShares(bucket);
        Position memory position = vault.group(bucket);
        if (bucket != 0 && shares != 0 && supply >= shares && position.status == PositionStatus.Exited) return 0;
        if (bucket == 0 || shares == 0 || supply < shares || position.status != PositionStatus.Active ||
            position.lpTokenId == 0) revert ValuationUnavailable();
        PoolConfig memory config = IZZZPools(access.module(Ids.POOLS)).accounting(position.poolId);
        // Mark actual concentrated-liquidity amounts only when their spot price
        // agrees with fresh oracle prices. Disabled operations do not invalidate
        // an otherwise honest mark; this view never changes rights or custody.
        IZZZStrategy(access.module(Ids.STRATEGY)).validateExitPrice(position.poolId);
        (uint256 a0, uint256 a1) = IZZZLiquidity(access.module(Ids.LIQUIDITY)).portfolioAmounts(position.lpTokenId);
        IZZZFees fees = IZZZFees(access.module(Ids.FEES));
        a0 += position.idle0 + fees.compoundBalance(bucket, config.key.currency0);
        a1 += position.idle1 + fees.compoundBalance(bucket, config.key.currency1);
        IZZZOracle oracle = IZZZOracle(access.module(Ids.ORACLE));
        uint256 nav = oracle.value(config.key.currency0, a0) + oracle.value(config.key.currency1, a1);
        nav += IHistoricalCompound(address(IPairVault(address(vault)).migrationBudget())).historicalCompoundValue(bucket);
        return Math.mulDiv(nav, shares, supply);
    }

    function render(NFTMetadataInput calldata input) external pure returns (string memory) {
        string memory rarity = input.traitsReady ? _rarity(input.rarity) : "Unrevealed";
        string memory state = input.valuationAvailable ? _stage(input.stage) : "Valuation unavailable";
        string memory image;
        if (input.traitsReady) {
            // Activated art is labelled as fallback, never a fabricated Dormant
            // state, when current marked LP valuation cannot be established.
            image = string.concat(input.baseURI, _palette(input.palette, true), "-", _patternFile(input.pattern), "-",
                _rarityFile(input.rarity), "-", _stageFile(input.valuationAvailable ? input.stage : 1), ".svg");
        } else {
            image = string.concat("data:image/svg+xml;base64,", Base64.encode(bytes(
                '<svg xmlns="http://www.w3.org/2000/svg" width="640" height="800"><rect width="640" height="800" fill="#030a1d"/><ellipse cx="320" cy="365" rx="150" ry="210" fill="#08142a" stroke="#46637a"/><text x="320" y="680" fill="#aac7d8" text-anchor="middle" font-size="20">Awaiting verifiable randomness</text></svg>')));
        }
        string memory description = input.stage == 4 ?
            "LP exited. Returned principal entitlement, unclaimed rewards and future royalty rights follow this NFT." :
            !input.traitsReady ? "Dormant NFT. Verifiable rarity, palette and circuit reveal pending." :
            input.valuationAvailable ? "Permanent LP fee rights follow this NFT. Rarity weights only NFT-sale royalties." :
            "Current LP valuation unavailable. Activated artwork is a fallback; royalty eligibility and fee rights remain.";
        bytes memory json = abi.encodePacked('{"name":"PoPL #', Strings.toString(input.id),
            '","description":"', description, '","image":"', Strings.escapeJSON(image),
            '","valuation_available":', input.valuationAvailable ? "true" : "false",
            ',"lp_exited":', input.stage == 4 ? "true" : "false",
            ',"royalty_activated":', input.royaltyWeight != 0 ? "true" : "false",
            ',"lp_value_usd_18":', input.valuationAvailable ? string.concat('"', Strings.toString(input.valueUSD), '"') : "null",
            ',"attributes":[{"trait_type":"Rarity","value":"', rarity,
            '"}', _visualAttributes(input), ',{"trait_type":"Evolution","value":"', state,
            '"},{"trait_type":"NFT-sale royalty weight","value":',
            input.traitsReady ? Strings.toString(uint256(input.rarity) + 1) : '"Unrevealed"', '}]}');
        return string.concat("data:application/json;base64,", Base64.encode(json));
    }

    function _rarity(uint8 value) private pure returns (string memory) {
        return value == 0 ? "Commun" : value == 1 ? "Rare" : "Legendary";
    }
    function _rarityFile(uint8 value) private pure returns (string memory) {
        return value == 0 ? "commun" : value == 1 ? "rare" : "legendary";
    }
    function _color(uint8 value) private pure returns (string memory) {
        string[8] memory labels = ["Cyan", "Blue", "Violet", "Emerald", "Amber", "Crimson", "Ivory", "Onyx"];
        return labels[value];
    }
    function _colorFile(uint8 value) private pure returns (string memory) {
        string[8] memory labels = ["cyan", "blue", "violet", "emerald", "amber", "crimson", "ivory", "onyx"];
        return labels[value];
    }
    function _palette(uint8 value, bool filename) private pure returns (string memory label) {
        uint8 colors = ZZZArtwork.mask(value);
        for (uint8 i; i < 8; ++i) {
            if ((colors & (uint8(1) << i)) != 0) {
                string memory part = filename ? _colorFile(i) : _color(i);
                label = bytes(label).length == 0 ? part : string.concat(label, filename ? "-" : " / ", part);
            }
        }
    }
    function _visualAttributes(NFTMetadataInput calldata input) private pure returns (bytes memory attributes) {
        if (!input.traitsReady) return abi.encodePacked(
            ',{"trait_type":"Color style","value":"Unrevealed"}',
            ',{"trait_type":"Palette","value":"Unrevealed"}',
            ',{"trait_type":"Circuit pattern","value":"Unrevealed"}');
        string memory style = input.palette < 8 ? "Monochrome" : input.palette < 30 ? "Bicolor" : "Tricolor";
        attributes = abi.encodePacked(',{"trait_type":"Color style","value":"', style,
            '"},{"trait_type":"Palette","value":"', _palette(input.palette, false), '"}');
        uint8 colors = ZZZArtwork.mask(input.palette); uint256 number;
        for (uint8 i; i < 8; ++i) {
            if ((colors & (uint8(1) << i)) != 0) {
                attributes = abi.encodePacked(attributes, ',{"trait_type":"Color ', Strings.toString(++number),
                    '","value":"', _color(i), '"}');
            }
        }
        return abi.encodePacked(attributes, ',{"trait_type":"Circuit pattern","value":"', _pattern(input.pattern), '"}');
    }
    function _pattern(uint8 value) private pure returns (string memory) {
        string[4] memory labels = ["Flowing arcs", "Segmented panels", "Orbital rings", "Twin circuit routes"];
        return labels[value];
    }
    function _patternFile(uint8 value) private pure returns (string memory) {
        string[4] memory labels = ["arcs", "panels", "orbits", "ribs"];
        return labels[value];
    }
    function _stage(uint8 value) private pure returns (string memory) {
        if (value == 4) return "LP exited";
        string[4] memory labels = ["Dormant", "Activated", "Enhanced", "Singularity"];
        return labels[value];
    }
    function _stageFile(uint8 value) private pure returns (string memory) {
        if (value == 4) return "activated";
        string[4] memory labels = ["dormant", "activated", "enhanced", "singularity"];
        return labels[value];
    }
}

src/ZZZOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {ZZZModule} from "./base/ZZZModule.sol";
import {IZZZProtocolPolicy} from "./interfaces/IZZZProtocolPolicy.sol";
import {IPriceFeed} from "./interfaces/IZZZ.sol";
import {ZZZContributionPricing} from "./ZZZContributionPricing.sol";
import {ZZZPriceMath} from "./libraries/ZZZPriceMath.sol";

/// @notice Two-source USD consensus. Source independence is a reviewed governance
/// assertion, not something two addresses or two matching answers can prove.
contract ZZZOracle is ZZZModule {
    ZZZContributionPricing public immutable contributionPricing;
    uint256 public constant PRICING_VERSION = 2;
    uint16 public constant MAX_DEVIATION_BPS = 500;
    bytes32 public constant FINGERPRINT_DOMAIN = keccak256("ZZZ_DUAL_USD_V2");
    struct SourcePolicy {
        address source;
        bytes32 expectedCodeHash;
        bytes32 independenceId;
        uint32 maxAge;
        uint8 feedDecimals;
    }
    struct DualPolicy {
        address token;
        SourcePolicy primary;
        SourcePolicy secondary;
        uint16 maxDeviationBps;
        uint8 assetDecimals;
        bytes32 reviewHash;
    }
    struct Round {
        uint80 round;
        int256 answer;
        uint256 startedAt;
        uint256 updatedAt;
        uint80 answeredInRound;
    }
    mapping(bytes32 => DualPolicy) private policies;
    mapping(address => bytes32) public activePolicy;
    bytes32[] private history;
    struct SequencerPolicy { address source; bytes32 expectedCodeHash; bytes32 reviewHash; bool bootstrapAdmission; }
    // The getter ABI is unchanged. Only governed, reviewed nonzero replacements
    // are possible; configuration never removes an existing uptime safeguard.
    address public sequencerFeed;
    mapping(bytes32 => SequencerPolicy) public sequencerPolicies;
    bytes32 public activeSequencerPolicy;
    bytes32[] private sequencerHistory;
    uint256 public constant SEQUENCER_GRACE = 1 hours;
    event DualPolicyRecorded(bytes32 indexed id, address indexed token, address indexed primary,
        address secondary, bytes32 primaryIndependenceId, bytes32 secondaryIndependenceId,
        uint16 maxDeviationBps, bytes32 reviewHash);
    event DualPolicyActivated(address indexed token, bytes32 indexed previousPolicy, bytes32 indexed activePolicy);
    event SequencerPolicyRecorded(bytes32 indexed id, address indexed source, bytes32 expectedCodeHash,
        bytes32 reviewHash, bool bootstrapAdmission);
    event SequencerPolicyActivated(bytes32 indexed previousPolicy, bytes32 indexed activePolicy);
    error InvalidPrice(address token);
    constructor(address controller, address sequencer) ZZZModule(controller) {
        contributionPricing = new ZZZContributionPricing(controller,address(this));
        if (sequencer != address(0)) {
            bytes32 codeHash = sequencer.codehash;
            _sequencerData(sequencer, codeHash);
            // A deployment admission reference is provenance, not an independent
            // review. Production qualification must separately review this pin.
            bytes32 admissionReference = keccak256(abi.encode("ZZZ_SEQUENCER_BOOTSTRAP_V1", sequencer, codeHash));
            _recordSequencer(SequencerPolicy(sequencer, codeHash, admissionReference, true));
        }
    }
    function sequencerPolicyCount() external view returns (uint256) { return sequencerHistory.length; }
    function sequencerPolicyAt(uint256 ordinal) external view returns (bytes32) { return sequencerHistory[ordinal]; }
    /// @notice Replace a failed/deprecated uptime dependency through the existing
    /// governance authority after sealing. Never query the old dependency here.
    /// A down or recovering new feed remains unusable for price reads until up
    /// and beyond the mandatory grace period; review does not waive that guard.
    function setSequencerFeed(address source, bytes32 expectedCodeHash, bytes32 reviewHash)
        external onlyGovernance returns (bytes32 id) {
        if (source == address(0) || reviewHash == bytes32(0)) revert InvalidConfiguration();
        _sequencerData(source, expectedCodeHash);
        return _recordSequencer(SequencerPolicy(source, expectedCodeHash, reviewHash, false));
    }
    function _recordSequencer(SequencerPolicy memory entry) private returns (bytes32 id) {
        bytes32 previous = activeSequencerPolicy;
        id = keccak256(abi.encode(address(this), sequencerHistory.length, entry));
        sequencerPolicies[id] = entry;
        sequencerHistory.push(id);
        activeSequencerPolicy = id;
        sequencerFeed = entry.source;
        emit SequencerPolicyRecorded(id, entry.source, entry.expectedCodeHash, entry.reviewHash,
            entry.bootstrapAdmission);
        emit SequencerPolicyActivated(previous, id);
    }
    function _sequencerData(address source, bytes32 expectedCodeHash) private view
        returns (int256 answer, uint256 startedAt) {
        if (source.code.length == 0 || expectedCodeHash == bytes32(0) || source.codehash != expectedCodeHash ||
            _decimals(source, source) != 0) revert InvalidConfiguration();
        uint256 round; uint256 answeredRound; uint256 updated;
        (round, answer, startedAt, updated, answeredRound) = abi.decode(
            _boundedRead(source, IPriceFeed.latestRoundData.selector, 160, source),
            (uint256, int256, uint256, uint256, uint256));
        if (round == 0 || round > type(uint80).max || answeredRound > type(uint80).max ||
            answeredRound < round || (answer != 0 && answer != 1) || startedAt == 0 ||
            startedAt > block.timestamp || updated < startedAt || updated > block.timestamp) revert InvalidPrice(source);
        // Uptime feeds report status transitions, not periodic price rounds. A
        // healthy unchanged status must not expire based on updatedAt age.
    }
    function policyCount() external view returns (uint256) { return history.length; }
    function policyAt(uint256 ordinal) external view returns (bytes32) { return history[ordinal]; }
    function policy(bytes32 id) external view returns (DualPolicy memory) { return policies[id]; }
    /// @notice Append and activate a reviewed, two-source policy. No stale-price,
    /// single-source, target-pool or presumed stable-peg fallback is available.
    /// Zero spread permits exact agreement only; 500bps is a hard safety ceiling,
    /// not a production recommendation. A particular asset needs reviewed bounds.
    function setDualFeed(address token, SourcePolicy calldata primary, SourcePolicy calldata secondary,
        uint16 maxDeviationBps, bytes32 reviewHash) external onlyGovernance returns (bytes32 id) {
        if (reviewHash == bytes32(0) || maxDeviationBps > MAX_DEVIATION_BPS ||
            primary.source == secondary.source || primary.independenceId == bytes32(0) ||
            primary.independenceId == secondary.independenceId || secondary.independenceId == bytes32(0)) {
            revert InvalidConfiguration();
        }
        uint8 assetDecimals = token == address(0) ? 18 : _decimals(token, token);
        if (assetDecimals > 18) revert InvalidConfiguration();
        DualPolicy memory next = DualPolicy(token, primary, secondary, maxDeviationBps, assetDecimals, reviewHash);
        // Reject an invalid current observation at admission too. Static source
        // calls cannot mutate the policy or its authority during these checks.
        // _round also validates each source policy: do not repeat those calls.
        _readBounds(next);
        bytes32 previous = activePolicy[token];
        id = keccak256(abi.encode(address(this), history.length, next));
        policies[id] = next;
        history.push(id);
        activePolicy[token] = id;
        emit DualPolicyRecorded(id, token, primary.source, secondary.source, primary.independenceId,
            secondary.independenceId, maxDeviationBps, reviewHash);
        emit DualPolicyActivated(token, previous, id);
    }
    function _boundedRead(address source, bytes4 selector, uint256 expectedLength, address token)
        private view returns (bytes memory result) {
        bool success;
        uint256 returned;
        uint256 gasLimit = IZZZProtocolPolicy(access.protocolPolicy()).sourceCallGas();
        // Copy only the exact bounded ABI result. A source cannot make the
        // caller allocate arbitrary returndata or disclose its revert payload.
        assembly ("memory-safe") {
            let input := mload(0x40)
            mstore(input, selector)
            success := staticcall(gasLimit, source, input, 4, 0, 0)
            returned := returndatasize()
        }
        if (!success || returned != expectedLength) revert InvalidPrice(token);
        result = new bytes(expectedLength);
        assembly ("memory-safe") { returndatacopy(add(result, 32), 0, expectedLength) }
    }
    function _decimals(address source, address token) private view returns (uint8 digits) {
        if (source.code.length == 0) revert InvalidConfiguration();
        uint256 decoded = abi.decode(_boundedRead(source, IPriceFeed.decimals.selector, 32, token), (uint256));
        if (decoded > 18) revert InvalidConfiguration();
        digits = uint8(decoded);
    }
    function _validateSource(SourcePolicy memory source, address token) private view {
        if (source.source.code.length == 0 || source.expectedCodeHash == bytes32(0) ||
            source.source.codehash != source.expectedCodeHash || source.maxAge == 0 || source.maxAge > 1 days ||
            source.feedDecimals > 18 || _decimals(source.source, token) != source.feedDecimals) {
            revert InvalidConfiguration();
        }
    }
    function _round(SourcePolicy memory source, address token) private view returns (Round memory r, uint256 usd) {
        _validateSource(source, token);
        bytes memory encoded = _boundedRead(source.source, IPriceFeed.latestRoundData.selector, 160, token);
        // Decode wide words first so noncanonical narrow integers produce the
        // same bounded domain error as other malformed source responses.
        (uint256 round, int256 answer, uint256 started, uint256 updated, uint256 answered) =
            abi.decode(encoded, (uint256, int256, uint256, uint256, uint256));
        if (round == 0 || round > type(uint80).max || answered > type(uint80).max || answered < round ||
            answer <= 0 || started == 0 || started > updated || updated == 0 || updated > block.timestamp ||
            block.timestamp - updated > source.maxAge) revert InvalidPrice(token);
        uint256 scale = 10 ** (18 - source.feedDecimals);
        if (uint256(answer) > 1e36 / scale) revert InvalidPrice(token);
        usd = uint256(answer) * scale;
        r = Round(uint80(round), answer, started, updated, uint80(answered));
    }
    function _readBounds(DualPolicy memory p)
        private view returns (uint256 lower, uint256 upper, Round memory first, Round memory second) {
        uint256 a;
        uint256 b;
        (first, a) = _round(p.primary, p.token);
        (second, b) = _round(p.secondary, p.token);
        lower = Math.min(a, b);
        upper = Math.max(a, b);
        // The denominator is the lower price. Rounding cannot admit a spread
        // one raw unit above the configured tolerance.
        if (upper - lower > Math.mulDiv(lower, p.maxDeviationBps, 10000)) revert InvalidPrice(p.token);
    }
    function _sequencerCheck() private view {
        if (sequencerFeed == address(0)) return;
        SequencerPolicy memory entry = sequencerPolicies[activeSequencerPolicy];
        (int256 answer, uint256 startedAt) = _sequencerData(sequencerFeed, entry.expectedCodeHash);
        if (answer != 0 || block.timestamp - startedAt <= SEQUENCER_GRACE) revert InvalidPrice(sequencerFeed);
    }
    function priceBounds(address token) public view returns (uint256 lower, uint256 upper, bytes32 fingerprint) {
        _sequencerCheck();
        bytes32 id = activePolicy[token];
        if (id == bytes32(0)) revert InvalidPrice(token);
        DualPolicy memory p = policies[id];
        if (token != address(0) && _decimals(token, token) != p.assetDecimals) revert InvalidConfiguration();
        Round memory first;
        Round memory second;
        (lower, upper, first, second) = _readBounds(p);
        fingerprint = keccak256(abi.encode(FINGERPRINT_DOMAIN, block.chainid, address(this), id,
            activeSequencerPolicy, first, second));
    }
    /// @notice Lower bound for minimum-contribution and ordinary display values.
    function price(address token) public view returns (uint256 normalizedUSD) {
        (normalizedUSD,,) = priceBounds(token);
    }
    function tokenDecimals(address token) public view returns (uint8) {
        bytes32 id = activePolicy[token];
        if (id == bytes32(0)) revert InvalidPrice(token);
        return policies[id].assetDecimals;
    }
    function value(address token, uint256 amount) public view returns (uint256) {
        return Math.mulDiv(amount, price(token), 10 ** tokenDecimals(token));
    }
    function quote(address input, address output, uint256 amount) external view returns (uint256) {
        (, uint256 upper,) = priceBounds(input);
        if (input == output) return amount;
        (uint256 lower,,) = priceBounds(output);
        uint256 sourceUSD = Math.mulDiv(amount, upper, 10 ** tokenDecimals(input));
        return Math.mulDiv(sourceUSD, 10 ** tokenDecimals(output), lower);
    }
    function referenceX96(address token0, address token1) external view returns (uint160) {
        return ZZZPriceMath.referenceX96(price(token0),price(token1),
            tokenDecimals(token0),tokenDecimals(token1),token0);
    }
}

src/ZZZPoolRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {ZZZModule} from "./base/ZZZModule.sol";
import {Ids, PoolKey, PoolConfig} from "./libraries/ZZZTypes.sol";
import {IZZZOracle, IZZZRewards, IZZZLiquidity, IStateViewMinimal} from "./interfaces/IZZZ.sol";
import {ZZZActivationAssets} from "./ZZZActivationAssets.sol";
import {ZZZActivationEntry} from "./ZZZActivationEntry.sol";
import {ZZZActivationAssetsFactory} from "./ZZZActivationAssetsFactory.sol";

interface INativeVenueBindings {
    function poolManager() external view returns (address);
    function stateView() external view returns (address);
    function permit2() external view returns (address);
}
interface ICollectiveExitPhase {
    function exitPhase() external view returns (uint8);
}

/// @notice Append-only pool identities; bounded strategy parameters are governed.
/// Native support is restricted to static, hookless ETH/ZZZ on pinned Robinhood v4.
/// Both get() and accounting() preserve the real native ETH identity at slot zero.
contract ZZZPoolRegistry is ZZZModule {
    ZZZActivationAssets public immutable activationAssets;
    ZZZActivationEntry public immutable activationEntry;
    bytes32 public constant SELECTED_NATIVE_POOL = 0x501122bfd256e408a63bddad901cc19a2512d74b2006f0474a3cf480e94afe1b;
    address private constant CORE = 0x8366a39CC670B4001A1121B8F6A443A643e40951;
    address private constant POSM = 0x58daec3116aae6D93017bAAea7749052E8a04fA7;
    address private constant STATE = 0xF3334192D15450CdD385c8B70e03f9A6bD9E673b;
    address private constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;
    address private constant ZZZ = 0x7dbf38976f6D3b9c529e7D9484A71898B409eE6a;
    mapping(bytes32 => PoolConfig) private pools;
    mapping(bytes32 => bool) public exists;
    /// @notice Zero means contributions are stopped. Historical/maintenance
    /// pools remain admitted, but at most one pool can enable new contributions.
    bytes32 public contributionPool;
    /// @notice Invalidates atomic execution reviews even if a callback restores
    /// the old values. Append-only storage; no change to historical deployments.
    uint64 public configurationRevision;
    event PoolConfigured(bytes32 indexed poolId, address indexed token0, address indexed token1);
    event PoolDisabled(bytes32 indexed poolId, bool depositsEnabled, bool operationsEnabled);
    event ContributionPoolChanged(bytes32 indexed previousPool, bytes32 indexed currentPool);
    constructor(address controller) ZZZModule(controller) {
        activationAssets = ZZZActivationAssets(ZZZActivationAssetsFactory(access.activationAssetsFactory()).create());
        activationEntry = new ZZZActivationEntry(controller, address(this), address(activationAssets));
    }
    modifier nativeConfiguration(bool depositsEnabled) {
        _checkNativeConfiguration(depositsEnabled);
        _;
        _checkNativeConfiguration(depositsEnabled);
    }
    function _checkNativeConfiguration(bool depositsEnabled) private view {
        // Migration.Ready (3) means every bucket is closed and principal is
        // allocated. Only remaining protocol reserves may use a restored/new
        // venue; terminal Vault locks cannot be reopened by this configuration.
        if (access.lpExitStarted() && (depositsEnabled ||
            ICollectiveExitPhase(access.module(Ids.MIGRATION)).exitPhase() != 3)) revert LPExitLocked();
    }
    /// @notice Admit a static hookless ETH/ZZZ pool, including future fee tiers.
    /// The selected launch identity does not prevent governed moves after sealing.
    /// Only native ETH/fixed ZZZ LP is admitted: every funded bucket must remain
    /// settleable to holders as ETH + ZZZ. ERC20 conversion venues are separate.
    /// Runtime/wiring are rechecked on every accounting/isNativePool read.
    /// After completed collective exit only deposits-disabled venue admission
    /// remains available, so the separate buyback reserve need not be stranded.
    function configureNative(PoolConfig calldata config) external onlyGovernance nativeConfiguration(config.depositsEnabled) returns (bytes32 poolId) {
        PoolKey memory key = config.key;
        if (key.currency0 != address(0) || key.currency1 != ZZZ || key.hooks != address(0) || key.fee > 100000 ||
            activationAssets.zzz() != ZZZ) {
            revert InvalidConfiguration();
        }
        _nativeBindings();
        poolId = keccak256(abi.encode(key));
        // Core protocol fees can change independently of the immutable static LP fee.
        // Swaps enforce actual net output; a fee-policy change must not freeze custody.
        (uint160 price,,, uint24 lpFee) = IStateViewMinimal(STATE).getSlot0(poolId);
        if (price == 0 || lpFee != key.fee) revert InvalidConfiguration();
        return _configure(config, address(0), ZZZ);
    }
    /// @notice Restrict an admitted pool without reading tokens, prices or venue
    /// dependencies. True flags DISABLE the respective capability; false keeps
    /// its current state. Re-enabling requires full configureNative validation.
    function disablePool(bytes32 poolId, bool disableDeposits, bool disableOperations) external onlyGovernance {
        if (!exists[poolId] || (!disableDeposits && !disableOperations)) revert InvalidConfiguration();
        PoolConfig storage config = pools[poolId];
        if (disableDeposits) {
            config.depositsEnabled = false;
            if (contributionPool == poolId) _setContributionPool(bytes32(0));
        }
        if (disableOperations) config.operationsEnabled = false;
        ++configurationRevision;
        emit PoolDisabled(poolId, config.depositsEnabled, config.operationsEnabled);
    }
    /// @notice Fixed Strategy may apply only its reviewed two-width policy.
    /// No keeper can call this directly or change assets, flags or other limits.
    function applyKeeperRange(bytes32 poolId,uint16 width) external onlyModule(Ids.STRATEGY) {
        // The fixed controller's moduleAuthorized already enforces sealed and
        // canonical-operating identity. All remaining calls are static and all
        // writes below are local: there is no callback requiring a second read.
        if (access.paused()) revert Paused();
        if (access.preparationActive()) revert Preparing();
        if (access.lpExitStarted()) revert LPExitLocked();
        PoolConfig storage c = pools[poolId];
        if (!exists[poolId] || !c.operationsEnabled || (width != 2500 && width != 5000) ||
            c.triggerBps >= width || c.maxSpotDeviationBps >= width) revert InvalidConfiguration();
        c.rangeBps = width; // Strategy emits the successful old/new width and review hash.
        ++configurationRevision;
    }
    function _configure(PoolConfig calldata config, address token0, address token1) internal returns (bytes32 poolId) {
        PoolKey memory k = config.key;
        poolId = keccak256(abi.encode(k));
        if (poolId == bytes32(0) || (config.depositsEnabled && contributionPool != bytes32(0) &&
            contributionPool != poolId)) revert InvalidConfiguration();
        if (k.tickSpacing <= 0 || k.tickSpacing > 32767 || k.fee > 100000 ||
            config.rangeBps < 100 || config.rangeBps >= 10000 || config.triggerBps < 100 ||
            config.triggerBps >= config.rangeBps || config.maxSpotDeviationBps == 0 ||
            config.maxSpotDeviationBps > 500 || config.maxSpotDeviationBps >= config.rangeBps || config.maxSlippageBps == 0 || config.maxSlippageBps > 1000 || k.fee >= uint24(config.maxSlippageBps) * 100 ||
            config.minRebalanceInterval < 600 || config.minRebalanceInterval > 7 days ||
            config.minDepositUSD == 0 || config.maxPositionUSD < config.minDepositUSD) revert InvalidConfiguration();
        IZZZOracle oracle = IZZZOracle(access.module(Ids.ORACLE));
        oracle.price(token0);
        oracle.price(token1);
        IZZZRewards rewards = IZZZRewards(access.module(Ids.REWARDS));
        if (!rewards.isAsset(token0) || !rewards.isAsset(token1)) revert InvalidConfiguration();
        activationAssets.admitPoolAsset(token0);
        activationAssets.admitPoolAsset(token1);
        pools[poolId] = config;
        exists[poolId] = true;
        if (config.depositsEnabled) _setContributionPool(poolId);
        else if (contributionPool == poolId) _setContributionPool(bytes32(0));
        ++configurationRevision;
        emit PoolConfigured(poolId, k.currency0, k.currency1);
    }
    function _setContributionPool(bytes32 poolId) private {
        bytes32 previous = contributionPool;
        if (previous == poolId) return;
        contributionPool = poolId;
        emit ContributionPoolChanged(previous, poolId);
    }
    function get(bytes32 poolId) external view returns (PoolConfig memory) {
        if (!exists[poolId]) revert InvalidConfiguration();
        return pools[poolId];
    }
    function accounting(bytes32 poolId) public view returns (PoolConfig memory c) {
        if (!exists[poolId]) revert InvalidConfiguration();
        c = pools[poolId];
        if (c.key.currency0 == address(0)) {
            _nativeBindings();
        }
    }
    /// @notice Source eligibility affects new contributions only, never existing LP/reward ledgers.
    function contributionValue(bytes32 poolId, uint256 amount0, uint256 amount1) external view returns (uint256) {
        if (msg.sender == access.module(Ids.VAULT)) {
            // Only the immutable child's actual fixed Vault call can carry an
            // original-source valuation. An armed mismatched context reverts.
            uint256 sourceUSD = activationEntry.sourceValue(poolId, amount0, amount1);
            if (sourceUSD != 0) return sourceUSD;
        }
        PoolConfig memory c = accounting(poolId);
        return activationAssets.value(c.key.currency0, amount0) + activationAssets.value(c.key.currency1, amount1);
    }
    /// @notice Whether an admitted pool settles its first currency as native ETH.
    function isNativePool(bytes32 poolId) public view returns (bool) {
        if (!exists[poolId]) revert InvalidConfiguration();
        if (pools[poolId].key.currency0 != address(0)) return false;
        _nativeBindings();
        return true;
    }
    function _nativeBindings() internal view virtual {
        if (block.chainid != 4663 ||
            CORE.codehash != 0xbd3881180b547f5fe817545743cfb4343e96b1bc6640dcd70c106b0066e95626 ||
            POSM.codehash != 0xc873e135dc9aaec88489cfbad146b4cb49d6a32e0d80326377784b7ba17670b2 ||
            STATE.codehash != 0x7d9c591e0956fd89d98feb4ffcfe8bf1f7a62bd485edd979fa21d104b49878a6 ||
            PERMIT2.codehash != 0x5208783f52488f7d3493e5e38311ab707c1d75457fe472a19b0b4d57d66a7fca ||
            ZZZ.codehash != 0x3d5ba33c3a94f655c16348011ff2c72f6ce8085239454ce4a6c4bf284e84a597) {
            revert InvalidConfiguration();
        }
        // Native settlement and custody do not call or rely on WETH, its
        // implementation, its admin, or the periphery's optional wrapper getter.
        address manager = access.module(Ids.LIQUIDITY);
        if (IZZZLiquidity(manager).positionManager() != POSM ||
            INativeVenueBindings(manager).poolManager() != CORE || INativeVenueBindings(manager).stateView() != STATE ||
            INativeVenueBindings(manager).permit2() != PERMIT2) {
            revert InvalidConfiguration();
        }
    }
}

src/ZZZPortfolioPolicy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {ZZZModule} from "./base/ZZZModule.sol";
import {Ids, PoolKey, PoolConfig, Position, PositionStatus} from "./libraries/ZZZTypes.sol";
import {IZZZPools, IZZZVault, IZZZLiquidity, IPositionManagerMinimal} from "./interfaces/IZZZ.sol";
import {IZZZProtocolPolicy} from "./interfaces/IZZZProtocolPolicy.sol";
import {EmergencyRebalance,IZZZEmergencyController} from "./interfaces/IZZZEmergency.sol";

interface IPortfolioAssociation {
    function secondaryId(uint256 main) external view returns(uint256);
}
interface IPortfolioParent { function portfolioPolicy() external view returns(address); }
interface IPortfolioConsolidation { function consolidationActive() external view returns(bool); }

/// @notice Fixed, noncustodial policy for one main and at most one residual LP.
/// Desired mode never moves assets. Only an atomic guarded adjustment applies it.
contract ZZZPortfolioPolicy is ZZZModule {
    uint256 public constant PORTFOLIO_VERSION = 2;
    uint256 public constant RESIDUAL_REINVEST_VERSION = 1;
    uint16 public constant HARD_MINIMUM_MAIN_BPS = 6000;
    uint16 public constant HARD_MAXIMUM_RESIDUAL_BPS = 4000;
    uint16 public constant DEFAULT_RESIDUAL_SIDE_BPS = 5000;
    uint16 public thresholdBps = 8500;
    uint64 public revision;
    uint64 public triggerRevision;
    mapping(bytes32 => uint64) public controlRevision;
    mapping(bytes32 => bool) public enabled;
    mapping(bytes32 => uint64) public geometryRevision;
    /// @dev Zero storage selects the explicitly approved half-side default.
    mapping(bytes32 => uint16) private configuredResidualSideBps;
    mapping(bytes32 => uint16) private configuredMinimumMainBps;
    mapping(bytes32 => uint24) private configuredResidualGap;
    mapping(bytes32 => bytes32) public residualReviewHash;
    mapping(uint256 => uint64) public appliedRevision;
    mapping(bytes32 => bytes32) public modeReviewHash;
    bytes32 public triggerReviewHash;
    uint256 private constant UNIT = 1e18;

    event PortfolioModeConfigured(bytes32 indexed pool,bool enabled,uint64 geometryRevision,uint64 revision,bytes32 indexed reviewHash);
    event PortfolioTriggerConfigured(uint16 previous,uint16 current,uint64 revision,bytes32 indexed reviewHash);
    event ResidualSideConfigured(bytes32 indexed pool,uint16 previous,uint16 current,uint64 geometryRevision,uint64 revision,bytes32 indexed reviewHash);
    event PortfolioApplied(uint256 indexed main,bytes32 indexed pool,uint64 geometryRevision);
    event MainAllocationConfigured(bytes32 indexed pool,uint16 minimumMainBps,uint64 geometryRevision,bytes32 indexed reviewHash);
    event ResidualGapConfigured(bytes32 indexed pool,uint24 spacings,uint64 geometryRevision,bytes32 indexed reviewHash);

    constructor(address controller) ZZZModule(controller) {}
    /// @notice The sealed controller fixes the sole Strategy parent. Standalone
    /// creation avoids embedding helper initcode; there is no parent setter.
    function strategy() public view returns(address) { return access.module(Ids.STRATEGY); }

    function setMode(bytes32 pool,bool next,bytes32 reviewed)
        external onlyGovernance operating principalOperating {
        if(reviewed == bytes32(0) || enabled[pool] == next) revert InvalidConfiguration();
        // Disabling an already enabled mode records a desired safe merge; it
        // must not depend on a currently failing external venue binding.
        if(next) _pool(pool);
        enabled[pool] = next;
        modeReviewHash[pool] = reviewed;
        ++geometryRevision[pool];
        ++controlRevision[pool];
        ++revision;
        emit PortfolioModeConfigured(pool,next,geometryRevision[pool],revision,reviewed);
    }

    function configureResidualSide(bytes32 pool,uint16 next,bytes32 reviewed)
        external onlyGovernance operating principalOperating {
        if(next == 0 || next > 10000 || reviewed == bytes32(0)) revert InvalidConfiguration();
        _pool(pool);
        uint16 previous = residualSideBps(pool);
        configuredResidualSideBps[pool] = next;
        residualReviewHash[pool] = reviewed;
        // An unused residual setting cannot force a single-position trade.
        // Relevant samples/reviews use this pool's control revision; unrelated
        // pools and cosmetic/read-only policies cannot reset its evidence.
        if(enabled[pool]) ++geometryRevision[pool];
        ++controlRevision[pool];
        ++revision;
        emit ResidualSideConfigured(pool,previous,next,geometryRevision[pool],revision,reviewed);
    }
    /// @notice 10000 uses the full corresponding main side; 5000 uses half that
    /// side's ZZZ-in-ETH price distance. Mode remains disabled by default.
    function residualSideBps(bytes32 pool) public view returns(uint16 configured) {
        configured = configuredResidualSideBps[pool];
        if(configured == 0) configured = DEFAULT_RESIDUAL_SIDE_BPS;
    }
    function minimumMainBps(bytes32 pool) public view returns(uint16 configured) {
        configured=configuredMinimumMainBps[pool];
        if(configured==0)configured=HARD_MINIMUM_MAIN_BPS;
    }
    function maximumResidualBps(bytes32 pool) external view returns(uint16){return 10000-minimumMainBps(pool);}
    function residualGapSpacings(bytes32 pool) public view returns(uint24 configured){
        configured=configuredResidualGap[pool];if(configured==0)configured=1;
    }
    /// @notice Raise the qualifying main allocation within the approved60/40
    /// envelope.100% is expressed by single mode, not an impossible zero-dust
    /// hybrid promise. Very strict floors can be unavailable until loosened.
    function configureMainAllocation(bytes32 pool,uint16 next,bytes32 reviewed)
        external onlyGovernance operating principalOperating {
        if(next<HARD_MINIMUM_MAIN_BPS || next>=10000 || reviewed==bytes32(0))revert InvalidConfiguration();
        _pool(pool);configuredMinimumMainBps[pool]=next;
        if(enabled[pool])++geometryRevision[pool];++controlRevision[pool];++revision;
        emit MainAllocationConfigured(pool,next,geometryRevision[pool],reviewed);
    }
    /// @notice The bound derives from the complete TickMath domain. Actual
    /// main-side width may be smaller and must still be feasible at execution.
    function configureResidualGap(bytes32 pool,uint24 next,bytes32 reviewed)
        external onlyGovernance operating principalOperating {
        PoolConfig memory c=_pool(pool);
        if(next==0 || reviewed==bytes32(0) || uint256(next)*uint256(uint24(c.key.tickSpacing))>=
            uint256(int256(TickMath.MAX_TICK)-int256(TickMath.MIN_TICK)))revert InvalidConfiguration();
        configuredResidualGap[pool]=next;
        if(enabled[pool])++geometryRevision[pool];++controlRevision[pool];++revision;
        emit ResidualGapConfigured(pool,next,geometryRevision[pool],reviewed);
    }

    /// @notice Percentage of actual centre-to-boundary PRICE distance, not ticks,
    /// square-root distance or percentage change from the centre itself.
    function setTriggerBps(uint16 next,bytes32 reviewed)
        external onlyGovernance operating principalOperating {
        if(next == 0 || next > 10000 || reviewed == bytes32(0)) revert InvalidConfiguration();
        uint16 previous = thresholdBps;
        thresholdBps = next;
        triggerReviewHash = reviewed;
        ++triggerRevision;
        ++revision;
        emit PortfolioTriggerConfigured(previous,next,revision,reviewed);
    }

    /// @notice Records only an actually minted, Vault-owned portfolio. The
    /// current fixed Manager is the sole writer; governance cannot mark a mode
    /// applied without the physical operation that the Manager authenticates.
    function recordApplied(uint256 main,bytes32 pool) external operating principalOperating {
        address manager = access.module(Ids.LIQUIDITY);
        if(!access.isSealed() || msg.sender != manager || manager == address(0) || main == 0 ||
            IPortfolioParent(strategy()).portfolioPolicy() != address(this)) revert Unauthorized();
        _pool(pool);
        IPositionManagerMinimal posm = IPositionManagerMinimal(IZZZLiquidity(manager).positionManager());
        _position(posm,main,pool);
        uint256 secondary = IPortfolioAssociation(manager).secondaryId(main);
        if(secondary != 0) {
            if(!enabled[pool] || secondary == main) revert InvalidState();
            _position(posm,secondary,pool);
        }
        appliedRevision[main] = geometryRevision[pool];
        emit PortfolioApplied(main,pool,geometryRevision[pool]);
    }

    /// @notice Only the fixed paused Migration's active, reviewed same-main
    /// operation may disable residual mode AND acknowledge its physical result.
    /// An independent main-range width update remains pending in Strategy.
    function completeConsolidation()
        external operating principalOperating {
        address migration=access.module(Ids.MIGRATION);
        if(msg.sender!=migration || !access.isSealed() || !access.paused() ||
            !IPortfolioConsolidation(migration).consolidationActive()) revert Unauthorized();
        EmergencyRebalance memory request=IZZZEmergencyController(migration).emergencyRequest();
        Position memory p=IZZZVault(access.module(Ids.VAULT)).group(request.bucket);
        uint256 main=p.lpTokenId; bytes32 pool=p.poolId; bytes32 reviewed=request.reviewHash;
        address manager=access.module(Ids.LIQUIDITY);
        if(reviewed==bytes32(0) || p.status!=PositionStatus.Active ||
            IPortfolioAssociation(manager).secondaryId(main)!=0) revert InvalidState();
        _position(IPositionManagerMinimal(IZZZLiquidity(manager).positionManager()),main,pool);
        if(enabled[pool]) {
            enabled[pool]=false; modeReviewHash[pool]=reviewed;
            ++geometryRevision[pool];
            emit PortfolioModeConfigured(pool,false,geometryRevision[pool],revision+1,reviewed);
        }
        // Manual reinvestment invalidates old samples/jitter even when mode was
        // already OFF and only previously closed attributed idle was consumed.
        ++controlRevision[pool]; ++revision;
        appliedRevision[main]=geometryRevision[pool];
        emit PortfolioApplied(main,pool,geometryRevision[pool]);
    }

    function _position(IPositionManagerMinimal posm,uint256 id,bytes32 pool) private view {
        (PoolKey memory key,uint256 info) = posm.getPoolAndPositionInfo(id);
        int24 lower = int24(uint24(info >> 8));
        int24 upper = int24(uint24(info >> 32));
        if(posm.ownerOf(id) != access.module(Ids.VAULT) || keccak256(abi.encode(key)) != pool ||
            posm.getPositionLiquidity(id) == 0 || lower < TickMath.MIN_TICK || upper > TickMath.MAX_TICK || lower >= upper)
            revert InvalidState();
    }

    /// @notice Explicit mode changes are pending independently of market price.
    /// Trigger-only changes invalidate evidence but do not create this exception.
    function configurationPending(uint256 bucket) external view returns(bool) {
        Position memory p = IZZZVault(access.module(Ids.VAULT)).group(bucket);
        return p.status == PositionStatus.Active && p.lpTokenId != 0 &&
            appliedRevision[p.lpTokenId] != geometryRevision[p.poolId];
    }

    function controlFingerprint(bytes32 pool) external view returns(bytes32) {
        return keccak256(abi.encode(address(this),strategy(),controlRevision[pool],triggerRevision,pool,enabled[pool],thresholdBps,
            geometryRevision[pool],residualSideBps(pool),minimumMainBps(pool),residualGapSpacings(pool),
            modeReviewHash[pool],residualReviewHash[pool],triggerReviewHash,
            IZZZProtocolPolicy(access.protocolPolicy()).maintenanceFingerprint()));
    }

    function _pool(bytes32 pool) private view returns(PoolConfig memory c) {
        c = IZZZPools(access.module(Ids.POOLS)).accounting(pool);
        if(pool == bytes32(0) || keccak256(abi.encode(c.key)) != pool || c.key.currency0 != address(0) ||
            c.key.currency1 == address(0) || c.key.hooks != address(0) || c.key.tickSpacing<=0) revert InvalidConfiguration();
    }

    /// @notice Raw side1=below sqrt range centre, side2=above. Interpolation is
    /// ALWAYS in ZZZ-in-ETH price (inverse pool price), using actual rounded bounds.
    /// Inward rounding is forbidden: floor the observed upper move and ceil its
    /// threshold; ceil the observed lower move and floor its threshold.
    function thresholdSide(uint160 center,int24 lower,int24 upper,uint160 price) external view returns(uint8) {
        if(lower < TickMath.MIN_TICK || upper > TickMath.MAX_TICK || lower >= upper ||
            price < TickMath.MIN_SQRT_PRICE || price >= TickMath.MAX_SQRT_PRICE) revert InvalidState();
        uint160 a = TickMath.getSqrtPriceAtTick(lower);
        uint160 b = TickMath.getSqrtPriceAtTick(upper);
        if(center <= a || center >= b) revert InvalidState();
        if(price <= a) return 1;
        if(price >= b) return 2;
        if(price == center) return 0;
        if(price < center) {
            uint256 observedRise = _ratio(center,price,false);
            uint256 boundaryRise = _ratio(center,a,true);
            uint256 thresholdRise = UNIT + Math.mulDiv(boundaryRise-UNIT,thresholdBps,10000,Math.Rounding.Ceil);
            return observedRise >= thresholdRise ? 1 : 0;
        }
        uint256 observed = _ratio(center,price,true);
        uint256 boundary = _ratio(center,b,false);
        uint256 threshold = UNIT-Math.mulDiv(UNIT-boundary,thresholdBps,10000,Math.Rounding.Ceil);
        return observed <= threshold ? 2 : 0;
    }

    function _ratio(uint160 numerator,uint160 denominator,bool roundUp) private pure returns(uint256) {
        return _ratioScale(numerator,denominator,roundUp,UNIT);
    }
    function _ratioScale(uint160 numerator,uint160 denominator,bool roundUp,uint256 unit) private pure returns(uint256) {
        Math.Rounding rounding = roundUp ? Math.Rounding.Ceil : Math.Rounding.Floor;
        uint256 root = Math.mulDiv(numerator,unit,denominator,rounding);
        return Math.mulDiv(root,root,unit,rounding);
    }

    /// @notice A passive range within the corresponding side of the new main.
    /// The nearest edge leaves at least one full spacing beyond spot. The outer
    /// edge uses the configured fraction of spot-to-main-bound PRICE distance,
    /// rounded inward. Insufficient representable width fails closed.
    function residualRange(bytes32 pool,uint160 current,int24 mainLower,int24 mainUpper,bool residual0)
        external view returns(int24 lower,int24 upper) {
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(pool);
        uint16 fraction = residualSideBps(pool);
        int24 spacing = c.key.tickSpacing;
        if(!enabled[pool] || fraction == 0 || spacing <= 0 || mainLower < TickMath.MIN_TICK ||
            mainUpper > TickMath.MAX_TICK || mainLower >= mainUpper || mainLower % spacing != 0 || mainUpper % spacing != 0)
            revert InvalidConfiguration();
        uint160 a = TickMath.getSqrtPriceAtTick(mainLower);
        uint160 b = TickMath.getSqrtPriceAtTick(mainUpper);
        if(current <= a || current >= b) revert InvalidState();
        int24 tick = TickMath.getTickAtSqrtPrice(current);
        int256 aligned = _floor(tick,spacing);
        int256 gap=int256(uint256(residualGapSpacings(pool)))*spacing;
        if(residual0) {
            int256 near = aligned + spacing + gap;
            if(near >= mainUpper) revert InvalidState();
            lower = int24(near);
            upper = mainUpper;
            if(fraction != 10000) {
                uint256 boundary = _ratioScale(current,b,true,1e36);
                uint256 ratio = 1e36-Math.mulDiv(1e36-boundary,fraction,10000);
                uint256 root = Math.sqrt(ratio,Math.Rounding.Ceil);
                uint160 outer = uint160(Math.mulDiv(current,1e18,root));
                upper = _floor(TickMath.getTickAtSqrtPrice(outer),spacing);
            }
        } else {
            int256 near = aligned - gap;
            if(near <= mainLower) revert InvalidState();
            upper = int24(near);
            lower = mainLower;
            if(fraction != 10000) {
                uint256 boundary = _ratioScale(current,a,false,1e36);
                uint256 ratio = 1e36+Math.mulDiv(boundary-1e36,fraction,10000);
                uint256 root = Math.sqrt(ratio);
                uint160 outer = uint160(Math.mulDiv(current,1e18,root,Math.Rounding.Ceil));
                int256 inward = int256(_floor(TickMath.getTickAtSqrtPrice(outer),spacing))+spacing;
                if(inward > TickMath.MAX_TICK) revert InvalidState();
                lower = int24(inward);
            }
        }
        if(lower < mainLower || upper > mainUpper || lower >= upper) revert InvalidState();
    }
    function _floor(int24 tick,int24 spacing) private pure returns(int24) {
        int24 quotient = tick/spacing;
        if(tick < 0 && tick % spacing != 0) --quotient;
        return quotient*spacing;
    }
    /// @notice One exact range implementation shared by Strategy target and
    /// recorded-centre comparisons. This pure helper grants no trading rights.
    function range(PoolConfig memory c,uint160 referenceX96,uint8 orientation)
        external pure returns(int24 lower,int24 upper) {
        if(orientation > 1 || c.rangeBps >= 10000 || c.key.tickSpacing <= 0) revert InvalidConfiguration();
        uint256 below = Math.sqrt(uint256(10000-c.rangeBps)*1e28);
        uint256 above = Math.sqrt(uint256(10000+c.rangeBps)*1e28);
        uint256 lowerRoot = orientation == 1 ? Math.mulDiv(referenceX96,1e16,
            Math.sqrt(uint256(10000+c.rangeBps)*1e28,Math.Rounding.Ceil)) : Math.mulDiv(referenceX96,below,1e16);
        uint256 upperRoot = orientation == 1 ? Math.mulDiv(referenceX96,1e16,below,Math.Rounding.Ceil) :
            Math.mulDiv(referenceX96,above,1e16);
        if(lowerRoot <= TickMath.MIN_SQRT_PRICE || upperRoot >= TickMath.MAX_SQRT_PRICE) revert InvalidConfiguration();
        lower = _floor(TickMath.getTickAtSqrtPrice(uint160(lowerRoot)),c.key.tickSpacing);
        upper = _floor(TickMath.getTickAtSqrtPrice(uint160(upperRoot)),c.key.tickSpacing)+c.key.tickSpacing;
        if(lower < TickMath.MIN_TICK || upper > TickMath.MAX_TICK || lower >= upper) revert InvalidConfiguration();
    }
}

src/ZZZProtocolPolicy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {ZZZModule} from "./base/ZZZModule.sol";
import {Ids} from "./libraries/ZZZTypes.sol";
import {IZZZProtocolPolicy as P} from "./interfaces/IZZZProtocolPolicy.sol";

interface IPolicyNFT {
    function mintedCount() external view returns(uint256);
    function nextToFinalize() external view returns(uint256);
    function royaltyRewards() external view returns(address);
    function policyMetadataChanged() external;
}

/// @notice Fixed-controller, noncustodial future operating policy. Separately
/// deployed before consumers; no arbitrary execution, approval, asset transfer,
/// principal recipient, share writer or relaxation of fixed loss ceilings.
contract ZZZProtocolPolicy is ZZZModule,ReentrancyGuard {
    uint256 public constant PROTOCOL_POLICY_VERSION=1;
    uint16 public constant MAX_IDLE_BPS=4000;
    uint32 public constant MIN_CALL_GAS=100000;
    uint32 public constant MAX_CALL_GAS=1000000;
    P.EntryPolicy private entry;
    P.MaintenancePolicy private maintenance;
    P.GasPolicy private gasLimits;
    P.SalePolicy private sale;
    P.MetadataPolicy private metadata;
    P.VrfPolicy private randomness;
    uint64 public vrfRevision;
    uint64 public configurationRevision;
    bytes32 public configurationHash;
    event EntryPolicyConfigured(uint128 activationUSD,uint128 growthUSD,uint16 maxIdleBps,uint64 revision,bytes32 reviewHash);
    event MaintenancePolicyConfigured(uint16 maxIdleBps,uint64 revision,bytes32 reviewHash);
    event GasPolicyConfigured(uint32 payoutGas,uint32 sourceCallGas,uint32 royaltySyncGas,uint64 revision,bytes32 reviewHash);
    event MintPriceConfigured(uint128 previous,uint128 current,uint64 revision,bytes32 reviewHash);
    event MintRecipientProposed(address indexed current,address indexed pending,uint64 revision,bytes32 reviewHash);
    event MintRecipientAccepted(address indexed previous,address indexed current,uint64 revision);
    event EvolutionThresholdsConfigured(uint128 enhancedUSD,uint128 singularityUSD,uint64 revision,bytes32 reviewHash);
    event RandomnessConfigured(address indexed coordinator,uint64 generation,uint64 revision,bytes32 reviewHash);
    event RandomnessSettingsConfigured(uint16 confirmations,uint32 callbackGasLimit,uint64 revision,bytes32 reviewHash);

    constructor(address controller,address initialMintRecipient) ZZZModule(controller) {
        if(initialMintRecipient==address(0) || initialMintRecipient==controller || initialMintRecipient==address(this))
            revert InvalidConfiguration();
        entry=P.EntryPolicy(100e18,5e18,500,1);
        maintenance=P.MaintenancePolicy(500,1);
        gasLimits=P.GasPolicy(180000,500000,1000000,1);
        sale=P.SalePolicy(uint128(0.05 ether),initialMintRecipient,address(0),1);
        metadata=P.MetadataPolicy(1000e18,10000e18,1);
        configurationHash=keccak256(abi.encode("ZZZ_PROTOCOL_POLICY_V1",block.chainid,address(this),controller,
            entry,maintenance,gasLimits,sale,metadata));
    }
    function entryPolicy() external view returns(P.EntryPolicy memory){return entry;}
    function maintenancePolicy() external view returns(P.MaintenancePolicy memory){return maintenance;}
    function gasPolicy() external view returns(P.GasPolicy memory){return gasLimits;}
    /// @notice One-word consumer reads avoid decoding the full operational
    /// tuple in tight custody modules; the complete tuple remains reviewable.
    function payoutGas() external view returns(uint32){return gasLimits.payoutGas;}
    function sourceCallGas() external view returns(uint32){return gasLimits.sourceCallGas;}
    function royaltySyncGas() external view returns(uint32){return gasLimits.royaltySyncGas;}
    function salePolicy() external view returns(P.SalePolicy memory){return sale;}
    function metadataPolicy() external view returns(P.MetadataPolicy memory){return metadata;}
    function vrfPolicy() external view returns(P.VrfPolicy memory){return randomness;}
    function entryFingerprint() external view returns(bytes32){return keccak256(abi.encode(address(this),entry));}
    function maintenanceFingerprint() external view returns(bytes32){return keccak256(abi.encode(address(this),maintenance));}
    function gasFingerprint() external view returns(bytes32){return keccak256(abi.encode(address(this),gasLimits));}
    function saleFingerprint() external view returns(bytes32){return keccak256(abi.encode(address(this),sale));}
    /// @notice A reviewed mint binds both future proceeds and the exact draw
    /// provider/settings generation. Cosmetic/read/payout policies are separate.
    function mintFingerprint() external view returns(bytes32){return keccak256(abi.encode(address(this),sale,vrfRevision,randomness));}
    function metadataFingerprint() external view returns(bytes32){return keccak256(abi.encode(address(this),metadata));}
    function _record(bytes32 domain,bytes32 value) private {
        ++configurationRevision;
        configurationHash=keccak256(abi.encode(configurationHash,domain,configurationRevision,value));
    }
    function _review(bytes32 review) private pure {if(review==bytes32(0))revert InvalidConfiguration();}

    /// @notice Changes only future contribution policy. Individual incoming
    /// budgets and actual marginal deployed-LP loss floors remain independent.
    function setEntryPolicy(uint128 activationUSD,uint128 growthUSD,uint16 maxIdleBps,bytes32 reviewHash)
        external onlyGovernance operating nonReentrant {
        _review(reviewHash);
        if(activationUSD<1e18 || growthUSD<1e18 || growthUSD>activationUSD || maxIdleBps>MAX_IDLE_BPS)
            revert InvalidConfiguration();
        entry=P.EntryPolicy(activationUSD,growthUSD,maxIdleBps,entry.revision+1);
        _record("ENTRY",keccak256(abi.encode(entry,reviewHash)));
        emit EntryPolicyConfigured(activationUSD,growthUSD,maxIdleBps,entry.revision,reviewHash);
    }
    function setMaintenancePolicy(uint16 maxIdleBps,bytes32 reviewHash) external onlyGovernance operating nonReentrant {
        _review(reviewHash);if(maxIdleBps>MAX_IDLE_BPS)revert InvalidConfiguration();
        maintenance=P.MaintenancePolicy(maxIdleBps,maintenance.revision+1);
        _record("MAINTENANCE",keccak256(abi.encode(maintenance,reviewHash)));
        emit MaintenancePolicyConfigured(maxIdleBps,maintenance.revision,reviewHash);
    }
    /// @notice Explicit engineering limits, not qualification of full batches
    /// or future providers. These revisions never alter LP sample geometry.
    function setGasPolicy(uint32 payoutGas,uint32 sourceCallGas,uint32 royaltySyncGas,bytes32 reviewHash)
        external onlyGovernance operating nonReentrant {
        _review(reviewHash);
        if(payoutGas<MIN_CALL_GAS || payoutGas>MAX_CALL_GAS || sourceCallGas<MIN_CALL_GAS ||
            sourceCallGas>MAX_CALL_GAS || royaltySyncGas<MIN_CALL_GAS || royaltySyncGas>MAX_CALL_GAS)
            revert InvalidConfiguration();
        gasLimits=P.GasPolicy(payoutGas,sourceCallGas,royaltySyncGas,gasLimits.revision+1);
        _record("GAS",keccak256(abi.encode(gasLimits,reviewHash)));
        emit GasPolicyConfigured(payoutGas,sourceCallGas,royaltySyncGas,gasLimits.revision,reviewHash);
    }
    function setMintPrice(uint128 price,bytes32 reviewHash) external onlyGovernance operating nonReentrant {
        _review(reviewHash);if(price==0)revert InvalidConfiguration();uint128 previous=sale.mintPrice;
        sale.mintPrice=price;++sale.revision;_record("MINT_PRICE",keccak256(abi.encode(sale,reviewHash)));
        emit MintPriceConfigured(previous,price,sale.revision,reviewHash);
    }
    /// @notice Only future primary-sale proceeds change. Zero cancels the
    /// proposal; accepting the new address requires that address itself.
    function proposeMintRecipient(address candidate,bytes32 reviewHash) external onlyGovernance operating nonReentrant {
        _review(reviewHash);
        if(candidate!=address(0)){
            _validRecipient(candidate);if(candidate==sale.recipient)revert InvalidConfiguration();
        }
        sale.pendingRecipient=candidate;++sale.revision;
        _record("MINT_RECIPIENT_PROPOSE",keccak256(abi.encode(sale,reviewHash)));
        emit MintRecipientProposed(sale.recipient,candidate,sale.revision,reviewHash);
    }
    function acceptMintRecipient() external operating nonReentrant {
        if(msg.sender==address(0) || msg.sender!=sale.pendingRecipient || access.preparationActive() ||
            (access.isSealed() && access.canonicalState()!=0))revert Unauthorized();
        _validRecipient(msg.sender);address previous=sale.recipient;
        sale.recipient=msg.sender;sale.pendingRecipient=address(0);++sale.revision;
        _record("MINT_RECIPIENT_ACCEPT",keccak256(abi.encode(sale)));
        emit MintRecipientAccepted(previous,sale.recipient,sale.revision);
    }
    function validateMintRecipient() external view {_validRecipient(sale.recipient);}
    function _validRecipient(address candidate) private view {
        address collection=access.module(Ids.NFT);
        if(candidate==address(0) || candidate==address(this) || candidate==address(access) ||
            candidate==access.module(Ids.VAULT) || candidate==collection || candidate==access.module(Ids.FEES) ||
            candidate==access.module(Ids.REWARDS) || candidate==access.module(Ids.MIGRATION))revert InvalidConfiguration();
        if(collection!=address(0) && candidate==IPolicyNFT(collection).royaltyRewards())revert InvalidConfiguration();
    }
    /// @notice Cosmetic tiers only; never touches rarity or economic shares.
    function setEvolutionThresholds(uint128 enhancedUSD,uint128 singularityUSD,bytes32 reviewHash)
        external onlyGovernance operating nonReentrant {
        _review(reviewHash);
        if(enhancedUSD==0 || singularityUSD<=enhancedUSD)revert InvalidConfiguration();
        metadata=P.MetadataPolicy(enhancedUSD,singularityUSD,metadata.revision+1);
        _record("METADATA",keccak256(abi.encode(metadata,reviewHash)));
        address collection=access.module(Ids.NFT);
        if(collection!=address(0))IPolicyNFT(collection).policyMetadataChanged();
        emit EvolutionThresholdsConfigured(enhancedUSD,singularityUSD,metadata.revision,reviewHash);
    }
    function _vrf(address coordinator,bytes32 expectedCodeHash,bytes32 keyHash,uint256 subscriptionId,
        uint16 confirmations,uint32 callbackGas,bool nativePayment,bytes32 reviewHash,uint64 generation)
        private view returns(P.VrfPolicy memory result) {
        _review(reviewHash);
        if(coordinator.code.length==0 || expectedCodeHash==bytes32(0) || coordinator.codehash!=expectedCodeHash ||
            keyHash==bytes32(0) || subscriptionId==0 || confirmations<3 || confirmations>200 ||
            callbackGas<200000 || callbackGas>10000000)revert InvalidConfiguration();
        result=P.VrfPolicy(coordinator,expectedCodeHash,keyHash,subscriptionId,confirmations,callbackGas,nativePayment,
            generation,true,reviewHash);
    }
    function configureRandomness(address coordinator,bytes32 expectedCodeHash,bytes32 keyHash,uint256 subscriptionId,
        uint16 confirmations,uint32 callbackGas,bool nativePayment,bytes32 reviewHash)
        external onlyGovernance operating nonReentrant {
        if(access.isSealed() || randomness.configured || randomness.generation!=0)revert InvalidConfiguration();
        randomness=_vrf(coordinator,expectedCodeHash,keyHash,subscriptionId,confirmations,callbackGas,nativePayment,reviewHash,0);
        ++vrfRevision;_record("VRF",keccak256(abi.encode(randomness,vrfRevision)));
        emit RandomnessConfigured(coordinator,0,vrfRevision,reviewHash);
    }
    /// @notice Future mints only, after every old draw is finalized. There is
    /// no provider retargeting, reroll or administrator-selected pending result.
    function rotateRandomness(address coordinator,bytes32 expectedCodeHash,bytes32 keyHash,uint256 subscriptionId,
        uint16 confirmations,uint32 callbackGas,bool nativePayment,bytes32 reviewHash)
        external onlyGovernance operating nonReentrant {
        if(!access.isSealed() || access.lpExitStarted() || !randomness.configured)revert InvalidState();
        IPolicyNFT collection=IPolicyNFT(access.module(Ids.NFT));
        if(collection.nextToFinalize()!=collection.mintedCount()+1)revert InvalidState();
        randomness=_vrf(coordinator,expectedCodeHash,keyHash,subscriptionId,confirmations,callbackGas,nativePayment,reviewHash,
            randomness.generation+1);
        ++vrfRevision;_record("VRF",keccak256(abi.encode(randomness,vrfRevision)));
        emit RandomnessConfigured(coordinator,randomness.generation,vrfRevision,reviewHash);
    }
    function setRandomnessRequestSettings(uint16 confirmations,uint32 callbackGas,bytes32 reviewHash)
        external onlyGovernance operating nonReentrant {
        _review(reviewHash);if(!randomness.configured || confirmations<3 || confirmations>200 ||
            callbackGas<200000 || callbackGas>10000000)revert InvalidConfiguration();
        randomness.requestConfirmations=confirmations;randomness.callbackGasLimit=callbackGas;randomness.reviewHash=reviewHash;
        ++vrfRevision;_record("VRF_SETTINGS",keccak256(abi.encode(randomness,vrfRevision)));
        emit RandomnessSettingsConfigured(confirmations,callbackGas,vrfRevision,reviewHash);
    }
}

src/ZZZPythPriceFeed.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @notice Optional immutable AggregatorV3-shaped reader for a reviewed Pyth
/// Core feed. This does not publish updates, authenticate provider independence,
/// pin proxy implementations or qualify a production price service.
/// @dev Pyth publishTime is used as the synthetic round identity and as both
/// original observation timestamps. No freshness is manufactured by this reader.
contract ZZZPythPriceFeed {
    address public immutable core;
    bytes32 public immutable expectedCoreCodeHash;
    bytes32 public immutable feedId;
    bytes32 public immutable reviewHash;
    int32 public immutable expectedExponent;
    uint32 public immutable maxAge;
    uint16 public immutable maxConfidenceBps;
    uint8 public immutable decimals;
    uint256 public constant SOURCE_CALL_GAS = 300_000;
    uint16 public constant MAX_CONFIDENCE_BPS = 300;
    bytes4 private constant GET_PRICE_UNSAFE = bytes4(keccak256("getPriceUnsafe(bytes32)"));

    error InvalidConfiguration();
    error InvalidObservation();

    constructor(address source, bytes32 codeHash, bytes32 id, int32 exponent,
        uint32 age, uint16 confidenceBps, bytes32 review) {
        if (source.code.length == 0 || codeHash == bytes32(0) || source.codehash != codeHash ||
            id == bytes32(0) || review == bytes32(0) || exponent < -18 || exponent > 0 ||
            age == 0 || age > 1 days || confidenceBps > MAX_CONFIDENCE_BPS) {
            revert InvalidConfiguration();
        }
        core = source;
        expectedCoreCodeHash = codeHash;
        feedId = id;
        expectedExponent = exponent;
        maxAge = age;
        maxConfidenceBps = confidenceBps;
        decimals = uint8(uint32(-exponent));
        reviewHash = review;
    }

    function latestRoundData() external view returns
        (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound) {
        address source = core;
        if (source.codehash != expectedCoreCodeHash) revert InvalidObservation();
        bytes32 id = feedId;
        bytes4 selector = GET_PRICE_UNSAFE;
        bool success;
        uint256 returned;
        uint256 gasLimit = SOURCE_CALL_GAS;
        // Never allocate or copy an upstream's unbounded return/revert data.
        assembly ("memory-safe") {
            let input := mload(0x40)
            mstore(input, selector)
            mstore(add(input, 4), id)
            success := staticcall(gasLimit, source, input, 36, 0, 0)
            returned := returndatasize()
        }
        if (!success || returned != 128) revert InvalidObservation();
        bytes memory data = new bytes(128);
        assembly ("memory-safe") { returndatacopy(add(data, 32), 0, 128) }
        // Decode wide words first so malformed sign extension or high bits
        // produce a bounded domain error instead of being silently truncated.
        uint256 confidence;
        int256 exponent;
        (answer, confidence, exponent, updatedAt) = abi.decode(data, (int256, uint256, int256, uint256));
        if (answer <= 0 || answer > type(int64).max || confidence > type(uint64).max ||
            exponent != int256(expectedExponent) || updatedAt == 0 || updatedAt > type(uint80).max ||
            updatedAt > block.timestamp || block.timestamp - updatedAt > maxAge ||
            confidence * 10_000 > uint256(answer) * maxConfidenceBps) revert InvalidObservation();
        roundId = uint80(updatedAt);
        startedAt = updatedAt;
        answeredInRound = roundId;
    }
}

src/ZZZRebalanceConfirmation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {ZZZModule} from "./base/ZZZModule.sol";
import {ZZZPortfolioPolicy} from "./ZZZPortfolioPolicy.sol";
import {Ids, Position, PoolConfig} from "./libraries/ZZZTypes.sol";
import {IZZZVault, IZZZPools, IZZZLiquidity, IZZZOracle, IStateViewMinimal} from "./interfaces/IZZZ.sol";
import {IZZZEmergencyVault, IZZZEmergencyBudget} from "./interfaces/IZZZEmergency.sol";

interface IConfirmationStrategy {
    function rebalanceConfirmation() external view returns(address);
    function needsRebalance(uint256) external view returns(bool);
    function rebalanceCondition(uint256) external view returns(uint8,bool);
    function portfolioPolicy() external view returns(ZZZPortfolioPolicy);
    function rangeUpdatePending(uint256) external view returns(bool);
    function rangeOrientation(bytes32) external view returns(uint8);
    function executionQualityRevision() external view returns(uint64);
    function activeKeeperRangePolicies() external view returns(uint256);
}
interface IConfirmationRegistry { function configurationRevision() external view returns(uint64); }
interface IConfirmationOracle {
    function activePolicy(address) external view returns(bytes32);
    function activeSequencerPolicy() external view returns(bytes32);
}
interface IConfirmationLiquidity { function stateView() external view returns(IStateViewMinimal); }
interface IConfirmationPortfolio { function portfolioFingerprint(uint256) external view returns(bytes32); }

/// @notice Receipt-backed sampled confirmation, not proof of uninterrupted price.
/// Created by the fixed Strategy. No funds, approvals, execution or custody rights.
contract ZZZRebalanceConfirmation is ZZZModule, ReentrancyGuard {
    uint256 public constant REBALANCE_CONFIRMATION_VERSION = 3;
    uint32 public constant MAX_DURATION = 7 days;
    uint32 public duration = 10 minutes;
    /// @notice Zero is unconfigured/stopped; it never disables the safeguard.
    uint32 public maxObservationGap;
    uint64 public policyRevision;
    bytes32 public reviewHash;
    /// @notice Ordinary samples require physical AND independent reference to
    /// cross the same85%-of-price-distance threshold, including during cooldown.
    /// Governance may explicitly relax this rule; changing/restoring it always
    /// invalidates previous samples. This never disables execution loss guards.
    bool public requireReferenceExit = true;
    bytes32 public referenceReviewHash;
    struct Observation { bytes32 identity; uint64 firstSeen; uint64 lastSeen; uint8 side; }
    mapping(uint256 => Observation) public observations;
    event ConfirmationConfigured(uint32 duration,uint32 maxObservationGap,uint64 revision,bytes32 indexed reviewHash);
    event ConfirmationInvalidated(uint64 revision);
    event ReferenceExitConfigured(bool required,uint64 revision,bytes32 indexed reviewHash);
    event Observed(uint256 indexed bucket,uint8 side,bytes32 indexed identity,uint64 firstSeen,uint64 lastSeen);
    /// @dev 1=no ordinary trigger, 2=read fault, 3=unconfigured/stopped,
    /// 4=manual exception, 5=keeper invalidation after an observed incident.
    event ObservationReset(uint256 indexed bucket,uint8 reason);

    constructor(address controller) ZZZModule(controller) {}
    /// @notice Sole parent selected by the immutable sealed module registry;
    /// standalone creation avoids Strategy initcode embedding both children.
    function strategy() public view returns(address) { return access.module(Ids.STRATEGY); }

    /// @notice Review the actual cadence/receipt latency before setting a gap.
    /// Reconfiguration always invalidates prior samples, including change/restore.
    function configure(uint32 secondsRequired,uint32 maximumGap,bytes32 reviewed)
        external onlyGovernance operating principalOperating nonReentrant {
        if(secondsRequired < 60 || secondsRequired > MAX_DURATION || maximumGap > secondsRequired/2 ||
            reviewed == bytes32(0)) revert InvalidConfiguration();
        duration = secondsRequired; maxObservationGap = maximumGap; reviewHash = reviewed;
        ++policyRevision;
        emit ConfirmationConfigured(secondsRequired,maximumGap,policyRevision,reviewed);
    }
    function setRequireReferenceExit(bool required,bytes32 reviewed)
        external onlyGovernance operating principalOperating nonReentrant {
        if(reviewed == bytes32(0)) revert InvalidConfiguration();
        if(required && IConfirmationStrategy(strategy()).activeKeeperRangePolicies() != 0) revert InvalidConfiguration();
        requireReferenceExit = required;
        referenceReviewHash = reviewed;
        ++policyRevision;
        emit ReferenceExitConfigured(required,policyRevision,reviewed);
    }
    /// @dev Only the fixed Strategy can invalidate. Its governed orientation
    /// setting remains configurable after LP exit for post-exit buyback context;
    /// invalidation grants no principal readiness or execution capability.
    function invalidatePolicy() external operating {
        if(msg.sender != strategy()) revert Unauthorized();
        ++policyRevision;
        emit ConfirmationInvalidated(policyRevision);
    }
    /// @notice Side0=no ordinary candidate, 1=below, 2=above; manual is the
    /// existing deliberate range-change exception, still subject to raw guards.
    function condition(uint256 bucket) public view returns(uint8 side,bytes32 identity,bool manual) {
        return _condition(bucket,false);
    }
    function _condition(uint256 bucket,bool pausedEmergency) private view returns(uint8 side,bytes32 identity,bool manual) {
        if(strategy() == address(0) || !access.isSealed() || (access.paused() && !pausedEmergency) ||
            access.preparationActive() || access.canonicalState() != 0 || access.lpExitStarted()) return(0,bytes32(0),false);
        IConfirmationStrategy policy = IConfirmationStrategy(strategy());
        if(policy.rebalanceConfirmation() != address(this)) revert InvalidState();
        (side,manual) = policy.rebalanceCondition(bucket);
        if(manual) return(0,bytes32(0),true);
        if(side == 0) return(0,bytes32(0),false);
        Position memory p = IZZZVault(access.module(Ids.VAULT)).group(bucket);
        address registry = access.module(Ids.POOLS);
        PoolConfig memory c = IZZZPools(registry).accounting(p.poolId);
        address manager = access.module(Ids.LIQUIDITY);
        (int24 lower,int24 upper) = IZZZLiquidity(manager).ticks(p.lpTokenId);
        if(requireReferenceExit) {
            if(_referenceSide(policy.portfolioPolicy(),c,p.centerX96,lower,upper) != side)
                return(0,bytes32(0),false);
        }
        // Normal feed rounds and fresh token balances do not reset the window.
        // Policy IDs/revisions, physical LP identity and both boundaries do.
        bytes32 physical = keccak256(abi.encode(block.chainid,address(this),bucket,p.poolId,p.lpTokenId,
            p.lastRebalance,lower,upper,manager,IConfirmationPortfolio(manager).portfolioFingerprint(p.lpTokenId)));
        identity = keccak256(abi.encode(physical,keccak256(abi.encode(c)),
            policy.rangeOrientation(p.poolId),_controlFingerprint(c)));
    }
    /// @notice Pinned-reader explanation, not readiness or permission to trade.
    /// Side0=below trigger distance,1/2=threshold side in raw pool-key orientation.
    function marketSides(uint256 bucket) external view returns(uint8 physical,uint8 referenceSide) {
        Position memory p = IZZZVault(access.module(Ids.VAULT)).group(bucket);
        if(p.lpTokenId == 0) revert InvalidState();
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
        address manager = access.module(Ids.LIQUIDITY);
        (int24 lower,int24 upper) = IZZZLiquidity(manager).ticks(p.lpTokenId);
        if(lower < TickMath.MIN_TICK || upper > TickMath.MAX_TICK || lower >= upper) revert InvalidState();
        (uint160 price,,,) = IConfirmationLiquidity(manager).stateView().getSlot0(p.poolId);
        ZZZPortfolioPolicy portfolio = IConfirmationStrategy(strategy()).portfolioPolicy();
        physical = portfolio.thresholdSide(p.centerX96,lower,upper,price);
        referenceSide = _referenceSide(portfolio,c,p.centerX96,lower,upper);
    }
    function _referenceSide(ZZZPortfolioPolicy portfolio,PoolConfig memory c,uint160 center,int24 lower,int24 upper)
        private view returns(uint8) {
        uint160 price = IZZZOracle(access.module(Ids.ORACLE)).referenceX96(c.key.currency0,c.key.currency1);
        return portfolio.thresholdSide(center,lower,upper,price);
    }
    /// @notice Stable controls for the complete close/swap/deploy operation.
    /// Pool-specific policy is intentional. Budget must retain the original
    /// source pool when checking a move; Manager binds the destination context.
    /// Physical LP state and healthy round updates are deliberately excluded.
    function controlFingerprint(bytes32 poolId) external view returns(bytes32) {
        return _controlFingerprint(IZZZPools(access.module(Ids.POOLS)).accounting(poolId));
    }
    /// @notice Stable controls plus the raw record, not readiness of a new LP.
    /// Budget captures this across callbacks and deliberate LP replacement.
    function observationFingerprint(uint256 bucket,bytes32 poolId) external view returns(bytes32) {
        Observation memory o=observations[bucket];
        return keccak256(abi.encode(_controlFingerprint(IZZZPools(access.module(Ids.POOLS)).accounting(poolId)),
            o.identity,o.firstSeen,o.lastSeen,o.side));
    }
    function _controlFingerprint(PoolConfig memory c) private view returns(bytes32) {
        if(c.key.currency0 != address(0) || c.key.currency1 == address(0)) revert InvalidConfiguration();
        address registry = access.module(Ids.POOLS);
        IConfirmationOracle oracle = IConfirmationOracle(access.module(Ids.ORACLE));
        bytes32 first = oracle.activePolicy(c.key.currency0);
        bytes32 second = oracle.activePolicy(c.key.currency1);
        if(first == bytes32(0) || second == bytes32(0)) revert InvalidState();
        bytes32 sources = keccak256(abi.encode(address(oracle),first,second,oracle.activeSequencerPolicy()));
        return keccak256(abi.encode(registry,IConfirmationRegistry(registry).configurationRevision(),sources,
            IConfirmationStrategy(strategy()).executionQualityRevision(),policyRevision,
            IConfirmationStrategy(strategy()).portfolioPolicy().controlFingerprint(keccak256(abi.encode(c.key)))));
    }
    /// @notice A fresh read never writes/reset samples and fails closed on faults.
    function ready(uint256 bucket) external view returns(bool) {
        if(!IConfirmationStrategy(strategy()).needsRebalance(bucket)) return false;
        (uint8 side,bytes32 identity,bool manual) = condition(bucket);
        if(manual) return true;
        return _ready(observations[bucket],side,identity);
    }
    /// @notice Optional manual-emergency check of still-fresh existing evidence.
    /// Does not record observations while paused or authorize ordinary execution.
    /// The independent raw-trigger/cooldown option is enforced by the Budget.
    function emergencyReady(uint256 bucket) external view returns(bool) {
        address budget = IZZZEmergencyVault(access.module(Ids.VAULT)).migrationBudget();
        if(msg.sender != budget || !access.paused()) revert Unauthorized();
        IZZZEmergencyBudget(budget).validateEmergency(bucket);
        (uint8 side,bytes32 identity,bool manual) = _condition(bucket,true);
        return manual || _ready(observations[bucket],side,identity);
    }
    function _ready(Observation memory old,uint8 side,bytes32 identity) private view returns(bool) {
        return maxObservationGap != 0 && side != 0 && old.identity == identity && old.side == side &&
            old.firstSeen != 0 && old.firstSeen <= old.lastSeen && old.lastSeen <= block.timestamp &&
            block.timestamp-old.lastSeen <= maxObservationGap && block.timestamp-old.firstSeen >= duration;
    }
    /// @notice Clear only, including during ordinary pause. A worker which saw
    /// an off-chain fault must confirm this reset before extending old evidence.
    function resetObservation(uint256 bucket) external onlyKeeper operating principalOperating nonReentrant {
        delete observations[bucket];
        emit ObservationReset(bucket,5);
    }
    /// @notice A failed observed read clears evidence in a successful transaction;
    /// reverting after deletion would incorrectly restore the previous samples.
    function observe(uint256 bucket) external onlyKeeper live operating principalOperating nonReentrant returns(bool) {
        try this.condition(bucket) returns(uint8 side,bytes32 identity,bool manual) {
            if(manual || side == 0 || maxObservationGap == 0) {
                delete observations[bucket];
                emit ObservationReset(bucket,manual ? 4 : side == 0 ? 1 : 3);
                return _withCooldown(bucket,manual);
            }
            if(block.timestamp == 0 || block.timestamp > type(uint64).max) revert InvalidState();
            Observation memory old = observations[bucket];
            bool restart = old.identity != identity || old.side != side || old.lastSeen > block.timestamp ||
                old.firstSeen == 0 || block.timestamp-old.lastSeen > maxObservationGap;
            Observation memory next = Observation(identity,restart ? uint64(block.timestamp) : old.firstSeen,
                uint64(block.timestamp),side);
            observations[bucket] = next;
            emit Observed(bucket,side,identity,next.firstSeen,next.lastSeen);
            return _withCooldown(bucket,_ready(next,side,identity));
        } catch {
            delete observations[bucket];
            emit ObservationReset(bucket,2);
            return false;
        }
    }
    /// @dev A fresh eligibility fault must clear the just-recorded evidence in a
    /// successful transaction, never revert and restore the previous window.
    function _withCooldown(uint256 bucket,bool candidate) private returns(bool) {
        if(!candidate) return false;
        try IConfirmationStrategy(strategy()).needsRebalance(bucket) returns(bool due) { return due; }
        catch {
            delete observations[bucket];
            emit ObservationReset(bucket,2);
            return false;
        }
    }
}

src/ZZZRewards.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IZZZMembership, IZZZNFT, IZZZVault} from "./interfaces/IZZZ.sol";
import {Ids} from "./libraries/ZZZTypes.sol";
import {ExactToken} from "./libraries/ExactToken.sol";
import {ExactLPAllocation} from "./libraries/ExactLPAllocation.sol";
import {ZZZExactLPRewardsCanonical} from "./base/ZZZExactLPRewardsCanonical.sol";
import {IZZZCanonicalAccess} from "./interfaces/IZZZCanonical.sol";
import {ZZZLPRewardConverter} from "./ZZZLPRewardConverter.sol";
import {ZZZRewardsCanonical} from "./ZZZRewardsCanonical.sol";

/// @notice Funded whole-unit LP rights follow the NFT's current owner.
/// @dev Accounting7 only. Individual trees use shared bucket shares; one global
/// tree uses equal activated membership. Royalties and principal are separate.
contract ZZZRewards is ZZZExactLPRewardsCanonical {
    using SafeERC20 for IERC20;
    using ExactLPAllocation for ExactLPAllocation.Tree;

    address public converter;
    address public immutable canonicalModule;
    event PoolRewardsCredited(uint256 indexed bucketId, address indexed token, uint256 individual, uint256 collective);
    event Claimed(uint256 indexed nftId, address indexed token, address indexed recipient, uint256 amount);
    event ConverterBound(address indexed converter);
    event LPRewardsConverted(uint256 indexed nftId, address indexed source,
        uint256 sourceIndividual, uint256 sourceCollective, uint256 nativeIndividual, uint256 nativeCollective);
    event ShareWeightSynchronized(uint256 indexed nftId, uint256 indexed bucketId,
        uint256 ordinal, uint256 previousWeight, uint256 weight, uint256 totalWeight);
    event CollectiveWeightSynchronized(uint256 indexed nftId,
        uint256 ordinal, uint256 previousWeight, uint256 weight, uint256 totalWeight);

    constructor(address controller) ZZZExactLPRewardsCanonical(controller) {
        canonicalModule = address(new ZZZRewardsCanonical(controller));
    }
    function _canonicalModule() internal view override returns (address) { return canonicalModule; }
    receive() external payable {}

    function bindConverter(address candidate) external onlyGovernance nonReentrant economic {
        if (access.isSealed() || converter != address(0) || candidate.code.length == 0 ||
            ZZZLPRewardConverter(payable(candidate)).ledger() != address(this) ||
            address(ZZZLPRewardConverter(payable(candidate)).access()) != address(access)) revert InvalidConfiguration();
        converter = candidate;
        emit ConverterBound(candidate);
    }

    /// @notice Bind only the deployment's fixed ZZZ, before sealing.
    function addAsset(address token) external onlyGovernance economic {
        if (access.isSealed() || assets.length != 1 || isAsset[token]) revert InvalidConfiguration();
        _validateZZZ(token);
        assets.push(token);
        isAsset[token] = true;
        emit AssetAdded(token);
    }
    function assetCount() external view returns (uint256) { return assets.length; }

    /// @notice Install authenticated new shares after the Vault's atomic write.
    /// @dev Stored old weights settle both old books first. No mutable dependency
    /// callback exists between the Vault write and this typed synchronization.
    function syncShares(uint256 id) external onlyModule(Ids.VAULT) nonReentrant economic {
        IZZZVault vault = IZZZVault(msg.sender);
        uint256 bucket = vault.nftBucket(id);
        uint256 weight = vault.sharesOf(id);
        uint256 ordinal = _ordinal(id);
        if (bucket == 0 || weight == 0 || (rewardBucket[id] != 0 && rewardBucket[id] != bucket)) revert InvalidState();
        ExactLPAllocation.Tree storage tree = ownerBooks[bucket];
        uint256 previous = tree.weightOf(ordinal);
        if (weight < previous) revert InvalidState();
        rewardBucket[id] = bucket;
        uint256 total = tree.setWeight(ordinal, weight);
        if (total != vault.bucketTotalShares(bucket)) revert InvalidState();
        emit ShareWeightSynchronized(id, bucket, ordinal, previous, weight, total);
    }

    /// @notice Add exactly one collective share after activation is recorded.
    function syncMembership(uint256 id) external onlyModule(Ids.MEMBERSHIP) nonReentrant economic {
        IZZZMembership membership = IZZZMembership(msg.sender);
        uint256 ordinal = _ordinal(id);
        uint256 previous = collectiveBook.weightOf(ordinal);
        if (!membership.eligible(id) || rewardBucket[id] == 0 || previous != 0) revert InvalidState();
        uint256 total = collectiveBook.setWeight(ordinal, 1);
        if (total != membership.totalEligible()) revert InvalidState();
        emit CollectiveWeightSynchronized(id, ordinal, previous, 1, total);
    }

    function creditPool(uint256 bucketId, address token, uint256 personal, uint256 shared)
        external payable onlyModule(Ids.FEES) nonReentrant economic {
        _creditPool(bucketId, token, personal, shared, false);
    }
    function creditCanonicalCutoff(uint256 bucketId, address token, uint256 personal, uint256 shared)
        external payable nonReentrant {
        if (msg.sender != access.module(Ids.FEES) || _state() != 1 ||
            !IZZZCanonicalAccess(address(access)).canonicalSettling()) revert CanonicalState();
        _creditPool(bucketId, token, personal, shared, true);
        if (_state() != 1 || !IZZZCanonicalAccess(address(access)).canonicalSettling()) revert CanonicalState();
    }

    function _creditPool(uint256 bucket, address token, uint256 personal, uint256 shared, bool cutoff) private {
        ExactLPAllocation.Asset book = _asset(token);
        uint256 amount = personal + shared;
        uint256 supply = IZZZVault(access.module(Ids.VAULT)).bucketTotalShares(bucket);
        uint256 eligible = IZZZMembership(access.module(Ids.MEMBERSHIP)).totalEligible();
        if (amount == 0) revert InvalidAmount();
        if (supply == 0 || ownerBooks[bucket].totalWeight() != supply ||
            collectiveBook.totalWeight() != eligible) revert InvalidState();
        if (msg.value != (token == address(0) ? amount : 0)) revert InvalidAmount();
        if (token != address(0)) ExactToken.pull(token, msg.sender, amount);
        if (cutoff) ZZZRewardsCanonical(payable(canonicalModule)).creditCutoff(token, amount);
        ownerBooks[bucket].credit(book, personal);
        liabilities[token] += personal;
        if (eligible == 0) orphaned[token] += shared;
        else {
            collectiveBook.credit(book, shared);
            liabilities[token] += shared;
        }
        _solvent(token);
        emit PoolRewardsCredited(bucket, token, personal, shared);
    }

    /// @notice Whole individual and collective rights, including direct credits.
    function claimableComponents(uint256 id, address token) public view returns (uint256 personal, uint256 shared) {
        if (_reentrancyGuardEntered()) revert InvalidState();
        ExactLPAllocation.Asset book = _asset(token);
        uint256 ordinal = _ordinal(id);
        uint256 bucket = rewardBucket[id];
        personal = directIndividual[id][token];
        if (bucket != 0) personal += ownerBooks[bucket].claimable(book, ordinal);
        shared = directCollective[id][token] + collectiveBook.claimable(book, ordinal);
    }
    function claimable(uint256 id, address token) external view returns (uint256) {
        (uint256 personal, uint256 shared) = claimableComponents(id, token);
        return personal + shared;
    }
    /// @notice Bucket zero selects the global equal-membership tree.
    function allocationTree(uint256 bucket) external view returns (uint256 weight, uint256 ethOutstanding, uint256 zzzOutstanding) {
        if (_reentrancyGuardEntered()) revert InvalidState();
        ExactLPAllocation.Tree storage tree = bucket == 0 ? collectiveBook : ownerBooks[bucket];
        return (tree.totalWeight(), tree.outstanding(ExactLPAllocation.Asset.ETH), tree.outstanding(ExactLPAllocation.Asset.ZZZ));
    }

    function _takeComponents(uint256 id, address token) private returns (uint256 personal, uint256 shared) {
        ExactLPAllocation.Asset book = _asset(token);
        uint256 ordinal = _ordinal(id);
        personal = directIndividual[id][token];
        shared = directCollective[id][token];
        if (personal != 0) delete directIndividual[id][token];
        if (shared != 0) delete directCollective[id][token];
        directLiabilities[token] -= personal + shared;
        uint256 bucket = rewardBucket[id];
        if (bucket != 0) personal += ownerBooks[bucket].take(book, ordinal);
        shared += collectiveBook.take(book, ordinal);
    }
    function _solvent(address token) private view {
        if (_canonicalBalance(token) < liabilities[token] + orphaned[token]) revert InvalidState();
    }

    function claim(uint256 id, address token) external nonReentrant economic returns (uint256) {
        return _claim(id, token, msg.sender);
    }
    /// @notice Only the NFT's fixed router may claim for its current owner.
    function claimFor(uint256 id, address token, address owner) external nonReentrant economic returns (uint256) {
        if (msg.sender != IZZZNFT(access.module(Ids.NFT)).claimRouter()) revert Unauthorized();
        return _claim(id, token, owner);
    }
    function _claim(uint256 id, address token, address owner) private returns (uint256 amount) {
        if (!access.isSealed() || IZZZNFT(access.module(Ids.NFT)).ownerOf(id) != owner) revert Unauthorized();
        (uint256 personal, uint256 shared) = _takeComponents(id, token);
        amount = personal + shared;
        liabilities[token] -= amount;
        if (token == address(0)) {
            if (amount != 0) { (bool ok,) = owner.call{value: amount}(""); if (!ok) revert InvalidState(); }
        } else ExactToken.push(token, owner, amount);
        _solvent(token);
        emit Claimed(id, token, owner, amount);
    }

    /// @notice Convert already allocated ZZZ rights into same-NFT ETH credits.
    function convertBatch(address token, uint256[] calldata ids, bytes32 routeId, uint256 minimumETH, uint256 deadline)
        external onlyKeeper live operating nonReentrant economic returns (uint256 output) {
        if (access.module(Ids.REWARDS) != address(this) || converter == address(0) || token == address(0) ||
            !isAsset[token] || ids.length == 0 || ids.length > MAX_CONVERSION_NFTS) revert InvalidConfiguration();
        uint256[] memory personal = new uint256[](ids.length);
        uint256[] memory shared = new uint256[](ids.length);
        uint256 total;
        for (uint256 i; i < ids.length; ++i) {
            if ((i != 0 && ids[i] <= ids[i-1]) || IZZZNFT(access.module(Ids.NFT)).ownerOf(ids[i]) == address(0))
                revert InvalidConfiguration();
            (personal[i], shared[i]) = _takeComponents(ids[i], token);
            total += personal[i] + shared[i];
        }
        if (total == 0) revert InvalidAmount();
        uint256 sourceBefore = IERC20(token).balanceOf(address(this));
        uint256 nativeBefore = address(this).balance;
        liabilities[token] -= total;
        IERC20(token).forceApprove(converter, total);
        output = ZZZLPRewardConverter(payable(converter)).convert(token,total,routeId,minimumETH,deadline);
        IERC20(token).forceApprove(converter, 0);
        if (IERC20(token).balanceOf(address(this)) != sourceBefore - total ||
            address(this).balance != nativeBefore + output) revert InvalidState();
        liabilities[address(0)] += output;
        directLiabilities[address(0)] += output;
        uint256 cumulative;
        uint256 assigned;
        for (uint256 i; i < ids.length; ++i) {
            cumulative += personal[i];
            uint256 next = Math.mulDiv(output,cumulative,total);
            uint256 ownETH = next - assigned;
            assigned = next;
            cumulative += shared[i];
            next = Math.mulDiv(output,cumulative,total);
            uint256 sharedETH = next - assigned;
            assigned = next;
            directIndividual[ids[i]][address(0)] += ownETH;
            directCollective[ids[i]][address(0)] += sharedETH;
            emit LPRewardsConverted(ids[i],token,personal[i],shared[i],ownETH,sharedETH);
        }
        _solvent(token);
        _solvent(address(0));
        if (!access.keeperAuthorized(msg.sender) || access.paused()) revert Unauthorized();
    }
}

