// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {SqrtPriceMath} from "@uniswap/v4-core/src/libraries/SqrtPriceMath.sol";
import {ZZZModule} from "./base/ZZZModule.sol";
import {ZZZPriceMath} from "./libraries/ZZZPriceMath.sol";
import {ZZZRebalanceConfirmation} from "./ZZZRebalanceConfirmation.sol";
import {ZZZPortfolioPolicy} from "./ZZZPortfolioPolicy.sol";
import {Ids, PoolConfig, Position, PositionStatus} from "./libraries/ZZZTypes.sol";
import {IZZZPools, IZZZOracle, IZZZLiquidity, IZZZVault, IStateViewMinimal} from "./interfaces/IZZZ.sol";

interface IV4FeeState { function stateView() external view returns (IStateViewMinimal); }
interface IRangeRegistry { function applyKeeperRange(bytes32 poolId,uint16 rangeBps) external; }

/// @notice Bounded strategy policy. Only the vault commits physical LP changes.
contract ZZZStrategy is ZZZModule {
    uint256 public constant RANGE_POLICY_VERSION = 1;
    /// @notice Price-space edge threshold, with governed geometry exceptions.
    uint256 public constant MAINTENANCE_POLICY_VERSION = 3;
    uint256 public constant REBALANCE_CONFIRMATION_VERSION = 3;
    uint256 public constant PORTFOLIO_VERSION = 2;
    ZZZRebalanceConfirmation public immutable rebalanceConfirmation;
    ZZZPortfolioPolicy public immutable portfolioPolicy;
    uint256 public constant EXECUTION_QUALITY_VERSION = 1;
    uint256 public constant MAX_ADDITIONAL_LOSS_BPS = 1000;
    uint16 public additionalLossBps = 100;
    uint64 public executionQualityRevision;
    /// 0 preserves historical token1/token0; 1 expresses token0/token1.
    mapping(bytes32 => uint8) public rangeOrientation;
    struct KeeperRangePolicy {
        bool enabled;
        uint16 narrowTriggerBps;
        uint16 widenTriggerBps;
        uint32 minInterval;
        uint64 lastChange;
        bytes32 configurationHash;
        bytes32 reviewHash;
    }
    mapping(bytes32 => KeeperRangePolicy) public keeperRangePolicy;
    uint256 public activeKeeperRangePolicies;
    event RangeOrientationChanged(bytes32 indexed poolId,uint8 previous,uint8 current);
    event KeeperRangePolicyChanged(bytes32 indexed poolId,bool enabled,bytes32 configurationHash,bytes32 reviewHash);
    event KeeperRangeSelected(bytes32 indexed poolId,uint16 previous,uint16 current,bytes32 reviewHash);
    event AdditionalLossLimitChanged(uint16 previous,uint16 current,uint64 revision,bytes32 indexed reviewHash);
    struct AssetPrice { uint256 lower; uint256 upper; uint256 scale; }
    struct PairPrices { AssetPrice first; AssetPrice second; uint160 referenceX96; }
    constructor(address controller,address portfolio,address confirmation) ZZZModule(controller) {
        if(portfolio.code.length == 0 || confirmation.code.length == 0 ||
            address(ZZZPortfolioPolicy(portfolio).access()) != controller ||
            ZZZPortfolioPolicy(portfolio).PORTFOLIO_VERSION() != 2 ||
            address(ZZZRebalanceConfirmation(confirmation).access()) != controller ||
            ZZZRebalanceConfirmation(confirmation).REBALANCE_CONFIRMATION_VERSION() != 3) revert InvalidConfiguration();
        portfolioPolicy = ZZZPortfolioPolicy(portfolio);
        rebalanceConfirmation = ZZZRebalanceConfirmation(confirmation);
    }
    /// @notice Separate from raw needsRebalance so pending upkeep blocks compound.
    function rebalanceReady(uint256 id) external view returns(bool) { return rebalanceConfirmation.ready(id); }
    function rebalanceObservation(uint256 id) external view returns(uint8 side,bytes32 identity,bool manual) {
        return rebalanceConfirmation.condition(id);
    }
    /// @notice Extra oracle-relative loss after actual directional trading fees;
    /// gross/caller/operation floors remain independent. Available for post-exit
    /// buybacks and ordinary pause, but not preparation/canonical lifecycle locks.
    function setAdditionalLossBps(uint16 limit,bytes32 reviewHash) external onlyGovernance operating {
        if (limit > MAX_ADDITIONAL_LOSS_BPS || reviewHash == bytes32(0)) revert InvalidConfiguration();
        uint16 previous = additionalLossBps;
        additionalLossBps = limit;
        ++executionQualityRevision;
        emit AdditionalLossLimitChanged(previous,limit,executionQualityRevision,reviewHash);
    }
    /// @notice Inclusion-time minimum, not a keeper-selected price or swap quote.
    /// Known fees are removed from raw input; rounding/impact/reference spread
    /// still consumes the additional limit. Never exempts fees from gross caps.
    function minimumOutput(bytes32 poolId,bool direction,uint256 amount) external view returns(uint256) {
        return _minimumOutput(poolId,direction,amount,true);
    }
    /// @notice Same financial floor without operations-enabled admission, for a
    /// separately authorized paused emergency which deliberately bypasses it.
    function minimumOutputForExit(bytes32 poolId,bool direction,uint256 amount) external view returns(uint256) {
        return _minimumOutput(poolId,direction,amount,false);
    }
    function _minimumOutput(bytes32 poolId,bool direction,uint256 amount,bool requireOperations) private view returns(uint256) {
        if (amount == 0 || amount > type(uint128).max) revert InvalidAmount();
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
        if (requireOperations && !c.operationsEnabled) revert InvalidState();
        PairPrices memory prices = _pairPrices(c);
        return _minimum(prices,direction,amount,c.maxSlippageBps,_swapFee(poolId,c,direction));
    }
    function _swapFee(bytes32 poolId,PoolConfig memory c,bool direction) private view returns(uint256) {
        (,,uint24 protocol,uint24 fee) = IV4FeeState(access.module(Ids.LIQUIDITY)).stateView().getSlot0(poolId);
        if (c.key.hooks != address(0) || fee != c.key.fee || fee > 100000 ||
            (protocol & 0xfff) > 1000 || protocol >> 12 > 1000) revert InvalidConfiguration();
        uint256 selected = direction ? protocol & 0xfff : protocol >> 12;
        return selected+fee-Math.mulDiv(selected,fee,1_000_000);
    }
    function _quoted(PairPrices memory prices,bool direction,uint256 amount) private pure returns(uint256) {
        AssetPrice memory input = direction ? prices.first : prices.second;
        AssetPrice memory output = direction ? prices.second : prices.first;
        return Math.mulDiv(Math.mulDiv(amount,input.upper,input.scale),output.scale,output.lower);
    }
    function _minimum(PairPrices memory prices,bool direction,uint256 amount,uint16 grossLoss,uint256 fee)
        private view returns(uint256) {
        uint256 gross = Math.mulDiv(_quoted(prices,direction,amount),10000-grossLoss,10000);
        uint256 net = Math.mulDiv(amount,1_000_000-fee,1_000_000);
        return Math.max(gross,Math.mulDiv(_quoted(prices,direction,net),10000-additionalLossBps,10000,Math.Rounding.Ceil));
    }
    function target(bytes32 poolId) public view returns (int24 lower, int24 upper, uint160 referenceX96) {
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
        if (!c.operationsEnabled) revert InvalidState();
        referenceX96 = IZZZOracle(access.module(Ids.ORACLE)).referenceX96(c.key.currency0, c.key.currency1);
        (lower, upper) = _range(c, referenceX96);
    }
    function _range(PoolConfig memory c, uint160 referenceX96) private view returns (int24 lower, int24 upper) {
        return portfolioPolicy.range(c,referenceX96,rangeOrientation[keccak256(abi.encode(c.key))]);
    }
    /// @notice Explicit opt-in; existing physical ticks are not reinterpreted.
    function setRangeOrientation(bytes32 poolId,uint8 orientation) external onlyGovernance operating {
        uint8 previous = rangeOrientation[poolId];
        if (orientation > 1 || previous == orientation) revert InvalidConfiguration();
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
        rangeOrientation[poolId] = orientation;
        _range(c,IZZZOracle(access.module(Ids.ORACLE)).referenceX96(c.key.currency0,c.key.currency1));
        KeeperRangePolicy storage policy = keeperRangePolicy[poolId];
        if (policy.enabled) {
            policy.enabled = false;
            --activeKeeperRangePolicies;
            emit KeeperRangePolicyChanged(poolId,false,policy.configurationHash,policy.reviewHash);
        }
        rebalanceConfirmation.invalidatePolicy();
        emit RangeOrientationChanged(poolId,previous,orientation);
    }
    /// @notice Review actual price-displacement rules, not an inferred volatility model.
    /// Disabling never needs healthy Oracle/venue data. Existing audit fields persist.
    function setKeeperRangePolicy(bytes32 poolId,bool enabled,uint16 narrowTriggerBps,uint16 widenTriggerBps,
        uint32 minInterval,bytes32 reviewHash) external onlyGovernance operating {
        if (poolId == bytes32(0)) revert InvalidConfiguration();
        KeeperRangePolicy storage policy = keeperRangePolicy[poolId];
        if (!enabled) {
            if(policy.enabled) --activeKeeperRangePolicies;
            policy.enabled = false;
            emit KeeperRangePolicyChanged(poolId,false,policy.configurationHash,policy.reviewHash);
            return;
        }
        // A keeper-selected width would otherwise use the deliberate-width
        // exception. It cannot silently bypass same-side reference protection.
        if(rebalanceConfirmation.requireReferenceExit()) revert InvalidConfiguration();
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
        if (rangeOrientation[poolId] != 1 || (c.rangeBps != 2500 && c.rangeBps != 5000) ||
            c.triggerBps >= 2500 || c.maxSpotDeviationBps >= 2500 || narrowTriggerBps >= widenTriggerBps ||
            widenTriggerBps >= 2500 || minInterval < 600 || minInterval < c.minRebalanceInterval ||
            minInterval > 7 days || reviewHash == bytes32(0)) revert InvalidConfiguration();
        _range(c,IZZZOracle(access.module(Ids.ORACLE)).referenceX96(c.key.currency0,c.key.currency1));
        bytes32 fingerprint = _rangeConfiguration(c);
        if(!policy.enabled) ++activeKeeperRangePolicies;
        keeperRangePolicy[poolId] = KeeperRangePolicy(true,narrowTriggerBps,widenTriggerBps,minInterval,
            uint64(block.timestamp),fingerprint,reviewHash);
        emit KeeperRangePolicyChanged(poolId,true,fingerprint,reviewHash);
    }
    function _rangeConfiguration(PoolConfig memory c) private view returns(bytes32 fingerprint) {
        uint16 width = c.rangeBps;
        c.rangeBps = 0;
        fingerprint = keccak256(abi.encode(c,rangeOrientation[keccak256(abi.encode(c.key))]));
        c.rangeBps = width;
    }
    function _displacement(bytes32 poolId,uint160 center,uint160 referenceX96) private view returns(uint256) {
        uint256 root = rangeOrientation[poolId] == 1 ? Math.mulDiv(center,1e18,referenceX96) :
            Math.mulDiv(referenceX96,1e18,center);
        uint256 ratio = Math.mulDiv(root,root,1e18);
        return ratio > 1e18 ? ratio-1e18 : 1e18-ratio;
    }
    function keeperRangeTarget(bytes32 poolId) public view returns(uint16 next) {
        KeeperRangePolicy memory policy = keeperRangePolicy[poolId];
        if (!policy.enabled || !access.isSealed() || access.paused() || access.preparationActive() ||
            access.canonicalState() != 0 || rangeOrientation[poolId] != 1 ||
            block.timestamp < uint256(policy.lastChange)+policy.minInterval) return 0;
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
        if (!c.operationsEnabled || _rangeConfiguration(c) != policy.configurationHash ||
            (c.rangeBps != 2500 && c.rangeBps != 5000)) return 0;
        IZZZVault vault = IZZZVault(access.module(Ids.VAULT));
        uint256 bucket = vault.poolBucket(poolId);
        if (bucket == 0) return 0;
        Position memory p = vault.group(bucket);
        if (p.poolId != poolId || p.status != PositionStatus.Active || p.lpTokenId == 0 || p.centerX96 == 0 ||
            block.timestamp < uint256(p.lastRebalance)+c.minRebalanceInterval || _rangeUpdatePending(p,c)) return 0;
        uint160 ref = IZZZOracle(access.module(Ids.ORACLE)).referenceX96(c.key.currency0,c.key.currency1);
        uint256 movement = _displacement(poolId,p.centerX96,ref);
        if (c.rangeBps == 2500 && movement >= uint256(policy.widenTriggerBps)*1e14) next = 5000;
        else if (c.rangeBps == 5000 && movement <= uint256(policy.narrowTriggerBps)*1e14) next = 2500;
        if (next != 0) { c.rangeBps = next; _range(c,ref); }
    }
    /// @notice Keeper supplies a pool only; the reviewed on-chain rule chooses width.
    function applyKeeperRange(bytes32 poolId) external onlyKeeper live operating principalOperating returns(uint16 next) {
        next = keeperRangeTarget(poolId);
        if (next == 0) revert InvalidState();
        uint16 previous = IZZZPools(access.module(Ids.POOLS)).get(poolId).rangeBps;
        keeperRangePolicy[poolId].lastChange = uint64(block.timestamp);
        IRangeRegistry(access.module(Ids.POOLS)).applyKeeperRange(poolId,next);
        emit KeeperRangeSelected(poolId,previous,next,keeperRangePolicy[poolId].reviewHash);
    }
    function validatePrice(bytes32 poolId) public view returns (uint160 spotX96) {
        return _validatePrice(poolId, true);
    }
    /// @notice A disabled source pool can still exit through governed custody paths.
    /// Oracle freshness and spot-deviation checks remain mandatory.
    function validateExitPrice(bytes32 poolId) public view returns (uint160 spotX96) {
        return _validatePrice(poolId, false);
    }
    function _validatePrice(bytes32 poolId, bool requireOperations) private view returns (uint160 spotX96) {
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
        if (requireOperations && !c.operationsEnabled) revert InvalidState();
        uint160 referenceX96 = IZZZOracle(access.module(Ids.ORACLE)).referenceX96(c.key.currency0, c.key.currency1);
        return _checkedSpot(poolId, c, referenceX96);
    }
    function _checkedSpot(bytes32 poolId, PoolConfig memory c, uint160 referenceX96) private view returns (uint160 spotX96) {
        spotX96 = IZZZLiquidity(access.module(Ids.LIQUIDITY)).spot(poolId);
        if (spotX96 == 0) revert InvalidState();
        uint256 relativeRoot = Math.mulDiv(spotX96, 1e18, referenceX96);
        uint256 relativePrice = Math.mulDiv(relativeRoot, relativeRoot, 1e18);
        uint256 difference = relativePrice > 1e18 ? relativePrice - 1e18 : 1e18 - relativePrice;
        if (difference > uint256(c.maxSpotDeviationBps) * 1e14) revert Slippage();
    }
    function needsRebalance(uint256 id) external view returns (bool) {
        Position memory p = IZZZVault(access.module(Ids.VAULT)).group(id);
        if (p.status != PositionStatus.Active || p.centerX96 == 0 || p.lpTokenId == 0) return false;
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
        if (!c.operationsEnabled || block.timestamp < p.lastRebalance + c.minRebalanceInterval) return false;
        (uint8 side,bool manual) = _rebalanceCondition(id,p,c);
        return side != 0 || manual;
    }
    /// @notice Sample during cooldown; this is not permission to execute.
    /// needsRebalance and Confirmation.ready independently enforce the clock.
    function rebalanceCondition(uint256 id) external view returns(uint8 side,bool manual) {
        Position memory p = IZZZVault(access.module(Ids.VAULT)).group(id);
        if(p.status != PositionStatus.Active || p.centerX96 == 0 || p.lpTokenId == 0) return(0,false);
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
        if(!c.operationsEnabled) return(0,false);
        return _rebalanceCondition(id,p,c);
    }
    function _rebalanceCondition(uint256 id,Position memory p,PoolConfig memory c) private view returns(uint8 side,bool manual) {
        uint160 ref = IZZZOracle(access.module(Ids.ORACLE)).referenceX96(c.key.currency0,c.key.currency1);
        uint160 spotX96 = _checkedSpot(p.poolId,c,ref);
        (int24 lower,int24 upper) = IZZZLiquidity(access.module(Ids.LIQUIDITY)).ticks(p.lpTokenId);
        if (lower < TickMath.MIN_TICK || upper > TickMath.MAX_TICK || lower >= upper) revert InvalidState();
        _checkedPoolTick(p.poolId,c);
        manual = _rangeUpdatePending(p,c) || portfolioPolicy.configurationPending(id);
        if(manual) return(0,true);
        side = portfolioPolicy.thresholdSide(p.centerX96,lower,upper,spotX96);
    }
    /// @dev Preserve v4's exact downward-crossing tick, which may be one below
    /// getTickAtSqrtPrice. Using a recomputed tick would misclassify that edge.
    function _checkedPoolTick(bytes32 poolId,PoolConfig memory c) private view returns(int24 tick) {
        uint160 price; uint24 protocol; uint24 fee;
        (price,tick,protocol,fee) = IV4FeeState(access.module(Ids.LIQUIDITY)).stateView().getSlot0(poolId);
        if (price < TickMath.MIN_SQRT_PRICE || price >= TickMath.MAX_SQRT_PRICE ||
            tick < TickMath.MIN_TICK || tick >= TickMath.MAX_TICK || fee != c.key.fee ||
            (protocol & 0xfff) > 1000 || protocol >> 12 > 1000) revert InvalidState();
        if (price < TickMath.getSqrtPriceAtTick(tick) || price > TickMath.getSqrtPriceAtTick(tick+1)) revert InvalidState();
    }
    /// @notice A governed width/orientation change can require replacement at a flat price.
    /// Pending is not execution eligibility: cooldown, operations and all Vault
    /// guards still apply. Comparing at the recorded center avoids price-drift churn.
    function rangeUpdatePending(uint256 id) external view returns (bool) {
        Position memory p = IZZZVault(access.module(Ids.VAULT)).group(id);
        if (p.status != PositionStatus.Active || p.centerX96 == 0 || p.lpTokenId == 0) return false;
        return _rangeUpdatePending(p, IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId)) ||
            portfolioPolicy.configurationPending(id);
    }
    function _rangeUpdatePending(Position memory p, PoolConfig memory c) private view returns (bool) {
        (int24 expectedLower, int24 expectedUpper) = _range(c, p.centerX96);
        (int24 lower, int24 upper) = IZZZLiquidity(access.module(Ids.LIQUIDITY)).ticks(p.lpTokenId);
        if (lower >= upper) revert InvalidState();
        return lower != expectedLower || upper != expectedUpper;
    }
    function swapPlan(bytes32 poolId, uint256 amount0, uint256 amount1)
        external view returns (bool zeroForOne, uint256 amountIn, uint256 minimumOut) {
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
        if (!c.operationsEnabled) revert InvalidState();
        PairPrices memory prices = _pairPrices(c);
        (int24 lower, int24 upper) = _range(c, prices.referenceX96);
        return _plan(poolId, c, prices, lower, upper, amount0, amount1);
    }
    function compoundPlan(uint256 id, uint256 amount0, uint256 amount1)
        external view returns (bool, uint256, uint256) {
        Position memory p = IZZZVault(access.module(Ids.VAULT)).group(id);
        (int24 lower, int24 upper) = IZZZLiquidity(access.module(Ids.LIQUIDITY)).ticks(p.lpTokenId);
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
        if (!c.operationsEnabled) revert InvalidState();
        return _plan(p.poolId, c, _pairPrices(c), lower, upper, amount0, amount1);
    }
    /// @dev One read-only plan uses one fully validated pair vector. This is
    /// memory-only: execution and final contribution checks still read afresh.
    function _pairPrices(PoolConfig memory c) private view returns (PairPrices memory p) {
        IZZZOracle oracle = IZZZOracle(access.module(Ids.ORACLE));
        (p.first.lower,p.first.upper,) = oracle.priceBounds(c.key.currency0);
        (p.second.lower,p.second.upper,) = oracle.priceBounds(c.key.currency1);
        uint8 d0 = oracle.tokenDecimals(c.key.currency0);
        uint8 d1 = oracle.tokenDecimals(c.key.currency1);
        p.first.scale = 10 ** d0; p.second.scale = 10 ** d1;
        p.referenceX96 = ZZZPriceMath.referenceX96(p.first.lower,p.second.lower,d0,d1,c.key.currency0);
    }
    function _value(AssetPrice memory p, uint256 amount) private pure returns (uint256) {
        return Math.mulDiv(amount,p.lower,p.scale);
    }
    function _plan(bytes32 poolId, PoolConfig memory c, PairPrices memory prices,
        int24 lower, int24 upper, uint256 amount0, uint256 amount1)
        private view returns (bool zeroForOne, uint256 amountIn, uint256 minimumOut) {
        uint160 spotX96 = _checkedSpot(poolId,c,prices.referenceX96);
        uint160 a = TickMath.getSqrtPriceAtTick(lower);
        uint160 b = TickMath.getSqrtPriceAtTick(upper);
        uint256 unit0;
        uint256 unit1;
        if (spotX96 <= a) unit0 = SqrtPriceMath.getAmount0Delta(a, b, uint128(1e18), false);
        else if (spotX96 >= b) unit1 = SqrtPriceMath.getAmount1Delta(a, b, uint128(1e18), false);
        else {
            unit0 = SqrtPriceMath.getAmount0Delta(spotX96, b, uint128(1e18), false);
            unit1 = SqrtPriceMath.getAmount1Delta(a, spotX96, uint128(1e18), false);
        }
        uint256 v0 = _value(prices.first, amount0);
        uint256 v1 = _value(prices.second, amount1);
        uint256 u0 = _value(prices.first, unit0);
        uint256 u1 = _value(prices.second, unit1);
        if (u0 + u1 == 0) revert InvalidAmount();
        uint256 desired0 = Math.mulDiv(v0 + v1, u0, u0 + u1);
        zeroForOne = v0 > desired0;
        AssetPrice memory input = zeroForOne ? prices.first : prices.second;
        uint256 excess = zeroForOne ? v0 - desired0 : desired0 - v0;
        uint256 fee = _swapFee(poolId,c,zeroForOne);
        {
            // Every admitted v4 pool is static, hookless and native ETH/fixed ZZZ.
            // Size the net pair after its actual directional protocol + LP fee.
            uint256 inputWeight = Math.mulDiv(zeroForOne ? u0 : u1, 1e18, u0 + u1);
            excess = Math.mulDiv(excess, 1e18, 1e18 - Math.mulDiv(inputWeight, fee, 1_000_000));
        }
        amountIn = Math.mulDiv(excess, input.scale, input.lower);
        if (amountIn > (zeroForOne ? amount0 : amount1)) revert InvalidState();
        // Preserve Oracle.quote's two floor operations exactly: upper-valued
        // source USD first, then lower-valued output raw units.
        minimumOut = _minimum(prices,zeroForOne,amountIn,c.maxSlippageBps,fee);
        if (minimumOut == 0) amountIn = 0;
    }
}

src/ZZZV4RouteExecutor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {PoolKey} from "./libraries/ZZZTypes.sol";
import {ExactToken} from "./libraries/ExactToken.sol";
import {ExactAsset} from "./libraries/ExactAsset.sol";
import {IPoolManagerMinimal, IStateViewMinimal} from "./interfaces/IZZZ.sol";

/// @notice One parent's fixed-recipient, single-hop v4 conversion executor.
/// The immutable parent enforces governance, lifecycle and economic floors.
/// Conversion markets are separate from the Registry's NFT principal pools.
/// There is no arbitrary calldata, hook, recipient, approval or rescue surface.
contract ZZZV4RouteExecutor is ReentrancyGuard {
    struct Policy {
        address source;
        address output;
        PoolKey key;
        address poolManager;
        address stateView;
        bytes32 sourceCodeHash;
        bytes32 outputCodeHash;
        bytes32 poolManagerCodeHash;
        bytes32 stateViewCodeHash;
        bytes32 reviewHash;
    }
    address public immutable parent;
    bytes32 public constant NATIVE_ASSET_CODE_HASH = keccak256("ZZZ_NATIVE_ETH_V1");
    bytes32 public constant ROUTE_DOMAIN = keccak256("ZZZ_TYPED_V4_ROUTE_V1");
    mapping(bytes32 => Policy) private policies;
    mapping(bytes32 => bool) public routeExists;
    mapping(bytes32 => bool) public routeEnabled;
    bytes32 private pendingHash;
    address private pendingManager;
    address private nativeSender;
    uint256 private nativeReceived;
    error Unauthorized();
    error InvalidConfiguration();
    error InvalidAmount();
    error InvalidState();
    error Slippage();
    error Expired();
    event RouteRecorded(bytes32 indexed id, address indexed source, address indexed output, bytes32 reviewHash);
    event RouteEnabled(bytes32 indexed id, bool enabled);
    event Executed(bytes32 indexed id, uint256 input, uint256 output);

    constructor() { parent = msg.sender; }
    modifier onlyParent() { if (msg.sender != parent) revert Unauthorized(); _; }
    receive() external payable {
        if (msg.sender != nativeSender || nativeSender == address(0)) revert Unauthorized();
        nativeReceived += msg.value;
    }

    function addRoute(Policy calldata policy) external onlyParent nonReentrant returns (bytes32 id) {
        _check(policy); id = _id(policy);
        if (routeExists[id]) revert InvalidConfiguration();
        policies[id] = policy; routeExists[id] = true; routeEnabled[id] = true;
        emit RouteRecorded(id, policy.source, policy.output, policy.reviewHash); emit RouteEnabled(id, true);
    }
    /// @notice Stopping a route does not query its external dependencies.
    function setRouteEnabled(bytes32 id, bool enabled) external onlyParent nonReentrant {
        if (!routeExists[id]) revert InvalidConfiguration();
        if (enabled) { if (_id(policies[id]) != id) revert InvalidConfiguration(); _check(policies[id]); }
        routeEnabled[id] = enabled; emit RouteEnabled(id, enabled);
    }
    function route(bytes32 id) external view returns (Policy memory) {
        if (!routeExists[id]) revert InvalidConfiguration(); return policies[id];
    }
    function validate(bytes32 id) external view returns (Policy memory) { return _validated(id); }
    function _validated(bytes32 id) private view returns (Policy memory p) {
        if (!routeExists[id] || !routeEnabled[id]) revert InvalidConfiguration();
        p = policies[id];
        if (_id(p) != id) revert InvalidConfiguration();
        _check(p);
    }
    function _id(Policy memory p) private view returns (bytes32) {
        return keccak256(abi.encode(ROUTE_DOMAIN, block.chainid, address(this), parent, p));
    }
    function _pin(address target, bytes32 codeHash) private view {
        if (target == address(0) || codeHash == bytes32(0) || target.code.length == 0 || target.codehash != codeHash)
            revert InvalidConfiguration();
    }
    function _asset(address asset, bytes32 codeHash) private view {
        if (asset == address(0)) { if (codeHash != NATIVE_ASSET_CODE_HASH) revert InvalidConfiguration(); }
        else _pin(asset, codeHash);
    }
    function _check(Policy memory p) private view {
        PoolKey memory k = p.key;
        if (p.source == p.output || k.currency0 >= k.currency1 || k.hooks != address(0) ||
            k.fee >= 1000000 || k.tickSpacing < 1 || k.tickSpacing > 32767 || p.reviewHash == bytes32(0) ||
            !((p.source == k.currency0 && p.output == k.currency1) ||
                (p.source == k.currency1 && p.output == k.currency0))) revert InvalidConfiguration();
        _asset(p.source, p.sourceCodeHash); _asset(p.output, p.outputCodeHash);
        _pin(p.poolManager, p.poolManagerCodeHash); _pin(p.stateView, p.stateViewCodeHash);
        IStateViewMinimal view_ = IStateViewMinimal(p.stateView);
        if (view_.poolManager() != p.poolManager) revert InvalidConfiguration();
        (uint160 price,,, uint24 lpFee) = view_.getSlot0(keccak256(abi.encode(k)));
        if (price < TickMath.MIN_SQRT_PRICE || price >= TickMath.MAX_SQRT_PRICE || lpFee != k.fee)
            revert InvalidConfiguration();
    }

    function execute(bytes32 id, uint256 amountIn, uint256 minimumOut, uint256 deadline)
        external payable onlyParent nonReentrant returns (uint256 amountOut) {
        if (deadline < block.timestamp || deadline > block.timestamp + 10 minutes) revert Expired();
        if (amountIn == 0 || amountIn > uint256(uint128(type(int128).max)) || minimumOut == 0 ||
            minimumOut > uint256(uint128(type(int128).max))) revert InvalidAmount();
        Policy memory p = _validated(id);
        if (msg.value != (p.source == address(0) ? amountIn : 0)) revert InvalidAmount();
        uint256 nativeBefore = address(this).balance - msg.value;
        uint256 sourceBefore = ExactAsset.balance(p.source, address(this)) - msg.value;
        uint256 outputBefore = ExactAsset.balance(p.output, address(this));
        if (p.source != address(0)) ExactToken.pull(p.source, parent, amountIn);
        // An ERC20 callback cannot inject ETH and disguise it as swap output,
        // or let prefunded ETH subsidize the exact declared native budget.
        if (address(this).balance != nativeBefore + msg.value) revert InvalidState();
        bytes memory payload = abi.encode(p.key, p.source, p.output, amountIn, minimumOut);
        pendingHash = keccak256(payload); pendingManager = p.poolManager;
        amountOut = abi.decode(IPoolManagerMinimal(p.poolManager).unlock(payload), (uint256));
        if (pendingHash != bytes32(0) || pendingManager != address(0) || nativeSender != address(0) ||
            nativeReceived != 0 || amountOut < minimumOut ||
            ExactAsset.balance(p.source, address(this)) != sourceBefore ||
            ExactAsset.balance(p.output, address(this)) != outputBefore + amountOut ||
            address(this).balance != nativeBefore + (p.output == address(0) ? amountOut : 0)) revert InvalidState();
        _check(p);
        uint256 parentBefore = ExactAsset.balance(p.output, parent);
        ExactAsset.push(p.output, parent, amountOut);
        if (ExactAsset.balance(p.source, address(this)) != sourceBefore ||
            ExactAsset.balance(p.output, address(this)) != outputBefore || address(this).balance != nativeBefore ||
            ExactAsset.balance(p.output, parent) != parentBefore + amountOut) revert InvalidState();
        _check(p);
        emit Executed(id, amountIn, amountOut);
    }

    function unlockCallback(bytes calldata payload) external returns (bytes memory) {
        if (msg.sender != pendingManager || pendingHash == bytes32(0) || pendingHash != keccak256(payload))
            revert Unauthorized();
        pendingHash = bytes32(0); pendingManager = address(0);
        (PoolKey memory key, address source, address output, uint256 amountIn, uint256 minimumOut) =
            abi.decode(payload, (PoolKey, address, address, uint256, uint256));
        IPoolManagerMinimal manager = IPoolManagerMinimal(msg.sender);
        bool zeroForOne = source == key.currency0;
        int256 delta = manager.swap(key, IPoolManagerMinimal.SwapParams(zeroForOne, -int256(amountIn),
            zeroForOne ? TickMath.MIN_SQRT_PRICE + 1 : TickMath.MAX_SQRT_PRICE - 1), bytes(""));
        int128 delta0 = int128(delta >> 128); int128 delta1 = int128(uint128(uint256(delta)));
        int128 inputDelta = zeroForOne ? delta0 : delta1;
        int128 outputDelta = zeroForOne ? delta1 : delta0;
        if (inputDelta >= 0 || outputDelta <= 0 || uint256(-int256(inputDelta)) != amountIn ||
            uint256(int256(outputDelta)) < minimumOut) revert Slippage();
        manager.sync(source);
        if (source == address(0)) {
            if (manager.settle{value: amountIn}() != amountIn) revert InvalidState();
        } else {
            ExactToken.push(source, msg.sender, amountIn);
            if (manager.settle() != amountIn) revert InvalidState();
        }
        uint256 amountOut = uint256(int256(outputDelta));
        uint256 beforeOutput = ExactAsset.balance(output, address(this));
        if (output == address(0)) { nativeSender = msg.sender; nativeReceived = 0; }
        manager.take(output, address(this), amountOut);
        if (output == address(0)) {
            if (nativeReceived != amountOut) revert InvalidState();
            nativeSender = address(0); nativeReceived = 0;
        }
        if (ExactAsset.balance(output, address(this)) != beforeOutput + amountOut) revert InvalidState();
        return abi.encode(amountOut);
    }
}

src/ZZZVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {ZZZModule} from "./base/ZZZModule.sol";
import {ZZZMigrationBudget} from "./ZZZMigrationBudget.sol";
import {ZZZVaultCanonical} from "./ZZZVaultCanonical.sol";
import {IZZZEmergencyLiquidity} from "./interfaces/IZZZEmergency.sol";
import {Ids, Position, PositionStatus} from "./libraries/ZZZTypes.sol";
import {ExactToken} from "./libraries/ExactToken.sol";
import {ExactAsset} from "./libraries/ExactAsset.sol";
import {
    IZZZNFT,
    IZZZMembership,
    IZZZFees,
    IZZZPools,
    IZZZLiquidity,
    IPositionManagerMinimal,
    IZZZRewards,
    IZZZActivationEntry
} from "./interfaces/IZZZ.sol";
interface IVaultPositionOperator { function positionOperator() external view returns(address); }
interface IVaultResidualLiquidity { function closeSecondary(bytes32,uint256,uint256) external; }
interface IVaultManualContext { function consolidationActive() external view returns(bool); }

/// @notice Non-upgradeable custody. No holder redemption during operation.
/// Governance may irreversibly settle actual principal to NFT holders.
/// Deposits, idle assets, compound reserves and earned fees are separate ledgers.
contract ZZZVault is ZZZModule, ReentrancyGuard, IERC721Receiver {
    mapping(uint256 => Position) private positions; // Custody is keyed by stable bucket, never NFT.
    mapping(uint256 => bool) private minted;
    mapping(uint256 => uint256) public nftBucket;
    mapping(uint256 => uint256) public sharesOf;
    mapping(uint256 => uint256) public contributionUSD;
    mapping(uint256 => uint256) public bucketTotalShares;
    mapping(uint256 => bytes32) public homePoolId;
    mapping(bytes32 => uint256) public poolBucket;
    uint256[] private buckets;
    mapping(uint256 => bool) private registeredBucket;
    // Bounds historical custody and collective fee-dust settlement work.
    // Existing-bucket returns and pool migrations reuse their historical slot.
    uint256 public constant MAX_BUCKETS = 4;
    event PoolReserved(bytes32 indexed poolId, uint256 indexed bucketId);
    event SharesAdded(uint256 indexed nftId, uint256 indexed bucketId, uint256 shares, uint256 netUSD);
    mapping(address => uint256) public totalIdle;
    uint256 private nativeReceived;
    uint256 public sequence;
    uint256 public immutable canonicalChainId;
    ZZZMigrationBudget public immutable migrationBudget;
    uint256 public constant ACCOUNTING_VERSION = 7;
    uint256 public constant RESIDUAL_EXIT_VERSION = 1;
    uint256 public constant RESIDUAL_REINVEST_VERSION = 1;
    event DormantMinted(uint256 indexed nftId, address indexed owner, uint256 mintPrice);
    event Activated(
        uint256 indexed nftId, address indexed owner, bytes32 indexed poolId, uint256 amount0, uint256 amount1
    );
    event LiquidityAdded(uint256 indexed nftId, uint256 amount0, uint256 amount1);
    event FeesCollected(uint256 indexed bucketId, uint256 amount0, uint256 amount1);
    event Rebalanced(uint256 indexed bucketId, uint256 oldLpTokenId, uint256 newLpTokenId, uint160 centerX96);
    event Compounded(uint256 indexed bucketId, uint256 amount0, uint256 amount1);
    event PrincipalReturnedToHolders(uint256 indexed bucketId, uint256 amountETH, uint256 amountZZZ);
    event PrincipalParked(uint256 indexed bucketId, uint256 oldLpTokenId);

    constructor(address controller, uint256 nftHomeChain, address budget)
        ZZZModule(controller) {
        if (nftHomeChain == 0 || access.protocolPolicy().code.length == 0) {
            revert InvalidConfiguration();
        }
        if (budget.code.length == 0 || address(ZZZMigrationBudget(budget).access()) != controller ||
            ZZZMigrationBudget(budget).IDLE_COMPOUNDING_VERSION() != 4) revert InvalidConfiguration();
        canonicalChainId = nftHomeChain;
        migrationBudget = ZZZMigrationBudget(budget);
    }

    receive() external payable {
        if (migrationBudget.validateNativeSender(msg.sender)) nativeReceived += msg.value;
    }

    /// @notice NFT lifecycle is separate from shared physical LP custody.
    function nftStatus(uint256 id) external view returns (PositionStatus) {
        if (!minted[id]) return PositionStatus.None;
        uint256 bucket = nftBucket[id];
        return bucket == 0 ? PositionStatus.Dormant : positions[bucket].status;
    }

    function group(uint256 bucket) external view returns (Position memory) {
        return positions[bucket];
    }

    function bucketCount() external view returns (uint256) {
        return buckets.length;
    }

    function bucketAt(uint256 index) external view returns (uint256) {
        return buckets[index];
    }

    function canonicalModule() public view returns (ZZZVaultCanonical) {
        return ZZZVaultCanonical(payable(access.module(Ids.VAULT_CANONICAL)));
    }

    /// @dev Reservations and historical custody share permanent slots. Reusing a
    /// bucket (including through another pool alias) never consumes another slot.
    function _registerBucket(uint256 bucketId) private {
        if (registeredBucket[bucketId]) return;
        if (buckets.length == MAX_BUCKETS) revert InvalidState();
        registeredBucket[bucketId] = true;
        buckets.push(bucketId);
    }

    /// @notice Permanently reserve capacity before approving a route. Pool
    /// reservations cannot be reassigned or released on cancellation/timeout.
    function reservePool(bytes32 pool, uint256 bucket) external onlyGovernance principalOperating {
        _reserve(pool, bucket);
    }

    function _reserve(bytes32 pool, uint256 bucketId) private {
        migrationBudget.validateReservation(pool, bucketId);
        _registerBucket(bucketId);
        poolBucket[pool] = bucketId;
        canonicalModule().registerAlias(pool, bucketId);
        emit PoolReserved(pool, bucketId);
    }

    function _tokens(uint256 bucketId) private view returns (address token0, address token1) {
        return migrationBudget.poolTokens(positions[bucketId].poolId);
    }

    function _nft() private view returns (IZZZNFT) {
        return IZZZNFT(access.module(Ids.NFT));
    }

    function _requireOwner(uint256 nftId, bool activation) private view {
        address entry = migrationBudget.validateOwner(nftId, msg.sender, minted[nftId], activation);
        if (entry != address(0)) IZZZActivationEntry(entry).validateOwner(nftId, keccak256(msg.data));
    }

    function _active(uint256 bucketId) private view {
        if (positions[bucketId].status != PositionStatus.Active) revert InvalidState();
    }

    function _tokenBalance(address token) private view returns (uint256) {
        return ExactAsset.balance(token, address(this));
    }

    function _receiveAssets(address token0, address token1, uint256 amount0, uint256 amount1) internal virtual {
        // Every admitted current pool is native ETH/fixed ZZZ. Historical
        // wrapped/foreign-pair deployments retain their own source profile.
        if (token0 != address(0) || msg.value != amount0) revert InvalidAmount();
        ExactToken.pull(token1, msg.sender, amount1);
    }

    /// @dev Production always admits native ETH in slot zero. This typed
    /// internal seam permits isolated accounting fixtures to substitute transport;
    /// it creates no public extension, upgrade or configurable approval target.
    function _approvePrincipalAssets(address token0,address token1,address spender,uint256,uint256 amount1)
        internal virtual {
        if (token0 != address(0)) revert InvalidConfiguration();
        ExactAsset.approve(token1,spender,amount1);
    }

    function _idle(uint256 bucketId, uint256 new0, uint256 new1) private {
        Position storage p = positions[bucketId];
        (address token0, address token1) = _tokens(bucketId);
        totalIdle[token0] = totalIdle[token0] - p.idle0 + new0;
        totalIdle[token1] = totalIdle[token1] - p.idle1 + new1;
        p.idle0 = new0;
        p.idle1 = new1;
        migrationBudget.assertIdle(bucketId);
    }

    function _valueBucket(uint256 bucketId, uint256 amount0, uint256 amount1) private view returns (uint256) {
        return migrationBudget.valueBucket(bucketId, amount0, amount1);
    }
    function _approveLP(IPositionManagerMinimal positionManager,address manager,uint256 id) private {
        positionManager.approve(manager,id);
    }

    function _put(uint256 bucketId, bool create, uint128 minimumLiquidity, uint256 deadline,
        uint256 a0, uint256 a1) private {
        ZZZMigrationBudget budget = migrationBudget;
        Position storage p = positions[bucketId];
        (address token0, address token1) = _tokens(bucketId);
        IZZZLiquidity manager = IZZZLiquidity(_moduleLiquidity());
        address operator = IVaultPositionOperator(address(manager)).positionOperator();
        // A contribution can deploy only its own post-swap amounts. Incumbent
        // idle and released compound remain attributed for guarded maintenance.
        if (a0 > p.idle0 || a1 > p.idle1) revert InvalidAmount();
        uint256 before0 = _tokenBalance(token0);
        uint256 before1 = _tokenBalance(token1);
        _approvePrincipalAssets(token0,token1,operator,a0,a1);
        uint256 nativeValue = token0 == address(0) ? a0 : 0;
        uint256 spent0;
        uint256 spent1;
        if (create) {
            (int24 lower, int24 upper, uint160 ref) = budget.mintTarget(bucketId);
            (p.lpTokenId, spent0, spent1) =
                manager.mint{value: nativeValue}(p.poolId, lower, upper, a0, a1, minimumLiquidity, deadline);
            IPositionManagerMinimal positionManager = IPositionManagerMinimal(manager.positionManager());
            _approveLP(positionManager,operator,p.lpTokenId);
            uint256 secondary = manager.secondaryId(p.lpTokenId);
            if (secondary != 0) _approveLP(positionManager,operator,secondary);
            p.centerX96 = ref;
            p.lastRebalance = uint64(block.timestamp);
        } else {
            (spent0, spent1) =
                manager.increase{value: nativeValue}(p.poolId, p.lpTokenId, a0, a1, minimumLiquidity, deadline);
        }
        _approvePrincipalAssets(token0,token1,operator,0,0);
        budget.assertPut(bucketId, a0, a1, spent0, spent1, before0, before1);
        _idle(bucketId, p.idle0 - spent0, p.idle1 - spent1);
        budget.assertDeployed(bucketId);
    }

    /// @notice Paid issuance creates no LP, collective membership or fee entitlement. Proceeds are
    /// forwarded separately and never enter the permanently locked principal ledger.
    function mintPrice() external view returns(uint256) {
        return canonicalModule().mintPrice();
    }
    function mintProceedsRecipient() external view returns(address payable) {
        return payable(canonicalModule().mintProceedsRecipient());
    }
    function mintPolicyFingerprint() external view returns(bytes32) {
        return canonicalModule().mintPolicyFingerprint();
    }
    function mintDormant(bytes32 expectedMintPolicy) external payable live operating principalOperating nonReentrant returns (uint256 id) {
        address recipient;
        (id,recipient) = canonicalModule().validateMint(msg.value, ++sequence,expectedMintPolicy);
        if (minted[id]) revert InvalidState();
        minted[id] = true;
        _nft().mint(msg.sender, id);
        (bool paid,) = payable(recipient).call{value: msg.value}("");
        if (!paid || canonicalModule().mintPolicyFingerprint() != expectedMintPolicy) revert InvalidState();
        emit DormantMinted(id, msg.sender, msg.value);
    }

    /// @notice New NFTs join the sole shared position for this pool. No redeemable token is issued.
    function activate(
        uint256 id,
        bytes32 poolId,
        uint256 amount0,
        uint256 amount1,
        uint128 minimumLiquidity,
        uint256 deadline
    ) external payable live operating principalOperating nonReentrant {
        _requireOwner(id, true);
        uint256 bucket = poolBucket[poolId];
        if (bucket == 0 || positions[bucket].status == PositionStatus.None) {
            uint256 canonicalBucket = canonicalModule().bucketIdentity(poolId);
            if (bucket != 0 && bucket != canonicalBucket) revert InvalidState();
            bucket = canonicalBucket;
            _reserve(poolId, bucket);
            homePoolId[bucket] = poolId;
            Position storage p = positions[bucket];
            p.poolId = poolId;
            p.status = PositionStatus.Active;
        }
        if (positions[bucket].poolId != poolId) revert InvalidState();
        nftBucket[id] = bucket; // Set the fee-index domain BEFORE checkpointing zero shares.
        _join(id, bucket, amount0, amount1, minimumLiquidity, deadline, true);
        emit Activated(id, _nft().ownerOf(id), poolId, amount0, amount1);
    }

    function increase(uint256 id, uint256 amount0, uint256 amount1, uint128 minimumLiquidity, uint256 deadline)
        external
        payable
        live
        operating
        principalOperating
        nonReentrant
    {
        _requireOwner(id, false);
        uint256 bucket = nftBucket[id];
        if (bucket == 0) revert InvalidState();
        _join(id, bucket, amount0, amount1, minimumLiquidity, deadline, false);
        emit LiquidityAdded(id, amount0, amount1);
    }

    function _nav(uint256 bucketId) private returns (uint256 deployed, uint256 idleValue) {
        return migrationBudget.contributionNav(bucketId);
    }

    function _join(
        uint256 nftId,
        uint256 bucketId,
        uint256 amount0,
        uint256 amount1,
        uint128 minimumLiquidity,
        uint256 deadline,
        bool activation
    ) private {
        _deadline(deadline);
        Position storage p = positions[bucketId];
        uint256 inputUSD = IZZZPools(_modulePools()).contributionValue(p.poolId, amount0, amount1);
        (address token0, address token1, uint32 limits) = migrationBudget.validateContribution(
            nftId, bucketId, inputUSD, amount0 | (amount1 << 128), minimumLiquidity, activation
        );
        uint256 supply = bucketTotalShares[bucketId];
        // Settle all already-funded collective dust before eligibility changes.
        // Only this nonreentrant Vault can allocate new LP fee receipts.
        IZZZMembership(access.module(Ids.MEMBERSHIP)).settleDust();
        if (supply != 0) {
            _harvest(bucketId, deadline);
            _flushDust(bucketId,token0,token1);
            _pullCompound(bucketId);
        }
        (uint256 oldLP, uint256 oldIdle) = _nav(bucketId);
        uint256 incumbentNAV = oldLP + oldIdle;
        if (supply != 0 && incumbentNAV == 0) revert InvalidState();
        _receiveAssets(token0, token1, amount0, amount1);
        _idle(bucketId, p.idle0 + amount0, p.idle1 + amount1);
        (amount0, amount1) = _balanceUsing(bucketId, deadline, amount0, amount1);
        uint256 freshCompound;
        if (supply != 0) {
            // Fees earned by the entry swap belong to pre-entry membership.
            _harvest(bucketId, deadline);
            _flushDust(bucketId,token0,token1);
            (uint256 f0, uint256 f1) = _pullCompound(bucketId);
            freshCompound = _valueBucket(bucketId, f0, f1);
        }
        // Concentrated LP amounts reprice during the entry swap. Preserve that
        // gain/loss for incumbents; only net new assets buy the entrant's shares.
        (oldLP,) = _nav(bucketId);
        incumbentNAV = oldLP + oldIdle + freshCompound;
        if (supply != 0 && incumbentNAV == 0) revert InvalidState();
        _put(bucketId, supply == 0, minimumLiquidity, deadline, amount0, amount1);
        (uint256 late0, uint256 late1) = _pullCompound(bucketId);
        incumbentNAV += _valueBucket(bucketId, late0, late1);
        (uint256 newLP, uint256 newIdle) = _nav(bucketId);
        // The captured governed contribution limit applies to activation and
        // growth. Network gas is separate; later callbacks cannot widen this budget.
        // Incumbent idle/compound assets cannot subsidize this contribution.
        (uint256 issued, uint256 netUSD) = migrationBudget.contributionResult(
            bucketId, inputUSD, supply, incumbentNAV, oldLP, newLP, newIdle, limits
        );
        sharesOf[nftId] += issued;
        bucketTotalShares[bucketId] = supply + issued;
        IZZZRewards(access.module(Ids.REWARDS)).syncShares(nftId);
        contributionUSD[nftId] += inputUSD;
        p.depositUSD += inputUSD;
        if (activation) IZZZMembership(access.module(Ids.MEMBERSHIP)).activate(nftId);
        _nft().notifyContribution(nftId);
        emit SharesAdded(nftId, bucketId, issued, netUSD);
    }

    function _allocate(uint256 bucketId, address token, uint256 amount) private {
        if (amount == 0) return;
        address fees = _moduleFees();
        ExactAsset.approve(token, fees, amount);
        IZZZFees(fees).allocate{value: token == address(0) ? amount : 0}(bucketId, token, amount);
        ExactAsset.approve(token, fees, 0);
    }

    /// @dev Separate and fund venue fees before closing principal.
    function _harvest(uint256 bucketId, uint256 deadline) private {
        _receiveVenue(bucketId, deadline, 0);
    }

    /// @dev Collection and closure share the same exact net-receipt proof.
    /// Manager performs the bounded portfolio operation atomically; neither
    /// raw prefunds nor forced ETH can become attributed receipts.
    /// @param operation Internal typed mode: collect=0, full close=1, residual close=2.
    function _receiveVenue(uint256 bucketId, uint256 deadline, uint8 operation) private {
        Position storage p = positions[bucketId];
        (address token0, address token1) = _tokens(bucketId);
        uint256 before0 = _tokenBalance(token0);
        uint256 before1 = _tokenBalance(token1);
        uint256 received = nativeReceived;
        IZZZLiquidity manager = IZZZLiquidity(_moduleLiquidity());
        if (operation == 0) manager.collect(p.poolId, p.lpTokenId, deadline);
        else if (operation == 1) manager.close(p.poolId, p.lpTokenId, deadline);
        else IVaultResidualLiquidity(address(manager)).closeSecondary(p.poolId, p.lpTokenId, deadline);
        uint256 amount0 = _tokenBalance(token0) - before0;
        uint256 amount1 = _tokenBalance(token1) - before1;
        if (token0 == address(0) && amount0 != nativeReceived - received) revert InvalidState();
        if (operation != 0) {
            if (operation == 1) p.lpTokenId = 0;
            _idle(bucketId, p.idle0 + amount0, p.idle1 + amount1);
        } else {
            _allocate(bucketId, token0, amount0);
            _allocate(bucketId, token1, amount1);
            emit FeesCollected(bucketId, amount0, amount1);
        }
    }

    function collectFees(uint256 id, uint256 deadline) external live nonReentrant canonicalAccounting principalOperating {
        _deadline(deadline);
        _active(id);
        _harvest(id, deadline);
    }

    function _pullCompound(uint256 bucketId) private returns (uint256 amount0, uint256 amount1) {
        (address token0, address token1) = _tokens(bucketId);
        Position storage p = positions[bucketId];
        IZZZFees fees = IZZZFees(_moduleFees());
        amount0 = fees.releaseCompound(bucketId, token0);
        amount1 = fees.releaseCompound(bucketId, token1);
        _idle(bucketId, p.idle0 + amount0, p.idle1 + amount1);
    }
    /// @dev Keep these external calls in Vault so Fees sees its exact authorized
    /// caller. Entry checkpoints and terminal exit retain their original order.
    function _flushDust(uint256 bucketId,address token0,address token1) private {
        IZZZFees fees=IZZZFees(_moduleFees());
        fees.flushDust(bucketId,token0); fees.flushDust(bucketId,token1);
    }

    function compound(uint256 id, uint128 minimumLiquidity, uint256 deadline)
        external
        onlyModule(Ids.COMPOUNDER)
        live
        operating
        principalOperating
        nonReentrant
    {
        (uint256 amount0,uint256 amount1)=_reinvest(id,minimumLiquidity,deadline,3);
        emit Compounded(id, amount0, amount1);
    }

    /// @dev Both paths reuse identical actual-receipt, balancing and LP proofs.
    /// Phase4 consumes already-attributed idle and residual principal only.
    function _reinvest(uint256 id,uint128 minimumLiquidity,uint256 deadline,uint8 phase)
        private returns(uint256 amount0,uint256 amount1) {
        _deadline(deadline); _active(id);
        _migrationCheckpoint(id,phase);
        _harvest(id,deadline);
        if(phase==3) (amount0,amount1)=_pullCompound(id);
        // Residual principal is already in the starting denominator. Include
        // released compound BEFORE closing it, never count proceeds twice.
        _migrationCheckpoint(id,1);
        if(phase==4 && IZZZLiquidity(_moduleLiquidity()).secondaryId(positions[id].lpTokenId)!=0)
            _receiveVenue(id,deadline,2);
        _redeploy(id,minimumLiquidity,deadline);
        _migrationCheckpoint(id,2);
    }

    function _close(uint256 bucketId, uint256 deadline) private {
        _receiveVenue(bucketId, deadline, 1);
    }

    /// @dev One atomic route/size decision consumes only this explicit budget.
    /// Whole-bucket attribution remains intact during external calls.
    function _balanceUsing(uint256 bucketId, uint256 deadline, uint256 amount0, uint256 amount1)
        private returns (uint256 balanced0, uint256 balanced1) {
        Position storage p = positions[bucketId];
        if (amount0 > p.idle0 || amount1 > p.idle1) revert InvalidAmount();
        (address token0, address token1) = _tokens(bucketId);
        address manager = _moduleLiquidity();
        uint256 before0 = _tokenBalance(token0);
        uint256 before1 = _tokenBalance(token1);
        bytes32 context = migrationBudget.balanceContext(bucketId);
        _approvePrincipalAssets(token0,token1,manager,amount0,amount1);
        (balanced0, balanced1) = IZZZLiquidity(manager).balance{value: token0 == address(0) ? amount0 : 0}(
            p.poolId, p.lpTokenId, amount0, amount1, deadline
        );
        _approvePrincipalAssets(token0,token1,manager,0,0);
        if (migrationBudget.balanceContext(bucketId) != context) revert InvalidState();
        // A typed return must match actual net receipts. Existing raw prefunds
        // or callback donations cannot fill a claimed balancing-output shortfall.
        if (_tokenBalance(token0) + amount0 != before0 + balanced0 ||
            _tokenBalance(token1) + amount1 != before1 + balanced1) revert InvalidState();
        _idle(bucketId, p.idle0 - amount0 + balanced0, p.idle1 - amount1 + balanced1);
    }

    function _idleValue(uint256 bucketId) private view returns (uint256) {
        return migrationBudget.idleValue(bucketId);
    }

    function _unwind(uint256 bucketId, uint256 deadline) private {
        migrationBudget.validateUnwind(bucketId);
        _harvest(bucketId, deadline);
        _pullCompound(bucketId);
        _migrationCheckpoint(bucketId, 1);
        _close(bucketId, deadline);
    }

    function _migrationCheckpoint(uint256 bucketId, uint8 phase) private {
        migrationBudget.checkpoint(bucketId, phase);
    }

    function _redeploy(uint256 bucketId, uint128 minimumLiquidity, uint256 deadline) private {
        bool create = positions[bucketId].lpTokenId == 0;
        uint256 beforeValue = _idleValue(bucketId);
        Position storage p = positions[bucketId];
        _balanceUsing(bucketId, deadline, p.idle0, p.idle1);
        // An existing LP can earn fees from its one balancing swap. Settle
        // them separately before INCREASE; they are never treated as principal.
        if (!create) _harvest(bucketId, deadline);
        migrationBudget.assertIdleLoss(bucketId, beforeValue);
        _put(bucketId, create, minimumLiquidity, deadline, p.idle0, p.idle1);
    }

    function rebalance(uint256 id, uint128 minimumLiquidity, uint256 deadline)
        external
        onlyKeeper
        live
        operating
        principalOperating
        nonReentrant
    {
        _rebalance(id,minimumLiquidity,deadline,false);
        if (!access.keeperAuthorized(msg.sender) || access.paused()) revert Unauthorized();
    }
    /// @notice Fixed Migration's typed manual dispatcher. Its active reviewed
    /// context chooses same-main reinvestment; otherwise the original scoped
    /// emergency replaces the portfolio. No arbitrary selector or recipient.
    function emergencyRebalance(uint256 id,uint128 minimumLiquidity,uint256 deadline)
        external onlyModule(Ids.MIGRATION) operating principalOperating nonReentrant {
        bool consolidation=IVaultManualContext(msg.sender).consolidationActive();
        bool forced=migrationBudget.emergencyActive();
        IZZZEmergencyLiquidity manager=IZZZEmergencyLiquidity(_moduleLiquidity());
        if(forced) manager.beginEmergency();
        if(consolidation) {
            if(!access.paused() || positions[id].lpTokenId==0 || minimumLiquidity==0) revert InvalidState();
            if(forced) migrationBudget.validateRebalance(id,minimumLiquidity);
            _reinvest(id,minimumLiquidity,deadline,4);
            if(!access.paused()) revert InvalidState();
        } else {
            if(!forced) revert InvalidState();
            _rebalance(id,minimumLiquidity,deadline,true);
        }
        if(forced) manager.endEmergency();
    }
    function _rebalance(uint256 id,uint128 minimumLiquidity,uint256 deadline,bool emergency) private {
        _deadline(deadline);
        bool parked = emergency && positions[id].status == PositionStatus.Parked;
        if(!parked) _active(id);
        migrationBudget.validateRebalance(id, minimumLiquidity);
        Position storage p = positions[id];
        uint256 oldId = p.lpTokenId;
        _migrationCheckpoint(id, 0);
        if(parked) { _pullCompound(id); _migrationCheckpoint(id,1); }
        else _unwind(id, deadline);
        _redeploy(id, minimumLiquidity, deadline);
        _migrationCheckpoint(id, 2);
        if(parked) p.status = PositionStatus.Active;
        emit Rebalanced(id, oldId, p.lpTokenId, p.centerX96);
    }

    /// @notice Migration commits terminal LP retirement through this lock so it
    /// cannot start reentrantly inside contribution, harvest or maintenance.
    function beginLPExit() external onlyModule(Ids.MIGRATION) operating nonReentrant {
        access.startLPExit();
    }

    /// @notice Close one fixed ETH/ZZZ bucket into the holder settlement module.
    /// No swap or USD price dependency. Only attributed principal and its 5%
    /// compound reserve leave; earned fees, buyback reserves and donations do not.
    function exitBucketToHolders(uint256 id, uint256 minimumETH, uint256 minimumZZZ, uint256 deadline)
        external onlyModule(Ids.MIGRATION) operating nonReentrant
        returns (uint256 amountETH, uint256 amountZZZ)
    {
        _deadline(deadline);
        Position storage p = positions[id];
        (address token0, address token1) = migrationBudget.validateHolderExit(id,msg.sender);
        // Final harvest runs while Active, as required by funded fee allocation.
        if (p.status == PositionStatus.Active) _harvest(id, deadline);
        _flushDust(id,token0,token1);
        _pullCompound(id);
        if (p.status == PositionStatus.Active) _close(id, deadline);
        if (p.lpTokenId != 0) revert InvalidState();
        amountETH = p.idle0;
        amountZZZ = p.idle1;
        if (amountETH < minimumETH || amountZZZ < minimumZZZ) revert Slippage();
        _idle(id, 0, 0);
        p.status = PositionStatus.Exited;
        migrationBudget.recordComposition(id);
        ExactAsset.push(token0, msg.sender, amountETH);
        ExactAsset.push(token1, msg.sender, amountZZZ);
        emit PrincipalReturnedToHolders(id, amountETH, amountZZZ);
    }

    /// @notice Paused governed residual-only close. Actual proceeds remain
    /// attributed to this bucket; no swap, holder payout or main replacement.
    /// A large retained idle balance is intentional recovery state, not entry
    /// permission to bypass the ordinary deployment/idle/loss checks.
    function closeResidual(uint256 id,uint256 deadline)
        external onlyModule(Ids.MIGRATION) operating principalOperating nonReentrant {
        _deadline(deadline);
        migrationBudget.validateResidualClose(id);
        _harvest(id,deadline);
        _receiveVenue(id,deadline,2);
        if(!access.paused()) revert InvalidState();
    }

    /// @notice Only the fixed Migration module can park an LP. Its governed
    /// request binds exact custody and raw close minimums. No assets leave Vault.
    function park(uint256 id, uint256 deadline) external onlyModule(Ids.MIGRATION) nonReentrant canonicalAccounting principalOperating {
        _deadline(deadline);
        _active(id);
        if (!access.paused() || positions[id].lpTokenId == 0) revert InvalidState();
        uint256 oldLp = positions[id].lpTokenId;
        _harvest(id, deadline);
        _close(id, deadline);
        positions[id].status = PositionStatus.Parked;
        emit PrincipalParked(id, oldLp);
    }

    function resume(uint256 id, bytes32 newPool, uint128 minimumLiquidity, uint256 deadline)
        external
        onlyModule(Ids.MIGRATION)
        live
        operating
        principalOperating
        nonReentrant
    {
        _deadline(deadline);
        if (positions[id].status != PositionStatus.Parked) revert InvalidState();
        _movePool(id, newPool, minimumLiquidity, deadline);
        positions[id].status = PositionStatus.Active;
    }

    function movePool(uint256 id, bytes32 newPool, uint128 minimumLiquidity, uint256 deadline)
        external
        onlyModule(Ids.MIGRATION)
        live
        operating
        principalOperating
        nonReentrant
    {
        _deadline(deadline);
        _active(id);
        if (positions[id].poolId == newPool) revert InvalidConfiguration();
        _movePool(id, newPool, minimumLiquidity, deadline);
    }

    function _movePool(uint256 bucketId, bytes32 newPool, uint128 minimumLiquidity, uint256 deadline) private {
        Position storage p = positions[bucketId];
        migrationBudget.validateMove(bucketId, newPool, minimumLiquidity);
        _reserve(newPool, bucketId);
        uint256 oldId = p.lpTokenId;
        _migrationCheckpoint(bucketId, 0);
        if (p.status == PositionStatus.Parked) {
            _pullCompound(bucketId);
            _migrationCheckpoint(bucketId, 1);
        } else {
            _unwind(bucketId, deadline);
        }
        p.poolId = newPool; // Ordinary local maintenance retains its ordered-pair guard.
        _redeploy(bucketId, minimumLiquidity, deadline);
        _migrationCheckpoint(bucketId, 2);
        emit Rebalanced(bucketId, oldId, p.lpTokenId, p.centerX96);
    }

    function onERC721Received(address, address, uint256, bytes calldata) external view override returns (bytes4) {
        migrationBudget.validateLPReceiver(msg.sender);
        return IERC721Receiver.onERC721Received.selector;
    }

    /// @dev Only the immutable canonical companion can write source-authenticated
    /// records while this deployment is inert. No raw storage slots are exposed.
    function canonicalWrite(uint8 kind, bytes calldata row) external {
        migrationBudget.validateCanonicalWriter(msg.sender);
        if (kind == 0) {
            sequence = abi.decode(row, (uint256));
        } else if (kind == 1) {
            (uint256 id, uint256 bucket, uint256 shares, uint256 contribution) =
                abi.decode(row, (uint256, uint256, uint256, uint256));
            if (minted[id]) revert InvalidState();
            minted[id] = true;
            nftBucket[id] = bucket;
            sharesOf[id] = shares;
            contributionUSD[id] = contribution;
        } else if (kind == 2) {
            (uint256 id, Position memory p, uint256 shares, bytes32 homePool) =
                abi.decode(row, (uint256, Position, uint256, bytes32));
            _registerBucket(id);
            positions[id] = p;
            bucketTotalShares[id] = shares;
            homePoolId[id] = homePool;
            if (p.status == PositionStatus.Parked) {
                (address a, address b) = migrationBudget.poolTokens(p.poolId);
                totalIdle[a] += p.idle0;
                totalIdle[b] += p.idle1;
            }
        } else if (kind == 3) {
            (bytes32 pool, uint256 id) = abi.decode(row, (bytes32, uint256));
            poolBucket[pool] = id;
        } else {
            revert InvalidConfiguration();
        }
    }

    /// @dev Recipient and amount come only from the fixed companion's captured
    /// manifest and the handoff's fixed module pairing. No public rescue path.
    function canonicalSend(address token, address destination, uint256 amount) external {
        _canonicalSender();
        ExactAsset.push(token, destination, amount);
    }

    function canonicalBarrier() external nonReentrant {
        _canonicalSender();
    }

    function _canonicalSender() private view {
        if (msg.sender != access.module(Ids.VAULT_CANONICAL)) revert Unauthorized();
    }

    // No individual early redemption, external custody recipient or generic sweep.
    function _modulePools() private view returns (address) {
        return access.module(Ids.POOLS);
    }

    function _moduleLiquidity() private view returns (address) {
        return access.module(Ids.LIQUIDITY);
    }

    function _moduleFees() private view returns (address) {
        return access.module(Ids.FEES);
    }
}

src/ZZZVaultCanonical.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IZZZAccess, IZZZVault, IZZZPools, IZZZMigration, IZZZNFT, IZZZLiquidity} from "./interfaces/IZZZ.sol";
import {IZZZCanonicalAccess} from "./interfaces/IZZZCanonical.sol";
import {Ids, Position, PositionStatus, PoolConfig} from "./libraries/ZZZTypes.sol";
import {ExactAsset} from "./libraries/ExactAsset.sol";
import {ZZZMigrationBudget} from "./ZZZMigrationBudget.sol";
import {IZZZProtocolPolicy} from "./interfaces/IZZZProtocolPolicy.sol";

interface ICanonicalVaultState is IZZZVault {
    function ACCOUNTING_VERSION() external view returns(uint256);
    function migrationBudget() external view returns (ZZZMigrationBudget);
    function mintPrice() external view returns (uint256);
    function sequence() external view returns (uint256);
    function contributionUSD(uint256 id) external view returns (uint256);
    function totalIdle(address asset) external view returns (uint256);
    function canonicalWrite(uint8 kind, bytes calldata row) external;
    function canonicalSend(address asset, address destination, uint256 amount) external;
    function canonicalBarrier() external;
}
interface ICanonicalPortfolio { function PORTFOLIO_VERSION() external view returns(uint256); }
interface ICanonicalVaultNFT {
    function tokenAtOrdinal(uint256 ordinal) external view returns (uint256);
    function royaltyRewards() external view returns (address);
}
interface ICanonicalMintRoyalty {
    function mintEnd() external view returns (uint64);
    function mintEndRevision() external view returns (uint64);
}
interface ICanonicalVaultRewards {
    function assetCount() external view returns (uint256);
    function assets(uint256 index) external view returns (address);
}

interface ICanonicalRecoveryRoute {
    function SCHEMA() external view returns(bytes32);
    function access() external view returns(address);
    function phase() external view returns(uint8);
    function incomingSource() external view returns(address);
    function destinationController() external view returns(address);
    function stateRoot() external view returns(bytes32);
    function exportRoot(uint256) external view returns(bytes32);
    function importRoot(uint256) external view returns(bytes32);
    function cancelledRoyaltyReturnController() external view returns(address);
}

/// @notice Immutable Vault companion. No configurable executor or delegatecall.
/// It records the finite export domain and moves only source-captured backing.
contract ZZZVaultCanonical {
    IZZZAccess public immutable access;
    ICanonicalVaultState public immutable vault;
    uint256 public originChain;
    address public originVault;
    bytes32[] public aliases;
    mapping(bytes32 => uint256) public aliasBucket;
    uint256 private nftCount;
    uint256 private groupCount;
    uint256 private aliasCount;
    address[] private backingAssets;
    uint256[] private backingAmounts;
    mapping(uint256 => bool) private released;
    mapping(uint256 => bool) private accepted;
    mapping(uint256 => uint256) private companionPrefund;
    mapping(uint256 => uint256) private importedShares;
    uint256 private cursor;
    bool private captured;
    bool private imported;
    error Unauthorized();
    error InvalidState();
    error InvalidAmount();
    error InvalidConfiguration();

    constructor(address controller, address vaultController, uint256 chain) {
        access = IZZZAccess(controller);
        if (vaultController.code.length == 0 || IZZZAccess(controller).module(Ids.VAULT) != vaultController ||
            chain == 0 || IZZZVault(vaultController).canonicalChainId() != chain ||
            ICanonicalVaultState(vaultController).ACCOUNTING_VERSION() != 7) revert InvalidState();
        vault = ICanonicalVaultState(vaultController);
        originChain = chain;
        originVault = vaultController;
    }
    receive() external payable {}
    modifier onlyVault() { if (msg.sender != address(vault)) revert Unauthorized(); _; }
    modifier onlyBudget() {
        if (msg.sender != address(vault.migrationBudget())) revert Unauthorized();
        _;
    }
    modifier onlyHandoff() {
        if (msg.sender != IZZZCanonicalAccess(address(access)).canonicalHandoff()) revert Unauthorized();
        _;
    }
    /// @notice Read-only custody checks delegated by this fixed Vault's Budget.
    /// These views cannot write ownership, approve tokens or move backing.
    function validateOwner(uint256 id,address caller,bool minted,bool activation)
        external view onlyBudget returns(address entry) {
        if (block.chainid != vault.canonicalChainId() || !minted) revert Unauthorized();
        if (activation && (vault.nftBucket(id) != 0 || !IZZZNFT(access.module(Ids.NFT)).traitsReady(id))) revert InvalidState();
        if (IZZZNFT(access.module(Ids.NFT)).ownerOf(id) == caller) return address(0);
        entry = IZZZPools(access.module(Ids.POOLS)).activationEntry();
        if (entry == address(0) || caller != entry) revert Unauthorized();
    }
    function validateContribution(uint256 id,uint256 bucket,uint256 inputUSD,uint256 inputTotal,
        uint128 minimumLiquidity,bool activation) external view onlyBudget returns(address,address,uint16) {
        Position memory p = vault.group(bucket);
        if (p.status != PositionStatus.Active ||
            IZZZMigration(access.module(Ids.MIGRATION)).activePlan(bucket) != bytes32(0)) revert InvalidState();
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
        IZZZProtocolPolicy.EntryPolicy memory entry = IZZZProtocolPolicy(access.protocolPolicy()).entryPolicy();
        if (!c.depositsEnabled || inputTotal == 0 || minimumLiquidity == 0 ||
            inputUSD < (activation ? entry.minActivationUSD : entry.minGrowthUSD) || inputUSD < c.minDepositUSD ||
            vault.contributionUSD(id) + inputUSD > c.maxPositionUSD) revert InvalidAmount();
        return(c.key.currency0,c.key.currency1,c.maxSlippageBps);
    }
    /// @notice Read-only extraction of the same holder-exit guards previously
    /// executed in Vault. Budget supplies the original module caller; this does
    /// not authorize a destination, token transfer or canonical state change.
    function validateHolderExit(uint256 id,address migrationCaller)
        external view onlyBudget returns(address token0,address token1) {
        if(!access.paused() || !access.lpExitStarted()) revert InvalidState();
        Position memory p=vault.group(id);
        if((p.status!=PositionStatus.Active && p.status!=PositionStatus.Parked) ||
            vault.bucketTotalShares(id)==0) revert InvalidState();
        PoolConfig memory c=IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
        token0=c.key.currency0;token1=c.key.currency1;
        if(token0!=address(0) || token1!=IZZZMigration(migrationCaller).currentZZZ()) revert InvalidConfiguration();
    }
    function mintIdentity(uint256 ordinal) external view returns (uint256) {
        return uint256(keccak256(abi.encode(originChain, originVault, ordinal)));
    }
    function mintPrice() external view returns(uint256) {
        return IZZZProtocolPolicy(access.protocolPolicy()).salePolicy().mintPrice;
    }
    function mintProceedsRecipient() external view returns(address) {
        return IZZZProtocolPolicy(access.protocolPolicy()).salePolicy().recipient;
    }
    /// @notice Bind the reviewed sale/VRF policy, exact collection and receiver,
    /// and its local sale-end epoch through the final proceeds callback.
    function mintPolicyFingerprint() external view returns(bytes32) {
        return _mintPolicyFingerprint(IZZZProtocolPolicy(access.protocolPolicy()));
    }
    function _mintPolicyFingerprint(IZZZProtocolPolicy policy) private view returns(bytes32) {
        address collection = access.module(Ids.NFT);
        address receiver = ICanonicalVaultNFT(collection).royaltyRewards();
        ICanonicalMintRoyalty ledger = ICanonicalMintRoyalty(receiver);
        return keccak256(abi.encode(keccak256("ZZZ_MINT_POLICY_WITH_ROYALTY_END_V2"),
            policy.mintFingerprint(),collection,receiver,ledger.mintEnd(),ledger.mintEndRevision()));
    }
    function validateMint(uint256 value,uint256 ordinal,bytes32 expectedPolicy) external view onlyVault returns (uint256,address) {
        if (block.chainid != vault.canonicalChainId()) revert InvalidState();
        IZZZProtocolPolicy policy = IZZZProtocolPolicy(access.protocolPolicy());
        IZZZProtocolPolicy.SalePolicy memory sale = policy.salePolicy();
        if(value != sale.mintPrice || expectedPolicy == bytes32(0) || expectedPolicy != _mintPolicyFingerprint(policy)) revert InvalidAmount();
        return (uint256(keccak256(abi.encode(originChain,originVault,ordinal))),sale.recipient);
    }
    function bucketIdentity(bytes32 pool) external view returns (uint256) {
        return uint256(keccak256(abi.encode(originChain, originVault, pool)));
    }
    function registerAlias(bytes32 pool, uint256 bucket) external onlyVault {
        uint256 old = aliasBucket[pool];
        if (old != 0 && old != bucket) revert InvalidState();
        if (old == 0) { aliases.push(pool); aliasBucket[pool] = bucket; }
    }
    function canonicalCapture() external onlyHandoff {
        if (IZZZCanonicalAccess(address(access)).canonicalState() != 1) revert InvalidState();
        vault.canonicalBarrier();
        _closedPortfolio();
        // A proved abort may be followed by a fresh freeze. Only snapshot caches
        // reset; ordinary shares, reservations and principal remain untouched.
        bool reset = captured || imported;
        delete backingAssets; delete backingAmounts;
        imported = false;
        nftCount = vault.sequence(); groupCount = vault.bucketCount(); aliasCount = aliases.length;
        for (uint256 i; i < groupCount; ++i) {
            uint256 id = vault.bucketAt(i);
            Position memory p = vault.group(id);
            if (p.status == PositionStatus.None) {
                if (p.lpTokenId != 0 || p.idle0 != 0 || p.idle1 != 0 || vault.bucketTotalShares(id) != 0) revert InvalidState();
            } else if (p.status != PositionStatus.Parked || p.lpTokenId != 0) revert InvalidState();
            if (IZZZMigration(access.module(Ids.MIGRATION)).activePlan(id) != bytes32(0)) revert InvalidState();
        }
        ICanonicalVaultRewards rewards = ICanonicalVaultRewards(access.module(Ids.REWARDS));
        if (rewards.assetCount() > 33) revert InvalidState();
        for (uint256 i; i < rewards.assetCount(); ++i) {
            address asset = rewards.assets(i);
            for (uint256 j; j < i; ++j) if (backingAssets[j] == asset) revert InvalidState();
            uint256 balance = ExactAsset.balance(asset,address(vault));
            if (balance < vault.totalIdle(asset)) revert InvalidState();
            backingAssets.push(asset); backingAmounts.push(balance);
            // A fresh source has zero flags; recapture/successor capture
            // clears old delivery flags without snapshotting unrelated prefunds.
            if (reset) { released[i] = false; accepted[i] = false; }
        }
        captured = true;
    }
    function canonicalSettle() external onlyHandoff { if (!captured) revert InvalidState(); }
    function canonicalCount() public view returns (uint256) {
        return 1 + groupCount + aliasCount + nftCount + backingAssets.length;
    }
    function canonicalExport(uint256 row) external view returns (bytes memory) {
        if (!captured || row >= canonicalCount()) revert InvalidState();
        if (row == 0) return abi.encode(originChain, originVault, nftCount, groupCount, aliasCount, backingAssets.length);
        --row;
        if (row < groupCount) {
            uint256 id = vault.bucketAt(row);
            return abi.encode(id, vault.group(id), vault.bucketTotalShares(id), vault.homePoolId(id),
                vault.migrationBudget().compositionEpoch(id));
        }
        row -= groupCount;
        if (row < aliasCount) return abi.encode(aliases[row], aliasBucket[aliases[row]]);
        row -= aliasCount;
        if (row < nftCount) {
            uint256 id = ICanonicalVaultNFT(access.module(Ids.NFT)).tokenAtOrdinal(row + 1);
            return abi.encode(id, vault.nftBucket(id), vault.sharesOf(id), vault.contributionUSD(id));
        }
        row -= nftCount;
        address asset = backingAssets[row];
        // Retain the exact principal/quarantine classification even when raw
        // balances subsequently increase through unsolicited transfers.
        return abi.encode(asset, backingAmounts[row], vault.totalIdle(asset));
    }
    function canonicalImport(uint256 row, bytes calldata record) external onlyHandoff {
        if (IZZZCanonicalAccess(address(access)).canonicalState() != 2 || row != cursor++) revert InvalidState();
        if (row == 0) {
            _closedPortfolio();
            if (record.length != 192) revert InvalidState();
            if (vault.sequence() != 0 || vault.bucketCount() != 0 || aliases.length != 0) revert InvalidState();
            uint256 assetCount;
            (originChain, originVault, nftCount, groupCount, aliasCount, assetCount) =
                abi.decode(record, (uint256,address,uint256,uint256,uint256,uint256));
            if (originChain == 0 || originVault == address(0) || nftCount > 1000 || groupCount > 4 || assetCount > 33) revert InvalidState();
            // Fixed length records make the complete domain independent of relay choices.
            backingAssets = new address[](assetCount); backingAmounts = new uint256[](assetCount);
            vault.canonicalWrite(0, abi.encode(nftCount));
            imported = true;
            return;
        }
        --row;
        if (row < groupCount) {
            if (record.length != 384) revert InvalidState();
            (uint256 id, Position memory p, uint256 shares, bytes32 homePool, uint64 epoch) =
                abi.decode(record, (uint256,Position,uint256,bytes32,uint64));
            if (p.status != PositionStatus.None && p.status != PositionStatus.Parked) revert InvalidState();
            if (p.lpTokenId != 0 || (p.status == PositionStatus.None &&
                (p.idle0 != 0 || p.idle1 != 0 || shares != 0))) revert InvalidState();
            if (p.status == PositionStatus.Parked) {
                // The admitted pool key supplies the actual local currencies.
                // Exact backing rows below must fund their attributed idle;
                // there is no remote/home token identity to reinterpret.
                IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
            }
            vault.canonicalWrite(2, abi.encode(id, p, shares, homePool));
            vault.migrationBudget().importComposition(id,epoch);
            return;
        }
        row -= groupCount;
        if (row < aliasCount) {
            if (record.length != 64) revert InvalidState();
            (bytes32 pool, uint256 id) = abi.decode(record, (bytes32,uint256));
            if (pool == bytes32(0) || id == 0 || aliasBucket[pool] != 0) revert InvalidState();
            aliases.push(pool); aliasBucket[pool] = id;
            vault.canonicalWrite(3, record);
            return;
        }
        row -= aliasCount;
        if (row < nftCount) {
            if (record.length != 128) revert InvalidState();
            (uint256 id, uint256 bucket, uint256 shares, uint256 contribution) = abi.decode(record, (uint256,uint256,uint256,uint256));
            if (id != uint256(keccak256(abi.encode(originChain, originVault, row + 1))) ||
                (bucket == 0 ? shares != 0 || contribution != 0 : shares == 0)) revert InvalidState();
            importedShares[bucket] += shares;
            vault.canonicalWrite(1, record);
            return;
        }
        row -= nftCount;
        if (row >= backingAssets.length) revert InvalidState();
        if (record.length != 96) revert InvalidState();
        (address asset, uint256 amount, uint256 principal) = abi.decode(record, (address,uint256,uint256));
        if (principal != vault.totalIdle(asset) || amount < principal) revert InvalidState();
        for (uint256 i; i < row; ++i) if (backingAssets[i] == asset) revert InvalidState();
        backingAssets[row] = asset; backingAmounts[row] = amount;
        companionPrefund[row] = ExactAsset.balance(asset,address(this));
    }
    function canonicalAssetCount() external view returns (uint256) { return backingAssets.length; }
    function canonicalBacking(uint256 index) external view returns (address asset, uint256 amount) {
        return (backingAssets[index], backingAmounts[index]);
    }
    function canonicalRelease(uint256 index, address destination) external onlyHandoff {
        uint8 state = IZZZCanonicalAccess(address(access)).canonicalState();
        if ((state != 1 && state != 4) || released[index] || (state == 4 && !accepted[index])) revert InvalidState();
        released[index] = true;
        vault.canonicalSend(backingAssets[index], destination, backingAmounts[index]);
    }
    function canonicalAccept(uint256 index, address) external payable onlyHandoff {
        if (msg.value != 0 || IZZZCanonicalAccess(address(access)).canonicalState() != 2 || accepted[index]) revert InvalidState();
        accepted[index] = true;
        _forward(index,false);
    }
    function canonicalRestore(uint256 index, address) external payable onlyHandoff {
        if (msg.value != 0 || IZZZCanonicalAccess(address(access)).canonicalState() != 1 || !released[index]) revert InvalidState();
        _forward(index,true);
        released[index] = false;
    }
    // Funding was transferred into this companion by canonicalRelease before
    // this zero-value acknowledgment. Prefunds cannot substitute for that row.
    function _forward(uint256 index,bool restore) private {
        address asset=backingAssets[index]; uint256 amount=backingAmounts[index];
        // Source restore follows Handoff.returnFunds' exact balance-delta check.
        // Capturing source prefunds would permit 33 dust donations to impose
        // cold storage costs on freeze. Imported successors must not reuse an
        // old importer baseline when they later become a source.
        uint256 prefund=restore?0:companionPrefund[index];
        if (ExactAsset.balance(asset,address(this)) < prefund+amount) revert InvalidState();
        ExactAsset.push(asset,address(vault),amount);
    }
    function canonicalValidate() external view {
        _closedPortfolio();
        if (imported) {
            if (cursor != canonicalCount() || vault.bucketCount() != groupCount || aliases.length != aliasCount) revert InvalidState();
            for (uint256 i; i < groupCount; ++i) {
                uint256 id = vault.bucketAt(i);
                if (importedShares[id] != vault.bucketTotalShares(id)) revert InvalidState();
            }
        } else if (!captured) revert InvalidState();
        for (uint256 i; i < backingAssets.length; ++i) {
            if (ExactAsset.balance(backingAssets[i],address(vault)) < backingAmounts[i]) revert InvalidState();
        }
    }
    function canonicalActivate() external onlyHandoff {
        if (IZZZCanonicalAccess(address(access)).canonicalState() != 2) revert InvalidState();
        _closedPortfolio();
    }
    /// @dev V5 exports only closed parked principal. The eight-word record
    /// cannot silently omit a live residual or an orphaned registered LP.
    function _closedPortfolio() private view {
        address manager = access.module(Ids.LIQUIDITY);
        if (ICanonicalPortfolio(manager).PORTFOLIO_VERSION() != 2 ||
            IZZZLiquidity(manager).activeSecondaryCount() != 0) revert InvalidState();
    }

    /// @notice Read-only ONE-hop proof for this controller's cancelled handoff.
    /// It accepts no route/recipient input and cannot move funds or set a cursor.
    function validateCancelledRoyaltyHop() external view onlyHandoff returns(address next) {
        if(access.canonicalState() != 4 || ICanonicalRecoveryRoute(msg.sender).phase() != 7) revert InvalidState();
        address previous = ICanonicalRecoveryRoute(msg.sender).cancelledRoyaltyReturnController();
        ICanonicalRecoveryRoute from = _recoveryPeer(previous);
        next = from.destinationController();
        if(IZZZAccess(previous).canonicalState() != 3 || from.phase() != 3 ||
            next == address(0) || next == previous || next == address(access) || !IZZZAccess(next).isSealed())
            revert InvalidState();
        uint8 state = IZZZAccess(next).canonicalState();
        ICanonicalRecoveryRoute to = _recoveryPeer(next);
        if((state != 0 && state != 3) || to.incomingSource() != previous ||
            (state == 0 ? to.phase() != 5 : to.phase() != 3)) revert InvalidState();
        // These domain chains are immutable after retirement/first import.
        // Later source snapshots or aborts may replace the successor's current
        // root, but cannot replace its original imported record chains.
        if(from.stateRoot() == bytes32(0)) revert InvalidState();
        for(uint8 slot;slot<6;++slot) {
            if(from.exportRoot(slot) != to.importRoot(slot)) revert InvalidState();
        }
    }
    function _recoveryPeer(address controller) private view returns(ICanonicalRecoveryRoute peer) {
        peer = ICanonicalRecoveryRoute(IZZZAccess(controller).canonicalHandoff());
        if(peer.SCHEMA() != keccak256("ZZZ_CANONICAL_SAME_CHAIN_EXACT_LP_V9") ||
            peer.access() != controller) revert InvalidState();
    }
}

