// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ExactToken} from "./ExactToken.sol";

/// @notice Native ETH is an asset identity, never an ERC20 alias. Payable ingress
/// must validate its entire declared budget before using these transfer helpers.
library ExactAsset {
    using SafeERC20 for IERC20;
    error NativeTransferFailed();

    function balance(address asset, address owner) internal view returns (uint256) {
        return asset == address(0) ? owner.balance : IERC20(asset).balanceOf(owner);
    }
    function approve(address asset, address spender, uint256 amount) internal {
        if (asset != address(0)) IERC20(asset).forceApprove(spender, amount);
    }
    function push(address asset, address to, uint256 amount) internal {
        if (asset != address(0)) ExactToken.push(asset, to, amount);
        else if (amount != 0) {
            uint256 beforeBalance = address(this).balance;
            (bool ok,) = payable(to).call{value: amount}("");
            if (!ok || address(this).balance != beforeBalance - amount) revert NativeTransferFailed();
        }
    }
}

src/libraries/ExactLPAllocation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

/// @notice Bounded whole-unit allocation to mutable NFT share weights.
/// @dev Internal engine used by accounting7 Rewards and its canonical codec.
/// The host authenticates immutable NFT ordinals, ETH/fixed-ZZZ
/// books, actual funding, ownership and atomic canonical share synchronization.
/// No token movement, authority or external call is implemented here.
library ExactLPAllocation {
    uint256 internal constant LEAVES = 1024;
    uint256 internal constant MAX_ORDINAL = 1000;
    uint256 internal constant Q = uint256(1) << 128;

    enum Asset { ETH, ZZZ }

    /// @dev Fairness phase only, never money or a fractional reserved claim.
    /// With subtree weight W>0, phase = high/Q + low/(Q*W).
    struct Carry { uint128 high; uint256 low; }
    struct Book {
        mapping(uint256 => uint256) pending;
        mapping(uint256 => Carry) carry;
        uint256 outstanding;
    }
    struct Tree {
        mapping(uint256 => uint256) weights;
        // Both books MUST settle before a shared weight changes. A caller
        // cannot supply an incomplete list or silently introduce another asset.
        Book[2] books;
    }

    error InvalidOrdinal();
    error EmptyCohort();
    error InvalidSplit();

    /// @notice Set one ordinal's weight after settling BOTH old asset paths.
    /// @dev A no-op preserves every pending unit and fairness phase. Genuine
    /// changes retain high phase and rebase only its low remainder, losing less
    /// than 1/Q phase per changed node, not bounding integer payout differences.
    /// Zero weight does not erase previously assigned leaf rights. This generic
    /// operation grants no host permission to deactivate NFTs or reuse ordinals.
    function setWeight(Tree storage tree, uint256 ordinal, uint256 weight)
        internal returns (uint256 total) {
        uint256 leaf = _leaf(ordinal);
        uint256 old = tree.weights[leaf];
        total = tree.weights[1];
        if (old == weight) return total;
        // Reject aggregate overflow before materializing any old pending path.
        total = total - old + weight;
        uint256 incoming = _settlePath(tree, tree.books[0], ordinal);
        if (incoming != 0) tree.books[0].pending[leaf] += incoming;
        incoming = _settlePath(tree, tree.books[1], ordinal);
        if (incoming != 0) tree.books[1].pending[leaf] += incoming;
        tree.weights[leaf] = weight;
        for (uint256 node = leaf >> 1; node != 0; node >>= 1) {
            uint256 beforeWeight = tree.weights[node];
            uint256 afterWeight = tree.weights[node << 1] + tree.weights[(node << 1) | 1];
            tree.weights[node] = afterWeight;
            _rebase(tree.books[0].carry[node], beforeWeight, afterWeight);
            _rebase(tree.books[1].carry[node], beforeWeight, afterWeight);
        }
    }

    /// @notice Assign funded whole units to the current weighted cohort.
    /// @dev Constant tree work; funding and aggregate liabilities belong to the
    /// host. Only outstanding balances are stored, never lifetime counters.
    function credit(Tree storage tree, Asset asset, uint256 amount) internal {
        if (amount == 0) return;
        if (tree.weights[1] == 0) revert EmptyCohort();
        Book storage book = tree.books[uint256(asset)];
        book.outstanding += amount;
        book.pending[1] += amount;
    }

    /// @notice Read one leaf's exact whole units without materialization.
    function claimable(Tree storage tree, Asset asset, uint256 ordinal)
        internal view returns (uint256 amount) {
        _leaf(ordinal);
        Book storage book = tree.books[uint256(asset)];
        uint256 node = 1;
        for (uint256 mask = LEAVES >> 1; mask != 0; mask >>= 1) {
            amount += book.pending[node];
            bool right = ((ordinal - 1) & mask) != 0;
            // Empty dormant subtrees need no division; old whole units may
            // remain at a zero-weight leaf and are read after this loop.
            if (amount != 0) {
                Carry storage c = book.carry[node];
                (uint256 left, uint256 other,,) = split(amount, tree.weights[node << 1],
                    tree.weights[node], c.high, c.low);
                amount = right ? other : left;
            }
            node = (node << 1) | (right ? 1 : 0);
        }
        amount += book.pending[node];
    }

    /// @notice Remove one leaf's whole units for a host-authenticated payout.
    /// @dev At most ten pushes. No owner, receiver or token is chosen here.
    function take(Tree storage tree, Asset asset, uint256 ordinal)
        internal returns (uint256 amount) {
        uint256 leaf = _leaf(ordinal);
        Book storage book = tree.books[uint256(asset)];
        amount = _settlePath(tree, book, ordinal);
        uint256 stored = book.pending[leaf];
        amount += stored;
        if (stored != 0) delete book.pending[leaf];
        if (amount != 0) book.outstanding -= amount;
    }

    function totalWeight(Tree storage tree) internal view returns (uint256) { return tree.weights[1]; }
    function weightOf(Tree storage tree, uint256 ordinal) internal view returns (uint256) { return tree.weights[_leaf(ordinal)]; }
    function outstanding(Tree storage tree, Asset asset) internal view returns (uint256) { return tree.books[uint256(asset)].outstanding; }

    /// @notice Full-precision whole-unit split with bounded fairness phase.
    /// @dev Fixed weights preserve exact batching/materialization behavior.
    /// The two carry folds avoid evaluating an overflowing remainder sum.
    function split(uint256 amount, uint256 leftWeight, uint256 weight, uint128 high, uint256 low)
        internal pure returns (uint256 left, uint256 right, uint128 nextHigh, uint256 nextLow) {
        if (weight == 0 || leftWeight > weight || low >= weight) revert InvalidSplit();
        left = Math.mulDiv(amount, leftWeight, weight);
        uint256 remainder = mulmod(amount, leftWeight, weight);
        uint256 phase = Math.mulDiv(remainder, Q, weight);
        nextLow = mulmod(remainder, Q, weight);
        uint256 gap = weight - low;
        if (nextLow >= gap) {
            ++phase;
            nextLow -= gap;
        } else nextLow += low;
        phase += uint256(high); // <2*Q, even when the low fold made phase=Q.
        if (phase >= Q) { ++left; phase -= Q; }
        nextHigh = uint128(phase);
        right = amount - left;
    }

    /// @dev The selected share stays in memory until its leaf. Only sibling
    /// shares need storage, avoiding temporary selected-child writes/deletes.
    /// No external call can observe this transient in-memory accounting.
    function _settlePath(Tree storage tree, Book storage book, uint256 ordinal)
        private returns (uint256 incoming) {
        uint256 node = 1;
        for (uint256 mask = LEAVES >> 1; mask != 0; mask >>= 1) {
            uint256 stored = book.pending[node];
            incoming += stored;
            if (stored != 0) delete book.pending[node];
            bool goRight = ((ordinal - 1) & mask) != 0;
            if (incoming != 0) {
                Carry storage c = book.carry[node];
                (uint256 left, uint256 right, uint128 high, uint256 low) =
                    split(incoming, tree.weights[node << 1], tree.weights[node], c.high, c.low);
                uint256 sibling = goRight ? left : right;
                if (sibling != 0) book.pending[(node << 1) | (goRight ? 0 : 1)] += sibling;
                c.high = high; c.low = low;
                incoming = goRight ? right : left;
            }
            node = (node << 1) | (goRight ? 1 : 0);
        }
    }

    function _rebase(Carry storage carry, uint256 oldWeight, uint256 newWeight) private {
        uint256 low = carry.low;
        if (low == 0) return;
        // Keep high even through an empty cohort. Clearing it would permit
        // genuine weight changes to repeatedly restart a whole-unit phase.
        carry.low = oldWeight == 0 || newWeight == 0 ? 0 : Math.mulDiv(low, newWeight, oldWeight);
    }

    function _leaf(uint256 ordinal) private pure returns (uint256) {
        if (ordinal == 0 || ordinal > MAX_ORDINAL) revert InvalidOrdinal();
        return LEAVES + ordinal - 1;
    }
}

src/libraries/ExactRoyaltyAllocation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @notice Exact raw-unit allocation to permanent rarity-weight tickets.
/// @dev Internal code only: no deployed helper or external authority. Tags hold
/// outstanding units, not lifetime accrual, so paid units leave the tree.
library ExactRoyaltyAllocation {
    uint256 internal constant MAX_TICKETS = 3000;
    uint256 private constant FIRST_LEAF = 4096;
    struct Book { mapping(uint256 => uint256) pending; }
    error InvalidAllocation();

    /// @notice Allocate every unit to the captured eligible prefix, rotating
    /// indivisible remainders. Fixed-prefix batching preserves final allocation.
    function credit(Book storage book,uint256 amount,uint256 weight,uint256 cursor)
        internal returns(uint256 nextCursor) {
        _validate(weight,cursor);
        uint256 quotient = amount / weight;
        uint256 remainder = amount % weight;
        if(quotient != 0) _add(book,1,weight,quotient);
        uint256 first = remainder < weight-cursor ? remainder : weight-cursor;
        if(first != 0) _add(book,cursor+1,cursor+first,1);
        uint256 wrapped = remainder-first;
        if(wrapped != 0) _add(book,1,wrapped,1);
        // Both terms are<weight<=3000; never add amount to cursor.
        nextCursor = cursor+remainder;
        if(nextCursor >= weight) nextCursor -= weight;
    }

    /// @notice Add units per ticket to one bounded inclusive interval.
    function addRange(Book storage book,uint256 low,uint256 high,uint256 delta) internal {
        _interval(low,high);
        if(delta != 0) _add(book,low,high,delta);
    }

    function _add(Book storage book,uint256 low,uint256 high,uint256 delta) private {
        uint256 left = FIRST_LEAF-1+low;
        uint256 right = FIRST_LEAF-1+high;
        // Standard inclusive dyadic cover. Only endpoints advance, so each
        // level uses at most two tags and at most13levels are visited.
        while(left <= right) {
            if((left & 1) != 0) book.pending[left++] += delta;
            if((right & 1) == 0) book.pending[right--] += delta;
            left >>= 1;
            right >>= 1;
        }
    }

    /// @notice Read a ticket without changing any tag or recipient entitlement.
    function viewTicket(Book storage book,uint256 ticket) internal view returns(uint256 amount) {
        _interval(ticket,ticket);
        uint256 node = FIRST_LEAF-1+ticket;
        while(node != 0) {
            amount += book.pending[node];
            node >>= 1;
        }
    }

    /// @notice Remove exactly one ticket's outstanding units. Carry selected
    /// tags in memory and materialize only the sibling's share; no external
    /// call can observe the temporary path. Other tickets retain all rights.
    function takeTicket(Book storage book,uint256 ticket) internal returns(uint256 amount) {
        _interval(ticket,ticket);
        uint256 node = 1;
        uint256 path = ticket-1;
        uint256 carry;
        for(uint256 mask=FIRST_LEAF>>1;mask != 0;mask >>= 1) {
            uint256 tag = book.pending[node];
            if(tag != 0) {
                carry += tag;
                delete book.pending[node];
            }
            if((path & mask) == 0) {
                if(carry != 0) book.pending[(node<<1)|1] += carry;
                node <<= 1;
            } else {
                if(carry != 0) book.pending[node<<1] += carry;
                node = (node<<1)|1;
            }
        }
        uint256 leaf = book.pending[node];
        amount = leaf + carry;
        if(leaf != 0) delete book.pending[node];
    }

    /// @notice Preview a pending allocation's exact units for an NFT interval.
    /// Future tickets beyond the captured eligible prefix receive zero.
    function previewShare(uint256 amount,uint256 weight,uint256 cursor,
        uint256 firstTicket,uint256 lastTicket) internal pure returns(uint256 value) {
        _validate(weight,cursor);
        _interval(firstTicket,lastTicket);
        uint256 count = _overlap(firstTicket,lastTicket,1,weight);
        value = (amount/weight)*count;
        uint256 remainder = amount%weight;
        uint256 first = remainder < weight-cursor ? remainder : weight-cursor;
        uint256 wrapped = remainder-first;
        if(first != 0) value += _overlap(firstTicket,lastTicket,cursor+1,cursor+first);
        if(wrapped != 0) value += _overlap(firstTicket,lastTicket,1,wrapped);
    }

    function _overlap(uint256 low,uint256 high,uint256 first,uint256 last)
        private pure returns(uint256) {
        if(low > last || high < first) return 0;
        uint256 start = low > first ? low : first;
        uint256 end = high < last ? high : last;
        return end-start+1;
    }
    function _validate(uint256 weight,uint256 cursor) private pure {
        if(weight == 0 || weight > MAX_TICKETS || cursor >= weight) revert InvalidAllocation();
    }
    function _interval(uint256 low,uint256 high) private pure {
        if(low == 0 || low > high || high > MAX_TICKETS) revert InvalidAllocation();
    }
}

src/libraries/ExactToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @notice Strict transfers for conventional non-rebasing, non-taxed ERC20s.
/// Balance checks do not prove a token will remain non-malicious in the future.
library ExactToken {
    using SafeERC20 for IERC20;
    error UnsupportedToken(address token);
    function pull(address token, address from, uint256 amount) internal {
        if (amount == 0) return;
        uint256 beforeBalance = IERC20(token).balanceOf(address(this));
        uint256 beforeSender = IERC20(token).balanceOf(from);
        IERC20(token).safeTransferFrom(from, address(this), amount);
        if (IERC20(token).balanceOf(address(this)) != beforeBalance + amount ||
            IERC20(token).balanceOf(from) + amount != beforeSender) revert UnsupportedToken(token);
    }
    function push(address token, address to, uint256 amount) internal {
        if (amount == 0) return;
        uint256 beforeSender = IERC20(token).balanceOf(address(this));
        uint256 beforeRecipient = IERC20(token).balanceOf(to);
        IERC20(token).safeTransfer(to, amount);
        if (IERC20(token).balanceOf(address(this)) + amount != beforeSender ||
            IERC20(token).balanceOf(to) != beforeRecipient + amount) revert UnsupportedToken(token);
    }
}

